/* n = número · r = rúbrica · t = texto */
const LEY_10797 = [{"n":1,"r":"JUICIO PREVIO","t":"JUICIO PREVIO. Ninguna persona podrá ser penada sin juicio previo fundado en ley anterior al hecho del proceso. Regirán de manera directa todas las garantías y derechos consagrados en la Constitución Nacional, en Tratados Internacionales y en la Constitución de la Provincia.-"},{"n":2,"r":"PERSECUCIÓN PENAL ÚNICA","t":"PERSECUCIÓN PENAL ÚNICA. Ninguna persona puede ser perseguida penalmente por el mismo hecho más de una vez, aunque se modifique su calificación legal o se afirmen nuevas circunstancias. No se podrán reabrir los procesos fenecidos, salvo los casos de revisión de sentencia a favor del condenado.-"},{"n":3,"r":"JUECES NATURALES Y JURADOS","t":"JUECES NATURALES Y JURADOS. Ninguna persona podrá ser juzgada por otras juezas o jueces que los instituidos por la Ley antes del hecho objeto del proceso y designados de acuerdo con la Constitución Nacional y Provincial. La competencia y el procedimiento para el juicio por jurados en casos criminales se ajustarán a las normas de la Constitución Nacional, la Constitución Provincial, este Código y a la Ley de Jurados.-"},{"n":4,"r":"PARTICIPACIÓN CIUDADANA","t":"PARTICIPACIÓN CIUDADANA. Las ciudadanas y ciudadanos participarán en la administración de la justicia penal conforme a lo previsto en los Artículos 24%, 75%, Inciso 12) y 118) de la Constitución de la Nación, Artículo169* de la Constitución Provincial y en las normas de este Código, como de otras leyes.-"},{"n":5,"r":"INDEPENDENCIA E IMPARCIALIDAD","t":"INDEPENDENCIA E IMPARCIALIDAD. Las juezas y jueces deben actuar con imparcialidad en sus decisiones. Se debe garantizar la independencia de las juezas y jueces, conjueces, juezas o jueces de paz y jurados de toda injerencia externa de las otras funciones del Estado y de los demás integrantes de la Función Judicial. Los parámetros jurídicos vigentes serán la única sujeción legalmente impuesta a las juezas o jueces en el ejercicio de la función jurisdiccional a su cargo. En caso de interferencia en el ejercicio de su función, las juezas o jueces informarán al Consejo de la Magistratura sobre los hechos que afecten su independencia y solicitará las medidas necesarias para su resguardo.- PA mo pa] ¡ES COPIA FicL DeL ORIGINAL ' uN 1 0 = 7 9 7"},{"n":6,"r":"SEPARACIÓN DE FUNCIONES","t":"SEPARACIÓN DE FUNCIONES. Las o los fiscales no pueden realizar actos jurisdiccionales y las juezas o jueces no pueden realizar actos de investigación o que impliquen el impulso de la persecución penal o suplan la actividad de las partes. La delegación de funciones jurisdiccionales en funcionarios o empleados subalternos tornará inválidas las actuaciones realizadas y será considerado causal de mal desempeño de las funciones a los efectos del proceso de remoción.-"},{"n":7,"r":"PRINCIPIOS DEL PROCESO","t":"PRINCIPIOS DEL PROCESO. En el proceso se observarán los principios de oralidad, publicidad, contradicción, concentración, inmediación, simplificación y celeridad, conforme a lo previsto en el Artículo 169\" de la Constitución Provincial.-"},{"n":8,"r":"ESTADO DE INOCENCIA Y DUDA","t":"ESTADO DE INOCENCIA Y DUDA. Nadie podrá ser considerado ni tratado como culpable mientras una sentencia firme de jueza o juez competente, dictada previo proceso legal, no lo declare tal. En caso de duda, deberá decidirse lo que sea más favorable a la persona imputada. Siempre se aplicará la Ley Penal más benigna para el imputado. Las juezas o jueces y el Ministerio Público Fiscal no deben presentar al imputado como culpable ni brindar información en ese sentido a los medios de comunicación social, no obstante, se pueden publicar los datos indispensables cuando sea necesario para lograr su identificación o captura.-"},{"n":9,"r":"LIBERTAD EN EL PROCESO","t":"LIBERTAD EN EL PROCESO. La persona imputada permanecerá en libertad durante el proceso. Excepcionalmente, podrá restringirse su libertad, fundándose en la existencia real de peligro de fuga u obstaculización del proceso. Nadie puede ser encarcelado sin que existan elementos de prueba suficientes para atribuirle un delito reprimido con pena privativa de libertad, conforme a las reglas de este Código.-"},{"n":10,"r":"","t":"DEFENSA EN JUICIO, El derecho de defensa es inviolable e irrenunciable y podrá ejercerse plenamente desde el inicio de la persecución. Ninguna persona podrá ser obligada a declarar en contra de sí misma. El ejercicio del derecho a guardar silencio no podrá ser valorado como una admisión de los hechos o como indicio de culpabilidad. Toda persona tiene derecho a la asistencia y representación de la defensa técnica letrada efectiva, que será garantizada por el Estado. En caso de colisión, primará la voluntad de la persona imputada expresada clara y libremente. -"},{"n":11,"r":"PROHIBICIÓN DE INCOMUNICACIÓN Y DEL SECRETO","t":"PROHIBICIÓN DE INCOMUNICACIÓN Y DEL SECRETO. Está prohibida la incomunicación de la persona imputada y el secreto de las actuaciones. Sólo en los casos y por los motivos autorizados por este Código se podrá disponer por la jueza o juez de garantías y a pedido de parte, la reserva de algún acto. Todas las audiencias serán públicas, salvo las excepciones expresamente previstas en este Código.-"},{"n":12,"r":"DERECHOS DE LA VÍCTIMA","t":"DERECHOS DE LA VÍCTIMA. La víctima tiene derecho a una tutela Judicial efectiva, a la protección integral de su persona, su familia y sus bienes frente a las consecuencias del delito, a participar del proceso penal en forma autónoma, conforme a lo establecido en el Artículo 31” de la Constitución Provincial. Las autoridades no podrán, bajo pretexto alguno, dejar de recibir sus denuncias o reclamos y de poner inmediatamente en funcionamiento los mecanismos legales previstos para su tutela efectiva.- E."},{"n":13,"r":"LEGALIDAD Y CARGA DE LA PRUEBA","t":"LEGALIDAD Y CARGA DE LA PRUEBA. Los elementos de prueba sólo tendrán valor si han sido obtenidos por medios lícitos y que respeten las reglas de su adquisición procesal. Incumbe a la acusación la carga de la prueba y en ningún caso podrá invertirse esta carga probatoria.-"},{"n":14,"r":"SOLUCIÓN DEL CONFLICTO","t":"SOLUCIÓN DEL CONFLICTO. La imposición de la pena es el último recurso. Las juezas o jueces y la fiscalía procurarán resolver el conflicto surgido a consecuencia del hecho punible de conformidad con los principios contenidos en las leyes, dando preferencia a las soluciones que mejor se adecuen al restablecimiento de la armonía entre sus protagonistas y la paz social.-"},{"n":15,"r":"JUSTICIA EN UN PLAZO RAZONABLE","t":"JUSTICIA EN UN PLAZO RAZONABLE. Toda persona tiene derecho a una decisión judicial definitiva en tiempo razonable, conforme a los plazos establecidos en este Código. El retardo en dictar resoluciones o las dilaciones indebidas, cuando sean reiteradas, constituirá falta grave.-"},{"n":16,"r":"IGUALDAD DE TRATO","t":"IGUALDAD DE TRATO. Las juezas o jueces no podrán mantener ninguna clase de comunicación con las partes o sus abogados sobre los asuntos sometidos a su conocimiento, sin dar previo aviso a todas ellas.-"},{"n":17,"r":"DESARROLLO Y APLICACIÓN PROGRESIVA","t":"DESARROLLO Y APLICACIÓN PROGRESIVA. Las juezas o jueces procurarán extender los principios y garantías a los casos y situaciones no previstos expresamente, conforme a una interpretación progresiva.-"},{"n":18,"r":"INOBSERVANCIA DE LAS GARANTÍAS","t":"INOBSERVANCIA DE LAS GARANTÍAS. La inobservancia de un principio o garantía no podrá hacerse valer en perjuicio de quien se encuentra amparado por ella ni retrotraer el procedimiento a etapas anteriores en contra de su voluntad.-"},{"n":19,"r":"APRECIACIÓN DE LAS PRUEBAS","t":"APRECIACIÓN DE LAS PRUEBAS. Las pruebas serán valoradas por las juezas o jueces según la sana crítica, observando las reglas de la lógica, los conocimientos científicos y las máximas de la experiencia. Las juezas o jueces formarán su convicción de la valoración conjunta y armónica de toda la prueba producida, explicando con argumentos de carácter objetivo su decisión. En el caso de juicio por jurados, los jurados apreciarán las pruebas a través de la deliberación conjunta y detallada, según la sana razón y el sentido común.-"},{"n":20,"r":"DELIBERACIÓN","t":"DELIBERACIÓN. Los jurados, juezas, jueces o conjueces deliberarán en todos los casos antes de tomar una decisión. La deliberación será inmediata, continua, integral y requerirá la intervención activa de cada uno de sus miembros. Cuando esté prevista la deliberación previa, su ausencia o su reemplazo por la mera circulación de votos tornará nula la decisión.-"},{"n":21,"r":"SENTENCIA","t":"SENTENCIA. La sentencia debe ser definitiva, absolviendo o condenando al imputado. Las juezas o jueces no podrán abstenerse de decidir so pretexto de oscuridad o ambigúedad de las leyes ni retardar indebidamente alguna decisión ni utilizar los fundamentos de las decisiones para realizar declaraciones o afirmaciones que no incidan en la decisión.-"},{"n":22,"r":"MOTIVACIÓN","t":"MOTIVACIÓN. Las decisiones dictadas por juezas o jueces técnicos deben expresar los fundamentos de hecho y de derecho en que se basen. La fundamentación no se puede reemplazar con la simple relación de documentos, afirmaciones dogmáticas, ficciones legales, expresiones rituales o apelaciones morales. PE AAA OSDIA EL REL Prem | LA RIOJA : Cuando se trate de sentencias dictadas por tribunales colegiados, la deliberación conjunta es obligatoria; cada uno de sus miembros debe fundar individualmente su voto, salvo que adhiera a los motivos expuestos por otro miembro. La adhesión a los fundamentos de otro no permite omitir la deliberación.- ARTÍCULO 23%. PROTECCIÓN DE LA INTIMIDAD Y PRIVACIDAD. En los procedimientos se debe respetar el derecho a la intimidad y a la privacidad de la persona imputada y de cualquier otra persona, en especial la libertad de conciencia, el domicilio, la correspondencia, los papeles privados y las comunicaciones de toda índole. Sólo con autorización de jueza o juez y bajo las reglas de este Código podrá afectarse este derecho.-"},{"n":23,"r":"PROTECCIÓN DE LA INTIMIDAD Y PRIVACIDAD","t":"PROTECCIÓN DE LA INTIMIDAD Y PRIVACIDAD. En los procedimientos se debe respetar el derecho a la intimidad y a la privacidad de la persona imputada y de cualquier otra persona, en especial la libertad de conciencia, el domicilio, la correspondencia, los papeles privados y las comunicaciones de toda índole. Sólo con autorización de jueza o juez y bajo las reglas de este Código podrá afectarse este derecho.-"},{"n":24,"r":"DERECHO AL RECURSO","t":"DERECHO AL RECURSO. Toda persona tiene derecho a recurrir la sanción penal que se le haya impuesto ante otra jueza o juez o tribunal con amplia capacidad para su revisión.-"},{"n":25,"r":"CONDICIONES CARCELARIAS","t":"CONDICIONES CARCELARIAS. Está prohibido alojar a personas privadas de libertad en lugares no habilitados o en sitios que no reúnan las mínimas condiciones de salubridad o más allá del cupo autorizado. Toda medida que so pretexto de precaución conduzca a mortificar a presos o detenidos hará responsable a la jueza o juez que la autorice o consienta y a los funcionarios que la ordenen, apliquen o consientan.-"},{"n":26,"r":"TRATO DIGNO - DIVERSIDAD CULTURAL","t":"TRATO DIGNO - DIVERSIDAD CULTURAL. Toda persona tiene derecho a reclamar un trato digno de los organismos penales pertenecientes a la administración de justicia y en dependencias policiales. Asimismo, toda persona tiene derecho a: 1.- Ser atendida por todos los intervinientes en la administración de justicia, de forma personalizada, respetuosa y adaptada a sus circunstancias psicológicas, sociales y culturales. 2.- Exigir que las actuaciones judiciales en las que resulte necesaria su comparecencia se celebren con la máxima puntualidad. 3.- Recibir las comunicaciones de los órganos judiciales en un lenguaje claro y sencillo, con información suficiente de las consecuencias derivadas de su incumplimiento. 4.- Recibir respuesta a sus solicitudes. En este caso, las autoridades y funcionarios deben exponer por escrito, a toda persona que realice una solicitud, los motivos por los que se deniega el acceso a una información de carácter procesal. Cuando se trate de hechos cometidos por miembros de un pueblo originario se aplicará en forma directa el Artículo 202\" del Convenio N? 169 de la Organización Internacional del Trabajo -OIT.- . ¡(ES PRO PL PE ASIAN ! ¡59 Lua mes DEL ORIGINAL"},{"n":27,"r":"INTERPRETACIÓN RESTRICTIVA","t":"INTERPRETACIÓN RESTRICTIVA. Todas las normas que coarten la libertad personal de la persona imputada o limiten el ejercicio de sus derechos se interpretarán restrictivamente. La analogía sólo está permitida en cuanto favorezca la libertad de la persona imputada o el ejercicio de sus derechos y facultades. Toda interpretación y decisión deberá adoptar una perspectiva de género y respetar la interculturalidad.- ) TÍTULO Il JURISDICCIÓN, COMPETENCIA Y SUJETOS PROCESALES CAPÍTULO | JURISDICCIÓN Y COMPETENCIA"},{"n":28,"r":"JURISDICCIÓN","t":"JURISDICCIÓN. La jurisdicción penal será ejercida por las juezas o jueces y jurados populares designados de acuerdo con la Constitución y la ley, y se extenderá al conocimiento de los delitos cometidos en el territorio de la Provincia y a aquellos cuyos efectos se produzcan en él, excepto los de jurisdicción federal. La jurisdicción penal será irrenunciable e indelegable.-"},{"n":29,"r":"COMPETENCIA Y EXTENSIÓN","t":"COMPETENCIA Y EXTENSIÓN. La competencia sólo puede ser fijada por Ley. No obstante, la competencia territorial de las juezas o jueces con funciones de juicio no podrá ser objetada ni modificada de oficio una vez fijada la audiencia. Las juezas o jueces tendrán competencia en todo el territorio de la Provincia, ello sin perjuicio que, por razones organizativas, se establezca una fijación territorial sobre los delitos cometidos dentro de la circunscripción judicial en la que ejerza sus funciones o cuyos efectos se produzcan en ella. En caso de que no haya juezas o jueces en la jurisdicción podrá intervenir una jueza o un juez de otra jurisdicción, quien será previamente sorteado e intervendrá en el acto procesal requerido. Los juicios por jurados se realizarán en el lugar en que se hubiera cometido el hecho. Excepcionalmente, cuando un hecho hubiera conmocionado a una comunidad de tal modo que no pudiera razonablemente obtenerse un jurado imparcial, la jueza o juez podrá disponer a pedido de parte que el juicio se lleve a cabo en otra circunscripción judicial. La prórroga de jurisdicción en el caso señalado se decidirá por sorteo en audiencia pública.-"},{"n":30,"r":"VARIOS PROCESOS","t":"VARIOS PROCESOS. Cuando a una persona se le imputen dos o más delitos, el Ministerio Público Fiscal podrá acumular los hechos y procesarlos en un único legajo o tramitarlos simultáneamente. La decisión se notificará a la defensa y en la audiencia de formulación de cargos la decisión fiscal podrá ser revisada por la jueza o juez de control si la defensa formaliza oposición. Si se tramitaren varios hechos en forma conjunta será competente el Tribunal al que le corresponda juzgar el delito más grave o siendo de la misma gravedad, el que primero intervino.-"},{"n":31,"r":"JURISDICCIONES ESPECIALES","t":"JURISDICCIONES ESPECIALES. PRIORIDAD DE JUZGAMIENTO., Si a una persona se le imputare un delito de jurisdicción provincial y otro de jurisdicción federal, el orden del juzgamiento se regirá por la Ley Nacional. Del mismo modo se 7 AAA A so ¿ES Ha PE ARA | ¡ES COPIA FIEL DEL ORIGINAL ió - 10.797 procederá en el caso de delitos conexos. No obstante, el proceso de jurisdicción provincial podrá sustanciarse simultáneamente con el otro, siempre que no se obstaculice el ejercicio de las respectivas jurisdicciones o la defensa del imputado. Las fiscalías provinciales y federales podrán acordar trabajar en conjunto.-"},{"n":32,"r":"COMPETENCIA DURANTE LA INVESTIGACIÓN","t":"COMPETENCIA DURANTE LA INVESTIGACIÓN. Dentro de una misma circunscripción judicial todas las juezas o jueces penales serán competentes para resolver las peticiones de las partes sin perjuicio de las normas prácticas de distribución del trabajo que se establezcan. Cuando la fiscalía investigue en forma conjunta delitos cometidos en distintas : circunscripciones judiciales entenderá la jueza o juez de la circunscripción correspondiente al hecho más grave o donde se desarrolle la investigación principal, salvo cuando la persona imputada se oponga porque se dificulte el ejercicio de la defensa O se produzca retardo procesal.-"},{"n":33,"r":"EFECTOS","t":"EFECTOS. El planteamiento de una cuestión de competencia no suspenderá la faz preparatoria ni la audiencia de control de la acusación, pero sí suspende la etapa del juicio.-"},{"n":34,"r":"UNIÓN Y SEPARACIÓN DE JUICIOS","t":"UNIÓN Y SEPARACIÓN DE JUICIOS. Los juicios se realizarán en la circunscripción judicial donde se produjeron los hechos. No obstante, las partes podrán solicitar su unificación y la jueza o juez de la etapa intermedia decidirá la realización separada o conjunta, según la naturaleza de los casos, para evitar el retardo procesal o para facilitar el ejercicio de la defensa.- CAPÍTULO Il TRIBUNALES COMPETENTES"},{"n":35,"r":"ÓRGANOS","t":"ÓRGANOS. Serán órganos jurisdiccionales los siguientes: 1.- Tribunal Superior de Justicia. 2.- Tribunal de Impugnación Penal. 3.- Colegio de Jueces Penales, integrado por las actuales juezas y jueces de Cámara de Juicio; juezas y jueces de Instrucción; y por juezas y jueces de Paz Letrados en las circunscripciones judiciales que por Ley se determinen. 4.- Tribunales de Jurados. 5.- Jueza o juez de Ejecución Penal.-"},{"n":36,"r":"TRIBUNAL SUPERIOR DE JUSTICIA","t":"TRIBUNAL SUPERIOR DE JUSTICIA. El Superior Tribunal de Justicia será competente para conocer: 1.- De la impugnación extraordinaria y de la queja por denegación de impugnación extraordinaria. 2.- De la revisión de una sentencia firme. A A ANA ta] z < my a fl ¡ES COPIA Pio ORIGINAL! 7 A . 10.797 3.- De la recusación de un miembro del Tribunal de Impugnación. 4.- De la competencia establecida en el Artículo 164% de la Constitución Provincial.-"},{"n":37,"r":"TRIBUNAL DE IMPUGNACIÓN PENAL","t":"TRIBUNAL DE IMPUGNACIÓN PENAL. El Tribunal de Impugnación Penal será competente, en todo el territorio de la provincia, para conocer: 1.- De las impugnaciones ordinarias contra las sentencias definitivas. 2.- De las impugnaciones ordinarias de las sentencias de los casos que tramitan bajo las reglas del sistema anterior y que aún no han tenido revisión judicial. 3.- De la revisión de la prisión preventiva. 4.- Dela revisión de una sentencia firme.-"},{"n":38,"r":"COLEGIO DE JUECES PENALES","t":"COLEGIO DE JUECES PENALES. El Colegio de Jueces Penales tendrá a su cargo las siguientes funciones: 1.- Tribunal de Juicio individual, colegiado o con jurados. 2.- De Garantías. 3.- De Revisión Ordinaria de toda decisión recurrible, con exclusión de la competencia asignada al Tribunal de Impugnación Penal. Será la Oficina Judicial la que se ocupará, en cada jurisdicción, de administrar los recursos y designar a las juezas o jueces en cada caso, para una adecuada prestación del servicio de justicia, acorde a los parámetros establecidos en la Ley Orgánica Judicial. 1.- Función de Tribunal de Juicio y Tribunales de Jurados. Los tribunales de Juicio serán unipersonales y serán competentes para conocer: a) La sustanciación del juicio en los delitos de acción privada y en todos aquellos que no estén reprimidos con pena privativa de libertad. b) En aquellos delitos reprimidos con pena privativa de libertad de hasta diez (10) - años o cuando el imputado o su defensor requieran la integración colegiada. c) En aquellos casos establecidos en la Ley Especial de Juicio por Jurados o procedimientos abreviados. En los casos en que la pena privativa de libertad del delito a juzgar supere los diez (10) años, el juicio será realizado en forma obligatoria frente a un tribunal constituido por tres (3) jueces. : 2.- Función de Control y Garantías. Corresponde a las juezas o jueces con función de Garantías: A A DO E ME SIRIA | ES COPIA Fic. DEL UHAANAL] LA RIOJA j a.- El control de la investigación y de todas las decisiones jurisdiccionales que se deban tomar durante la etapa preparatoria, intermedia o preparatoria de juicio, hasta la redacción del auto de apertura a juicio. b.- Del procedimiento abreviado, en los casos y forma prevista en este Código. C.- De las solicitudes que se hagan durante el período de suspensión del juicio a prueba, de su revocación o de la decisión que disponga la extinción de la acción penal. 3) Juezas o Jueces con Función de Revisión. Corresponde al Colegio de Jueces Penales la revisión horizontal de toda decisión, con excepción de la revisión de las decisiones que le competen al Tribunal de Impugnación Penal. La revisión será unipersonal y quedará a cargo de la jueza o juez que determine la Oficina Judicial.-"},{"n":39,"r":"JUEZA O JUEZ CON FUNCIONES DE EJECUCIÓN","t":"JUEZA O JUEZ CON FUNCIONES DE EJECUCIÓN. La jueza o juez con funciones de ejecución tiene a su cargo: 1.- Controlar que se respeten todas las garantías constitucionales e instrumentos internacionales de derechos humanos en el trato otorgado a los condenados y personas sometidas a medidas de seguridad. En los casos en que tuviere conocimiento de la violación de una garantía en relación a una persona sometida a prisión preventiva pondrá de inmediato la situación a conocimiento del juez o jueza que ordenó la medida. 2.- Practicar el cómputo de pena fijando la fecha en que finalizará la condena, y todo aquel instituto que implique un egreso transitorio o definitivo, de conformidad con la Ley de Ejecución Penal. 3.- Controlar el cumplimiento efectivo de las sentencias de condena. 4.- Resolver todos los planteos que se susciten en el período de ejecución de las penas y medidas curativas o educativas. 5.- Resolver los recursos que se presenten contra las decisiones de la administración penitenciaria. 6.- Visitar periódicamente los establecimientos donde se encuentren personas privadas de su libertad, a su disposición. 7.- Dejar sin efecto una pena o modificar las condiciones de su cumplimiento cuando entre en vigencia una Ley Penal más benigna. 8.- Realizar la unificación de condenas o penas que se adviertan durante la ejecución de la pena.-"},{"n":40,"r":"COLEGIO DE JUEZAS O JUECES","t":"COLEGIO DE JUEZAS O JUECES. Todas las juezas o jueces, salvo los que integran el Tribunal Superior de Justicia, el Tribunal de Impugnación y la jueza o juez de Ejecución Penal, se organizarán en Colegios de Juezas o Jueces. La Ley Orgánica de la Justicia Penal establecerá el número, el mecanismo de asignación de casos y la forma de integración de los Colegios para toda la Provincia.- en [ES COPIA FIEL DEL ORIGINAL | = A ARTÍCULO 41?.- OFICINA JUDICIAL. Los Colegios de Juezas o Jueces serán asistidos por una Oficina Judicial, cuya composición y funcionamiento será establecido por la Ley Orgánica de la Justicia Penal. Su director o directora deberá organizar las audiencias, dictar las resoluciones de mero trámite ordenar las comunicaciones y emplazamientos, disponer la custodia de objetos secuestrados en los casos que corresponda, llevar los registros y estadísticas, dirigir el personal auxiliar, informar a las partes y colaborar en todos los trabajos materiales que el juez o jueza o el tribunal le indiquen. A tal fin, deberá confeccionar una carpeta judicial donde asentará la actividad que realice para cada uno de los casos, bajo el principio de desformalización. La directora o el Director de la Oficina Judicial debe procurar que se fijen audiencias en el menor tiempo posible. Está prohibida la delegación de tareas jurisdiccionales en los integrantes de la Oficina Judicial, en su caso, tornará inválidas las actuaciones realizadas, será considerada falta grave y causal de mal desempeño.- CAPÍTULO III . MOTIVOS DE EXCUSACIÓN Y RECUSACIÓN"},{"n":41,"r":"OFICINA JUDICIAL","t":"OFICINA JUDICIAL. Los Colegios de Juezas o Jueces serán asistidos por una Oficina Judicial, cuya composición y funcionamiento será establecido por la Ley Orgánica de la Justicia Penal. Su director o directora deberá organizar las audiencias, dictar las resoluciones de mero trámite ordenar las comunicaciones y emplazamientos, disponer la custodia de objetos secuestrados en los casos que corresponda, llevar los registros y estadísticas, dirigir el personal auxiliar, informar a las partes y colaborar en todos los trabajos materiales que el juez o jueza o el tribunal le indiquen. A tal fin, deberá confeccionar una carpeta judicial donde asentará la actividad que realice para cada uno de los casos, bajo el principio de desformalización. La directora o el Director de la Oficina Judicial debe procurar que se fijen audiencias en el menor tiempo posible. Está prohibida la delegación de tareas jurisdiccionales en los integrantes de la Oficina Judicial, en su caso, tornará inválidas las actuaciones realizadas, será considerada falta grave y causal de mal desempeño.- CAPÍTULO III . MOTIVOS DE EXCUSACIÓN Y RECUSACIÓN"},{"n":42,"r":"MOTIVOS","t":"MOTIVOS. Las juezas o jueces podrán apartarse o ser recusados por las partes, fundadamente, cuando existan motivos que puedan afectar su imparcialidad.-"},{"n":43,"r":"EXCUSACIÓN","t":"EXCUSACIÓN. La jueza o juez que se excuse remitirá las actuaciones, por resolución fundada, al presidente o la presidenta del Colegio de Juezas o Jueces, quien resolverá si la decisión resulta procedente, Se considerará motivo de excusación los siguientes: a) Si intervino en él como acusador o acusada, defensor o defensora, representante, perito o consultor técnico, si denunció el hecho o lo conoció como testigo o si dio recomendaciones o emitió opinión sobre el caso fuera del procedimiento. b) Si intervino durante la investigación preparatoria o en el procedimiento de control de la acusación no podrá intervenir en el juicio; si pronunció la decisión impugnada no podrá intervenir en el procedimiento que sustancia la impugnación ni en su decisión. c) Si en el caso intervino o interviene su cónyuge, conviviente o algún pariente dentro del tercer grado de consanguinidad o por adopción y segundo de afinidad, quien ha sido su tutor, curador o guardador o quien está o ha estado bajo su tutela, curatela o guarda. d) Si ella, él o alguna de las personas mencionadas en el Inciso c) estuvieren interesados en el caso o tuvieren juicio pendiente, comunidad o sociedad con alguno de los interesados, salvo que se tratare de una sociedad anónima cuyas acciones coticen en el mercado de valores. ; PADRE CT AP PRA [ES COPIA MEL EZ. ORIGIMAL| e) Siella, él o alguna de las personas mencionadas en el Inciso c) recibieron o reciben beneficios de importancia o son acreedores, deudores o fiadores de alguno de los interesados, salvo que se tratare de instituciones estatales o de entidades financieras o si, después de comenzado el procedimiento, el juez o jueza hubiere recibido presentes o dádivas de alguno de los interesados, aunque fueren de escaso valor. !) Si antes de iniciado el procedimiento tuvo amistad íntima o enemistad manifiesta con alguno de los interesados, si denunció o acusó a alguno de ellos o fue acusado o denunciado por alguno de ellos, incluso conforme al procedimiento para el desafuero o la destitución, salvo que circunstancias posteriores demuestren armonía entre ambos. y) Si mediaren circunstancias que, por su gravedad, afecten su independencia e imparcialidad. La jueza o juez, comprendidos en alguno de los motivos contenidos en los Incisos a), b), Cc), d), e) y g), deberán denunciarlo inmediatamente de conocer su situación respecto del caso, y apartarse del conocimiento y decisión del proceso respectivo. En el supuesto del Inciso f), la jueza o juez, a su exclusivo criterio, podrá omitir el apartamiento, sin perjuicio de informar a los intervinientes y al presidente del Colegio de Juezas o Jueces sobre la situación en la que se encuentra.-"},{"n":44,"r":"RECUSACIÓN","t":"RECUSACIÓN. Las juezas o jueces podrán ser recusados por las partes cuando se generen dudas razonables acerca de su imparcialidad frente al caso. También podrán invocar alguno de los motivos previstos en el Artículo 43 u otros análogos o equivalentes. Al formularse la recusación se indicarán por escrito, bajo pena de inadmisibilidad, los motivos en que se funda y los elementos de prueba pertinentes. La recusación deberá formularse dentro de los tres (3) días de conocerse las causas en que se funda. Si la jueza o juez admite la recusación aplicará el procedimiento previsto para la excusación. En caso contrario, remitirá un informe al Colegio de Jueces para su resolución en audiencia. La resolución de la excusación anterior no impedirá la interposición de la recusación por el mismo motivo.- CAPÍTULO IV TRIBUNALES DE JURADOS"},{"n":45,"r":"INTEGRACIÓN DE TRIBUNALES DE JURADOS","t":"INTEGRACIÓN DE TRIBUNALES DE JURADOS. La Ley Especial de Juicio por Jurados determinará la composición, integración, constitución, sustanciación y deliberación del juicio en el que participe un tribunal de jurados.- CAPÍTULO V LA PERSONA IMPUTADA"},{"n":46,"r":"DENOMINACIÓN","t":"DENOMINACIÓN. Se denominará persona imputada a toda persona a quien mediante denuncia, querella o cualquier acto del procedimiento de la fiscalía se señale como autor o partícipe de un delito.- APOmNa EN REL SO ES COPIA FIEL DEL ORIGINAL | dor"},{"n":47,"r":"DERECHOS DE LA PERSONA IMPUTADA","t":"DERECHOS DE LA PERSONA IMPUTADA. A toda persona imputada se le asegurarán las garantías necesarias para su defensa, a cuyo fin las autoridades intervinientes le informarán de manera inmediata y comprensible los siguientes derechos: 1.- —Aser informada de las razones de su aprehensión o detención, la autoridad que la ha ordenado, entregándole si la hubiere copia de la orden judicial emitida en su contra, y el de ser conducida ante una jueza o juez, sin demora, para que decida sobre la legalidad de aquella. 2.- A pedir que su aprehensión o detención sea comunicada en forma inmediata a un pariente o persona de su confianza, asociación o entidad. Si la persona imputada ejerciere este derecho se dejará constancia de la producción del aviso y del resultado obtenido. Cuando la persona aprehendida o detenida fuese extranjera se le informará que puede pedir que su situación sea comunicada al Cónsul del Estado de su nacionalidad y también que se haga saber al Cónsul su interés de ser entrevistada por él. 3.- A guardar silencio, sin que ello pueda ser valorado como una admisión de los hechos o como indicio de culpabilidad. 4.- A ser asistida desde el primer acto del procedimiento por el defensor de su elección o por uno propuesto por una persona de su confianza y en defecto de ello, por un defensor público. 5.- A entrevistarse con su defensor en forma libre, privada y confidencial, en particular en oportunidad previa a la realización de cualquier acto que requiera su intervención. 6.- Apprestar declaración, si así lo deseara y si se encuentra detenida, dentro de las 48 horas de efectivizada la medida. 7.- A presentarse ante la fiscalía, jueza o juez, en su caso, para que se le informe y escuche sobre los hechos que se le imputan. 8.- A declarar cuantas veces quiera, con la presencia de su defensor, lo que se le hará saber cada vez que manifieste su deseo de hacerlo. 9.- Ano ser sometida a técnicas o métodos que induzcan o alteren su libre voluntad o a medidas contrarias a su dignidad. 10.- A que no se empleen medios que impidan el libre movimiento de su persona en el lugar y durante la realización de un acto procesal, sin perjuicio de las medidas de vigilancia que en casos especiales y a su prudente arbitrio la jueza o juez o la fiscalía considere necesarias. 11.- A acceder a toda la información disponible desde el momento en que tenga noticia de la existencia del proceso, según las previsiones de este Código. En todos los casos se dejará constancia fehaciente del cumplimiento del deber de información establecido en este Artículo.- . 2 AREA E PEL ADICINA ¡ES COPIA FICA DEL ORIGINAL | . 10.797"},{"n":48,"r":"IDENTIFICACIÓN Y DOMICILIO","t":"IDENTIFICACIÓN Y DOMICILIO. Desde el primer acto en que intervenga la persona imputada será identificada por sus datos personales y señas particulares. Si se abstiene de proporcionar esos datos, existiera duda sobre ellos o lo hace falsamente se lo identificará por testigos o por otros medios útiles. La duda sobre los datos obtenidos no alterará el curso del procedimiento y los errores sobre ellos podrán ser corregidos en cualquier oportunidad. En su primera intervención la persona imputada deberá denunciar el domicilio real, fijar el domicilio procesal y/o aportar cualquier otro medio de comunicación, posteriormente deberá mantener actualizados esos datos.-"},{"n":49,"r":"INCAPACIDAD","t":"INCAPACIDAD. La incapacidad por trastorno mental de la persona imputada que excluya su capacidad de comprensión de los actos procesales o de obrar conforme a ese conocimiento será declarada por un juez o una jueza y provocará la suspensión del procedimiento hasta que desaparezca. Si la incapacidad es irreversible se dispondrá el archivo del caso. Sin embargo, no impedirá la investigación del hecho ni la continuación con respecto a otras personas imputadas. Si la incapacidad existiera al momento de cometerse el hecho investigado el juez o jueza declarará la inimputabilidad. Cuando correspondiere se dará intervención a la justicia civil y al Ministerio Público de la Defensa.-"},{"n":50,"r":"REBELDÍA","t":"REBELDÍA. Será declarada en rebeldía la persona imputada que no comparezca a una citación a la que está obligada a comparecer sin justificación, se fugue del establecimiento o lugar donde esté detenida, desobedezca una orden de detención o se ausente del domicilio denunciado sin justificación. La declaración de rebeldía y la consecuente orden de captura serán dispuestas por la jueza o juez a solicitud de la parte acusadora. La rebeldía suspenderá el procedimiento, salvo las diligencias de la investigación. También suspenderá el plazo de duración del proceso.-"},{"n":51,"r":"LIBERTAD DE DECLARAR","t":"LIBERTAD DE DECLARAR. La persona imputada no será citada a declarar, aunque tendrá derecho a hacerlo cuantas veces considere necesario. Durante la etapa preparatoria podrá declarar oralmente o por escrito en la fiscalía por ante la encargada o el encargado de la etapa penal preparatoria. En los demás casos ante la jueza o el juez o el tribunal. Está prohibida la declaración de la persona imputada en ausencia del defensor o defensora. Cuando por imposibilidad física de la persona imputada no pudiera oír o expresarse verbalmente o no comprenda el idioma nacional tendrá derecho a designar su propio traductor o intérprete, pero si no lo designare será provisto de uno a costa del Estado, para que le transmita el contenido del acto o de la audiencia. En ningún caso se le exigirá a la persona imputada juramento o promesa de decir verdad, ni podrá ser sometida a ninguna clase de fuerza o coacción. Se prohíbe toda medida que afecte la libertad de decisión, voluntad, memoria o capacidad de comprensión de la persona imputada.- a a a, | ES COPIA FIEL DEL ORIGINAL!"},{"n":52,"r":"FACULTADES POLICIALES","t":"FACULTADES POLICIALES. La policía no podrá interrogar a la persona imputada. Sólo podrá requerirle los datos correspondientes a su identidad, cuando no esté suficientemente individualizado. Sí expresa su deseo de declarar, se le hará saber de inmediato a la o el fiscal interviniente y a la abogada o abogado a cargo de su defensa.- CAPÍTULO VI DEFENSA"},{"n":53,"r":"DEFENSA TÉCNICA","t":"DEFENSA TÉCNICA. La persona imputada tendrá derecho a elegir una abogada o abogado de su confianza para que la asista y represente como defensora o defensor. Si no lo hace se le designará una abogada o abogado de la Defensa Pública. Si prefiere defenderse por sí mismo, la jueza o juez lo permitirá sólo cuando no perjudique la eficacia de su propia defensa. La asistencia e intervención de la defensa técnica no menoscaba el derecho de la persona imputada a formular solicitudes y observaciones. -"},{"n":54,"r":"NOMBRAMIENTO","t":"NOMBRAMIENTO. El nombramiento de la defensa técnica no estará sujeto a ninguna formalidad. Una vez designada la abogada o abogado deberá informar a la autoridad que corresponda el lugar y modo para recibir comunicaciones. Durante el transcurso del proceso, la persona imputada podrá designar nuevo abogada o abogado en su defensa, pero el anterior no podrá renunciar a la defensa hasta que el designado comunique su aceptación. El ejercicio del cargo de defensor o defendora será obligatorio para quien lo acepte, salvo excusa fundada. Para el ejercicio de sus funciones, los defensores serán admitidos de inmediato y sin ningún trámite, por la policía, la fiscalía, la jueza o juez, según el caso.-"},{"n":55,"r":"NOMBRAMIENTO EN CASO DE URGENCIA","t":"NOMBRAMIENTO EN CASO DE URGENCIA. Cuando la persona imputada esté privada de su libertad o prófuga, cualquier persona de su confianza podrá proponer ante la autoridad competente la designación de un defensor o defensora, la que será puesta en conocimiento del imputado inmediatamente. En caso de urgencia comenzará a actuar provisionalmente el defensor o defensora propuesto y a falta de este, la defensora o el defensor público. Si el imputado no está individualizado se deberá designar una defensora o defensor público a estos fines. La diligencia solamente será válida si el defensor o defensora controla efectivamente la realización de la misma mediante su real participación en el acto.-"},{"n":56,"r":"RENUNCIA Y ABANDONO","t":"RENUNCIA Y ABANDONO. El defensor o defensora podrá renunciar al ejercicio de la defensa; en este caso, se fijará un plazo para que el imputado nombre a otro. Si no lo hace será reemplazado por un defensor o defensora público. El o la renunciante no podrá abandonar la defensa mientras no intervenga su reemplazante. No se podrá renunciar durante las audiencias, salvo por motivos muy graves. El abandono de la defensa, la renuncia intempestiva y la falta de expresión de intereses contrapuestos entre más de un asistido constituirá una falta grave, que será comunicada de inmediato al Consejo de Abogados. El incumplimiento injustificado de las obligaciones por parte de la Defensora o Defensor Público será comunicado de inmediato al Defensor o Defensora General. ANA E E COIN | ES COPIA PEL DEL ORIGINAL] Si el defensor o defensora, sin causa justificada, abandona la defensa o deja al imputado sin asistencia técnica se nombrará uno de oficio. La resolución se comunicará al imputado, instruyéndole sobre su derecho a elegir otro defensor o defensora. Cuando el abandono ocurra poco antes del juicio se podrá aplazar su comienzo por un plazo no mayor de diez (10) días, si lo solicita el nuevo defensor o defensora.-"},{"n":57,"r":"PLURALIDAD DE DEFENSORES","t":"PLURALIDAD DE DEFENSORES. El imputado podrá designar las o los defensores que considere conveniente, pero no será defendido simultáneamente por más de dos en las audiencias orales o en el mismo acto. Cuando intervengan dos o más defensores la comunicación practicada a uno de ellos tendrá validez respecto de todos y la sustitución de uno por otro no alterará trámites ni plazos. Será inadmisible la defensa de varios imputados en un mismo procedimiento por un defensor común cuando exista incompatibilidad. La defensora o defensor podrá designar un defensor o defensora auxiliar para aquellas diligencias a las que no pueda asistir personalmente, lo cual será consentido previamente por el imputado o deberá ratificarlo posteriormente. El defensor o defensora auxiliar sólo tendrá responsabilidad en aquellos actos en los que participe, pero no exime la responsabilidad del principal.- CAPÍTULO VII LA VÍCTIMA SECCIÓN PRIMERA DERECHOS FUNDAMENTALES"},{"n":58,"r":"DEFINICIÓN DE VÍCTIMA","t":"DEFINICIÓN DE VÍCTIMA. Este Código considera víctima: 1.- Ala persona ofendida directamente por el delito. 2.- Al cónyuge, conviviente, hermanos, herederos, tutores, guardadores oO curadores en los delitos cuyo resultado sea la muerte de una persona o cuando el ofendido hubiere sufrido una afectación psíquica o física que le impida ejercer sus derechos. 3.- Alos socios, respecto de los delitos que afecten a una sociedad, cometidos : por quienes la dirigen, administren, gerencien o controlen, debiendo designar un representante para que actúe en su nombre. 4.- A las asociaciones, en aquellos hechos punibles que afecten intereses colectivos o difusos, siempre que el objeto de la asociación se vincule directamente con esos intereses. 5.- A cualquier asociación que acredite interés cuando se trate de hechos que importen violación a los derechos humanos fundamentales y hayan sido cometidos como autores o participes, por funcionarios públicos en el ejercicio de sus funciones o en ocasión de ellas o cuando impliquen actos de corrupción pública o abuso del poder público y conlleven graves perjuicios patrimoniales para el Estado. EPT ras 1 QCOODA Eo el Se RUR SUE E dianas TA A E EE A mcr 6.- Alas comunidades indígenas en los delitos que impliquen discriminación de uno de sus miembros, genocidio o afecten de un modo directo sus derechos colectivos reconocidos.-"},{"n":59,"r":"DERECHOS DE LA VÍCTIMA","t":"DERECHOS DE LA VÍCTIMA. La víctima será informada sobre sus derechos cuando realice la denuncia o en su primera intervención en el procedimiento y tendrá los siguientes derechos: 1.- Arecibir un trato digno y respetuoso y que se hagan mínimas las molestias derivadas del procedimiento y a contar con información sobre los derechos que en su beneficio existan, como ser atendida por personal del mismo sexo o del sexo que la víctima elija, cuando así lo requiera y recibir, por efectos de la comisión del delito, atención médica y psicológica de urgencia. 2.- A que se respete su intimidad en la medida que no obstruya la investigación. 3.- A recibir trato sin discriminación, a fin de evitar que se atente contra la dignidad humana y se anulen o menoscaben sus derechos y libertades, por lo que la protección de sus derechos se hará sin distinción alguna. 4.- Arequerir medidas de protección para su seguridad, la de sus familiares y la de los testigos que declaren en su interés, a través de los Órganos competentes. 5.- A intervenir en el procedimiento penal, conforme a lo establecido por este Código. 6.- A ser informada de los resultados del procedimiento, aun cuando no haya intervenido en él. 7.- A examinar documentos y actuaciones, ser informada verbalmente sobre el estado del proceso y la situación del imputado. 8.- A aportar información durante la investigación. 9.- Arecusar por los motivos, forma y procedimientos previstos en este Código. 10.- A ser escuchada antes de cada decisión que implique la extinción o suspensión de la acción penal, siempre que lo solicite expresamente. 11.- A requerir la revisión de la desestimación o archivo dispuesto por el o la fiscal, aun cuando no haya intervenido en el procedimiento como querellante; 12.- A ser notificada de las resoluciones que pueda impugnar o requerir su revisión; 13.- A requerir la revisión del pedido de sobreseimiento ante una o un fiscal superior, aun sin ser querellante. E A JA EX FE Moras ¡ES COPIA Mo A DS” 14.- A tener asesoramiento técnico gratuito para el ejercicio de sus derechos. Podrá designar a una abogada o abogado de su confianza y, si no lo hiciere, por las circunstancias del hecho y por situaciones de vulnerabilidad se encuentre imposibilitada de afrontar los gastos que demande el patrocinio letrado se le informará que tiene derecho a ser asistida gratuitamente y se la derivará a la Oficina Fiscal de Asistencia de la Víctima, conforme a lo dispuesto en el Artículo 13% de la Ley N* 10.185 o la que en el futuro la reemplace. 15.- A que el Ministerio Público y sus auxiliares así como el Órgano jurisdiccional le faciliten el acceso a la justicia y les presten los servicios que constitucionalmente tienen encomendados con legalidad, honradez, lealtad, imparcialidad, profesionalismo, eficiencia y eficacia y con la debida diligencia, contemplando especialmente la situación de aquellas víctimas que presenten alguna discapacidad, garantizando su participación plena y efectiva en el proceso. 16.- A "},{"n":60,"r":"REPRESENTACIÓN Y ASISTENCIA ESPECIAL","t":"REPRESENTACIÓN Y ASISTENCIA ESPECIAL. La víctima será representada en el proceso penal por el Ministerio Público Fiscal, conforme a lo que disponga la Ley, quien deberá dar cumplimiento a los derechos de la víctima, sin perjuicio de ejercer la facultad de constituirse en querellante particular bajo las reglas establecidas en este Código. La fiscalía general garantizará, conforme a los requisitos y asignaciones funcionales que determine la reglamentación, la asistencia técnica y patrocinio jurídico de las víctimas de delitos, si por la limitación de sus recursos económicos o vulnerabilidad resultara necesaria la intervención de la abogada o abogado del Ministerio Público Fiscal, en atención a la especial gravedad de los hechos investigados. Podrá también solicitar que sus derechos y facultades sean ejercidos en el proceso, constituyéndose como querellante particular, por intermedio de una asociación de protección o ayuda a las víctimas, sin fines de lucro, cuando sea más conveniente para la defensa de sus intereses.- SECCIÓN SEGUNDA QUERELLA"},{"n":61,"r":"FORMA Y CONTENIDO DE LA QUERELLA","t":"FORMA Y CONTENIDO DE LA QUERELLA. La pretensión de constituirse en parte querellante podrá formularse por escrito, en forma personal o por mandatario especial que agregará el poder, con asistencia letrada; podrá el querellante peticionar su participación por representante con poder otorgado \"apud acta”, el cual será ratificado ante el fiscal, en la primera oportunidad que lo disponga en el procedimiento preparatorio; en todos los supuestos deberá contener: aaa 1 ¡ E ¡ES COPIA FIEL. Del ORIGINAL] Ansa o 10.797 1.- Datos de identidad, domicilio y firma del querellante y, en su caso, también del mandatario. 2.- Datos de identidad y el domicilio del querellado, o si se ignora, cualquier descripción que sirva para identificarlo. 3.- Una relación clara, precisa y circunstanciada del hecho, con indicación del lugar y el momento en que se ejecutó. 4.- Las pruebas que se ofrezcan, indicando en su caso los datos que permitan llevar adelante su producción. Si se trata de testigos o peritos, además de los datos personales y domicilio, se deberán indicar los hechos sobre los que deberán ser examinados o requeridos. 5.- La acreditación de los extremos de personería que invoca, en su caso. La presentación deberá acompañarse con una copia del escrito para cada querellado. Si se omitiere algunos de los requisitos establecidos en este Artículo deberá intimarse a quien efectuó la presentación para que en el plazo de tres (3) días corrija el error u omisión, bajo apercibimiento de inadmisibilidad.- ARTÍCULO 62>.- OCASIÓN. La querella deberá formularse ante el fiscal en el procedimiento preparatorio. Éste rechazará la solicitud de constitución cuando el interesado no tenga legitimación. En tal caso, la víctima podrá acudir, dentro del tercer día de notificada, ante la jueza o juez para que revise la decisión.-"},{"n":62,"r":"OCASIÓN","t":"OCASIÓN. La querella deberá formularse ante el fiscal en el procedimiento preparatorio. Éste rechazará la solicitud de constitución cuando el interesado no tenga legitimación. En tal caso, la víctima podrá acudir, dentro del tercer día de notificada, ante la jueza o juez para que revise la decisión.-"},{"n":63,"r":"ACUSACIÓN ÚNICA","t":"ACUSACIÓN ÚNICA. UNIDAD DE REPRESENTACIÓN. Cuando los acusadores fueran varios e invocaren identidad de intereses entre ellos actuarán bajo una sola representación, la que se ordenará a pedido de parte si ellos no se pusieren de acuerdo en el plazo que se les fije. En aquellos casos en que la víctima se haya constituido como querellante y no exista una simetría en los aspectos fácticos y jurídicos de la imputación, la jueza o juez en la audiencia preparatoria de juicio consultará a las partes a efectos de resolver las controversias que pudieran existir. La persona imputada tendrá derecho a que se le enrostre una única acusación, debiéndose respetar estrictamente el principio de congruencia procesal en los aspectos fácticos. Si no llegase a un acuerdo prevalecerá la acusación mayor o más amplia.-"},{"n":64,"r":"DESISTIMIENTO Y ABANDONO DE LA QUERELLA","t":"DESISTIMIENTO Y ABANDONO DE LA QUERELLA. El querellante podrá desistir de su intervención en cualquier momento, quedando obligado por las costas que su actuación hubiere causado. La querella se considerará abandonada en los siguientes casos: 4.- — Enlos delitos de acción privada: a) Siel querellante no insta el procedimiento durante treinta (30) días; ES COPIA FIEL DEL ORIGINAL] b) Cuando el querellante no concurra a la audiencia de conciliación o de juicio sin justa causa. c) Si habiendo fallecido o incapacitado el querellante, quien esté autorizado para ello según la Ley no concurra a proseguir el procedimiento, dentro de los treinta (30) días siguientes al suceso. . 2. Enlos delitos de acción pública : a) Cuando no presente acusación ni adhiera a la de la Fiscalía. b) Cuando no concurra a la audiencia de control de la acusación o de juicio o se aleje de éste, o no presente conclusiones sin justa causa. c) Cuando fallecido o incapacitado el querellante, quien esté autorizado para ello según la Ley no concurra a proseguir el procedimiento, dentro de los treinta (30) días siguientes del suceso. En los casos de incomparecencia, la existencia de justa causa deberá acreditarse antes de iniciar la audiencia o diligencia.-"},{"n":65,"r":"QUERELLANTE AUTÓNOMO","t":"QUERELLANTE AUTÓNOMO. En los delitos de acción pública, la víctima o su representante legal estará facultada para intervenir en la persecución penal, aun cuando por reglas de disponibilidad el o la fiscal decida no continuarla. Las entidades del sector público no podrán ser querellantes. En estos casos el o la fiscal representará los intereses del Estado. No obstante, podrán participar en el proceso como terceros coadyuvantes. La participación de la víctima como querellante no alterará las facultades concedidas por la ley a la fiscalía ni la eximirá de sus responsabilidades.-"},{"n":66,"r":"ACCIÓN POPULAR","t":"ACCIÓN POPULAR. Cualquier persona, humana o jurídica, podrá iniciar y proseguir querella contra los presuntos responsables cuando: 1.- Los delitos violen los derechos humanos fundamentales y hayan sido cometidos como autores o partícipes, por funcionarios públicos en el ejercicio de su función o en ocasión de ella. 2.- Los delitos impliquen abuso del poder público y conlleven graves perjuicios patrimoniales para el Estado. 3.- Los delitos que afecten intereses difuso. 4.- Se trate de delitos de lesa humanidad.-"},{"n":67,"r":"ACCIÓN PENAL PRIVADA","t":"ACCIÓN PENAL PRIVADA. Toda persona que se considere ofendida por delito de acción privada tendrá derecho a presentar querella. El o la representante legal del incapaz por delitos cometidos en su perjuicio, gozará de igual derecho. En el caso de que la abogada o el abogado cumpla la calidad de representante podrá ejercer directamente las facultades del querellante, salvo las de carácter personal o cuando exista una reserva expresa en la Ley o en el mandato. Regirán análogamente las reglas previstas para el defensor o la defensora del imputado.- peo PROA DEL PO AMÓN ¡ES COPIA MEL Dal ORIGINAL] CAPÍTULO VIII EL MINISTERIO PUBLICO FISCAL"},{"n":68,"r":"FUNCIONES","t":"FUNCIONES. El Ministerio Público Fiscal promoverá y ejercerá la acción penal pública de acuerdo a las normas de este Código, dirigiendo la investigación y la actuación de todos los funcionarios que participen en ella, interviniendo en todas las etapas del proceso. A los fiscales les corresponderá la carga de la prueba de los hechos que funden su . acusación. El fiscal debe hacer conocer a la defensa toda la prueba de cargo y de descargo que se ha reunido o conocido durante el proceso penal. Será deber de los fiscales adoptar o requerir las medidas necesarias para proteger a las víctimas de los delitos, favorecer su intervención en el procedimiento y evitar o disminuir cualquier perjuicio que pudieran derivar de su intervención. Formularán sus requerimientos, dictámenes y resoluciones en forma motivada. No podrán ocultar información o evidencias que puedan favorecer la situación del imputado. Su inobservancia constituye falta grave. y será considerado causal de mal desempeño de las funciones a los efectos del proceso de remoción."},{"n":69,"r":"INHIBICIÓN Y RECUSACIÓN","t":"INHIBICIÓN Y RECUSACIÓN. El o la fiscal se inhibirá y podrá ser recusado cuando exista algún interés personal que pueda interferir en su actuación funcional. La recusación será resuelta por la o el fiscal superior jerárquico y la decisión no será impugnable.-"},{"n":70,"r":"AGENCIA DE INVESTIGACIÓNES PENALES","t":"AGENCIA DE INVESTIGACIÓNES PENALES. La Agencia de Investigaciones Penales estará bajo la dirección técnica del Ministerio Público Fiscal en todo lo concerniente a la investigación y persecución de los delitos. Su organización y funcionamiento será establecido por una ley especial. Sus integrantes ejecutarán sus tareas bajo la dirección y responsabilidad de los fiscales, sin perjuicio de la dependencia administrativa que les corresponda. La autoridad administrativa no podrá revocar, alterar o retardar una orden emitida por la o los fiscales o los jueces o juezas. El Ministerio Público Fiscal emitirá las instrucciones generales necesarias para coordinar la labor de la Agencia de Investigaciones Penales y la Policía Provincial.-"},{"n":71,"r":"FACULTADES","t":"FACULTADES. Los funcionarios de la Agencia de Investigaciones Penales podrán realizar, aun sin recibir instrucciones previas, las siguientes actuaciones: 1.- Prestar auxilio a las víctimas y proteger a los testigos. 2.- Recibir denuncias. 3.- Identificar y entrevistar a los testigos, a excepción de los supuestos especiales contemplados en este Código. 4.- —Resguardar la escena del hecho y cuidar que los rastros e instrumentos sean conservados, haciendo constar por cualquier medio u operación el estado de las personas, cosas y lugares. ¡EQ PRO E Pa Cos ¡ES COPIA Miel DEL ORIGINAL! LA RIOJA : 5.- Recabar los datos que sirvan para la identificación del imputado, con los límites establecidos por este Código. 6.- Efectuar la aprehensión de personas en los casos de flagrancia. 7.- — Ejecutar registros, requisas y secuestros cuando les esté permitido.-"},{"n":72,"r":"OTROS PREVENTORES","t":"OTROS PREVENTORES. Las mismas disposiciones regirán para la Policía de la Provincia o cualquier autoridad que realice actos de policía o tenga el deber de colaborar en la investigación criminal.- TÍTULO II ACTIVIDAD PROCESAL CAPÍTULO | ACTOS PROCESALES SECCIÓN PRIMERA NORMAS GENERALES"},{"n":73,"r":"REGLAS","t":"REGLAS. En los actos procesales se observarán las siguientes reglas: 1.- Se cumplirán en días y horas hábiles, sin perjuicio de las habilitaciones que disponga el juez o juezas. Los actos de investigación, salvo excepciones expresamente dispuestas, se podrán cumplir en cualquier día y hora; 2.- Deberá usarse idioma español, 3.- Los olas fiscales y juezas o jueces podrán constituirse en cualquier lugar del territorio provincial para la realización de los actos propios de su función.-"},{"n":74,"r":"ORALIDAD","t":"ORALIDAD. RESOLUCIONES JUDICIALES. Las resoluciones jurisdiccionales contendrán: 1.- El día, lugar e identificación del proceso. 2.- Elobjeto a decidir y las peticiones de las partes. 3.- La decisión y su motivación. : Todas las decisiones jurisdiccionales, requieran o no debate de las partes, se adoptarán en audiencia pública con la asistencia ininterrumpida de la jueza o juez y de todos los sujetos procesales que deban intervenir, garantizando el principio de oralidad, contradicción, publicidad, inmediación y simplicidad. La jueza o juez no podrá suplir la actividad de estas y deberá sujetarse a lo que hayan discutido. Sin embargo, deberá generar un genuino contradictorio entre las partes. El desarrollo de la audiencia y el fundamento de las decisiones quedarán debidamente registrados en soporte de audio o video, entregándose copia de ellos a las partes que lo soliciten. Las resoluciones jurisdiccionales expresarán los fundamentos de hecho y de derecho en que se basen. e arpas mic AR ASIAN Ay? [ES COPIA MEL DEL ORIGINAL! l 10.797 La fundamentación no podrá ser reemplazada con la simple relación de documentos, invocación de las solicitudes de las partes, afirmaciones dogmáticas, expresiones rituales o apelaciones morales. Las decisiones de mero trámite serán resueltas por la Oficina Judicial.-"},{"n":75,"r":"DOCUMENTACIÓN","t":"DOCUMENTACIÓN. Los actos se documentarán por audio o video. Se utilizarán imágenes y sonidos para documentar actos de prueba o audiencias, quedando prohibida toda forma de edición, tratamiento o modificación de los registros. Se deberá asegurar su autenticidad e inalterabilidad. Se deberá reservar el original en condiciones que aseguren su inviolabilidad hasta el debate, sin perjuicio de la obtención de copias que podrán utilizarse para otros fines del proceso. Las formalidades esenciales de los actos deberán surgir del mismo registro y, en caso de no ser posible, de un acta complementaria. Las diligencias que deban asentarse en forma escrita contendrán: a) La mención del lugar, fecha y hora. b) La firma de todos los participó en el acto, dejándose constancia de las razones de aquel que no la firme o del que lo hace a ruego o como testigo de actuación.-"},{"n":76,"r":"ACLARATORIA","t":"ACLARATORIA. Dentro del término de tres (3) días de notificadas las resoluciones, el tribunal podrá rectificar, de oficio o a instancia de parte en audiencia, cualquier error u omisión material contenidos en aquellas siempre que ello no importe una modificación esencial. La instancia de aclaración suspenderá el término para interponer los recursos que procedan.-"},{"n":77,"r":"PLAZOS","t":"PLAZOS. Los actos procesales serán cumplidos en los plazos establecidos observándose las siguientes prescripciones: 1.- Los plazos legales y judiciales serán perentorios y vencerán a las 24 horas del último día señalado, provocando la conclusión de las instancias o del derecho a petición de las partes. Si el término fijado venciese después de las horas de oficina, el acto que deba cumplirse en ella podrá ser realizado durante las dos (2) primeras horas del día hábil siguiente. 2.- Los plazos determinados por horas comenzarán a correr inmediatamente después de ocurrido el acontecimiento que fija su iniciación sin interrupción. 3.- Los plazos determinados por días comenzaran a correr al día siguiente de practicada su comunicación. A esos efectos, se computarán sólo los días hábiles, salvo que la Ley disponga expresamente lo contrario. 4.- Los plazos comunes comenzarán a correr a partir de la última comunicación que se practique a los interesados. 5.- Cuando la Ley permita la fijación de un plazo judicial, la jueza o el juez lo fijará conforme a la naturaleza del procedimiento y a la importancia de la actividad que se deba cumplir, teniendo en cuenta los derechos de las partes; éste será siempre inferior al plazo establecido legalmente. al SMA SNE] PAPI Aria ; ¡ES COPIA FlEL DEL ORIGINAL A A 6.- Las partes podrán solicitar la reposición total o parcial del plazo, cuando por defecto de la comunicación, por razones de fuerza mayor o por caso fortuito no hayan podido observarlo. 7.- Las partes podrán acordar la prórroga de un plazo. La parte a cuyo favor se ha establecido un plazo podrá renunciarlo o abreviarlo mediante expresa manifestación de voluntad que deberá ser conjunta cuando el plazo sea común.-"},{"n":78,"r":"VENCIMIENTO","t":"VENCIMIENTO. EFECTOS. El vencimiento de un término fatal sin que se haya cumplido el acto para el que está determinado, importará, además, el cese automático de la intervención en el caso de la jueza o juez, tribunal o representante del Ministerio Público al que dicho plazo le hubiere sido acordado. En tales casos, aquellos serán reemplazados por la magistrada o el magistrado o funcionaria o funcionario que legalmente corresponda. El cese de intervención de la funcionaria o del funcionario judicial por este motivo constituye falta grave, debiendo comunicarse al órgano que ejerza la superintendencia y sin perjuicio de que su reiteración lo haga pasible de la apertura del procedimiento por ante el Jurado de Enjuiciamiento de la Provincia o cese del interinato por subrogancia.-"},{"n":79,"r":"PODER DE DISCIPLINA","t":"PODER DE DISCIPLINA. Las juezas o jueces velarán por la regularidad del litigio y el ejercicio correcto de las facultades de las personas litigantes. No podrán restringir el derecho de defensa o limitar facultades de las partes invocando razones de indisciplina. Cuando las características del caso aconsejen adoptar medidas especiales para asegurar la regularidad en el litigio, la jueza o juez convocará a las partes a fin de acordar reglas particulares de actuación.- SECCIÓN SEGUNDA AUDIENCIAS"},{"n":80,"r":"MODALIDAD","t":"MODALIDAD. CARÁCTER MULTIPROPÓSITO DE LA AUDIENCIA. Todas las audiencias en el marco del procedimiento establecido en el presente Código tienen carácter multipropósito, pudiendo someterse a decisión jurisdiccional cuestiones diferentes de las que pudieran haber motivado su realización. Todas las personas que participen en una audiencia se expresarán en forma oral. No se admitirá la lectura de escritos o declaraciones salvo la lectura parcial de notas. Quienes no puedan hablar o no entiendan el idioma español declararán por escrito o por medio de intérpretes. Las juezas o jueces en casos extraordinarios realizarán las audiencias de forma virtual, posibilitando que se efectivice por medio de un sistema tecnológico que admita una comunicación bidireccional y simultanea de la imagen, sonido y datos que permita la interacción visual, auditiva y verbal entre personas geográficamente distantes. Las audiencias efectuadas en forma virtual se harán bajo los lineamientos de las Leyes de la Provincia N* 10.249 y N* 10.254, o las que se dicten en consecuencia. Serán conducidas por el órgano jurisdiccional, respetando los derechos de las partes, especialmente el derecho de defensa y los principios procesales que gobiernan los distintos procesos judiciales, principalmente los de imparcialidad, publicidad, igualdad de partes, oralidad, inmediación, contradicción y concentración. Va A a a ga] ¡ES COPIA FIEL DEL ORIGINAL | Las partes en el marco de las audiencias virtuales desarrollarán sus actos procesales con sujeción a la buena fe y lealtad tecnológica hacia el juez o jueza y el adversario o adversaria como así también en el empleo de las herramientas virtuales tecnológicas o sistemas informáticos que permitan la comunicación y participación de las partes e interesados autorizados en el proceso. ' La persona imputada no podrá retirarse de la audiencia sin autorización del Organo Jurisdiccional. Asistirá a la audiencia libre en su persona y ocupará un asiento al lado de su defensa técnica. Sólo en casos excepcionales podrán disponerse medidas de seguridad que impliquen su confinamiento en un cubículo aislado en la sala de audiencia, cuando ello sea una medida indispensable para salvaguardar la integridad física de los intervinientes en la audiencia. Si se rehúsa a permanecer en la audiencia será custodiada en una sala próxima, desde la que pueda seguir la audiencia, y representada para todos los efectos por su defensa técnica. Cuando sea necesario para el desarrollo de la audiencia se le hará comparecer para la realización de actos particulares en los cuales su presencia resulte imprescindible.-"},{"n":81,"r":"PUBLICIDAD","t":"PUBLICIDAD. Las audiencias serán públicas. No obstante, la jueza o juez o tribunal podrá decidir fundadamente que se realice total o parcialmente en forma privada cuando: 1.- Se afecte directamente el pudor, la vida privada o ello implique una amenaza para la integridad física de alguno de los intervinientes. 2.- Peligre un secreto oficial, profesional, particular, comercial o industrial cuya develación cause perjuicio grave. 3.- Ha pedido de parte, cuando peligre el éxito de las medidas de pesquisa solicitadas. El tribunal podrá imponer a las partes que intervinieren en el acto el deber de guardar secreto sobre los hechos que presenciaron o conocieron. No podrán ingresar a la sala de audiencias personas que se presenten en forma incompatible con la seguridad, orden e higiene de la audiencia ni los menores de 12 años de edad, salvo cuando sean acompañados por un mayor que responda por su conducta. Antes y durante las audiencias el imputado tendrá derecho a comunicarse con su defensor o defensora, pero no con el público. Si infringe esa disposición, el Órgano Jurisdiccional podrá imponerle una medida de apremio. Si alguna persona del público se comunica o intenta comunicarse con alguna de las partes, el Organo jurisdiccional podrá ordenar que sea retirada de la audiencia e imponerle una medida de apremio.-"},{"n":82,"r":"MEDIOS DE COMUNICACIÓN","t":"MEDIOS DE COMUNICACIÓN. Los representantes de los medios de difusión podrán presenciar las audiencias e informar al público sobre lo que suceda. La jueza o juez o el tribunal señalarán en cada caso las condiciones en que se ejercerán esas facultades y, por resolución fundada, podrá imponer restricciones cuando sea perjudicial para el desarrollo del debate o puedan afectarse los intereses indicados en el Artículo anterior. a asa a a tear) ESO. A Aaa . 10.797 Si la víctima, el imputado o un testigo solicitan que no se autorice a los medios de : comunicación a que se grabe su voz o su imagen, el tribunal examinará los motivos y resolverá en función de los diversos intereses comprometidos.-"},{"n":83,"r":"DESARROLLO","t":"DESARROLLO. Las audiencias se realizarán con la presencia ininterrumpida de las juezas o jueces y de todas las partes salvo las excepciones que se establecen en el Código. La jueza o juez que dirija la audiencia otorgará la palabra a las partes, comenzando por aquella que hubiese hecho el planteo o la solicitud. Siempre la última palabra le será conferida a la defensa. Las partes deberán expresar sus peticiones de modo concreto y las juezas o jueces podrán requerir precisiones para determinar los alcances de tales peticiones.- ARTÍCULO 84?.- REGISTRACIÓN. Las audiencias se registrarán en forma íntegra, en audio o video, por cualquier medio con el que se asegure la fidelidad. Las partes tendrán derecho a obtener copias fieles de los registros. Los registros se conservarán hasta la terminación del proceso y serán públicos, salvo en los casos en que las audiencias se hayan cumplido en forma privada. En forma complementaria se confeccionará un acta que contendrá: 1.- El lugar y fecha con indicación de la hora de inicio y finalización, así como de las suspensiones y de las reanudaciones. 2.- La mención de las juezas o jueces y de las partes. 3.- Los datos personales de la persona imputada. 4.- Las solicitudes y decisiones producidas. 5.- La firma de la persona encargada de sala que dependa de la Oficina Judicial.-"},{"n":84,"r":"REGISTRACIÓN","t":"REGISTRACIÓN. Las audiencias se registrarán en forma íntegra, en audio o video, por cualquier medio con el que se asegure la fidelidad. Las partes tendrán derecho a obtener copias fieles de los registros. Los registros se conservarán hasta la terminación del proceso y serán públicos, salvo en los casos en que las audiencias se hayan cumplido en forma privada. En forma complementaria se confeccionará un acta que contendrá: 1.- El lugar y fecha con indicación de la hora de inicio y finalización, así como de las suspensiones y de las reanudaciones. 2.- La mención de las juezas o jueces y de las partes. 3.- Los datos personales de la persona imputada. 4.- Las solicitudes y decisiones producidas. 5.- La firma de la persona encargada de sala que dependa de la Oficina Judicial.-"},{"n":85,"r":"MEDIDAS URGENTES","t":"MEDIDAS URGENTES. En casos de urgencia o fuera del horario judicial de atención al público, las partes podrán solicitar a la jueza o juez las medidas de prueba o coerción que no admiten demora para el éxito de la investigación. Para ello se deberá utilizar medios tecnológicos idóneos que permitan la inmediatez en la comunicación entre la parte y el juez o jueza, como así también el íntegro registro del mismo.- SECCIÓN TERCERA DIRECCIÓN DEL PROCEDIMIENTO"},{"n":86,"r":"DURACIÓN MÁXIMA","t":"DURACIÓN MÁXIMA. Sin perjuicio de lo establecido para los procedimientos especiales, todo proceso tendrá una duración máxima de tres (3) años contados desde el acto de la formulación de cargos hasta el dictado de la sentencia no firme. No se computará a estos efectos el tiempo necesario para resolver el recurso extraordinario federal. A E O ] MEE MIG PE] pura | ES COPIA FIEL DEL ORIGINAL! . 10.797 La rebeldía o la suspensión del trámite del proceso por cualquiera de las causas previstas en la Ley suspenderán el plazo antes referido. El incumplimiento del plazo previsto en el párrafo anterior hará incurrir al juez o jueza y al representante del Ministerio Público Fiscal en falta grave.-"},{"n":87,"r":"QUEJA POR RETARDO DE JUSTICIA","t":"QUEJA POR RETARDO DE JUSTICIA. Si la Oficina Judicial no fija audiencia o la jueza o juez no dicta la resolución correspondiente en los plazos que le señala este Código, el interesado podrá urgir pronto trámite y si dentro de las 48 horas no lo obtiene, podrá interponer queja por retardo de justicia. La Directora o director o jefa o jefe de la Oficina Judicial o la jueza o juez, con un breve informe sobre los motivos de su demora, remitirá inmediatamente las actuaciones al presidente del Colegio de Jueces para que resuelva lo que corresponda.-"},{"n":88,"r":"DEMORA DE LOS JUECES CON FUNCIONES DE REVISIÓN POR IMPUGNACIÓN","t":"DEMORA DE LOS JUECES CON FUNCIONES DE REVISIÓN POR IMPUGNACIÓN. Cuando las juezas o jueces con funciones de revisión por impugnación no resuelvan el recurso dentro de los plazos establecidos en este Código se podrá solicitar el pronto trámite. Si en cinco (5) días no dictan resolución, incurren en falta grave.- SECCIÓN CUARTA REGLAS DE COOPERACIÓN JUDICIAL"},{"n":89,"r":"COOPERACIÓN DE AUTORIDADES PROVINCIALES","t":"COOPERACIÓN DE AUTORIDADES PROVINCIALES. Cuando sea necesario, las juezas o jueces y fiscales podrán requerir cooperación de manera directa a otra autoridad judicial o administrativa de la Provincia para la ejecución de un acto o diligencia, fijando el plazo de su cumplimiento.-"},{"n":90,"r":"COOPERACIÓN DE OTRAS AUTORIDADES","t":"COOPERACIÓN DE OTRAS AUTORIDADES. Los o las fiscales y juezas o jueces podrán solicitar la cooperación de autoridades judiciales y administrativas de otras jurisdicciones. Ella se regirá por lo establecido en los convenios, por las normas internas o las prácticas de asistencia mutua, asimismo, existirá reciprocidad respecto a requerimientos análogos de autoridades judiciales de otras jurisdicciones. La decisión será motivada. Podrá suspenderse el cumplimiento de la cooperación en el caso de que su ejecución inmediata perjudique el curso de una investigación o de un juicio que se desarrolle en esta Provincia. La decisión será motivada.-"},{"n":91,"r":"EXTRADICIÓN EN EL PAÍS","t":"EXTRADICIÓN EN EL PAÍS. Los o las fiscales o las juezas o jueces de ejecución solicitarán la extradición de personas imputadas o condenadas que se encuentren en el territorio nacional y fuera del ámbito de la Provincia, de conformidad con los convenios celebrados. La solicitud de extradición efectuada por juezas o jueces o fiscales de otras jurisdicciones será resuelta por la jueza o juez de garantías que corresponda, en audiencia y con presencia de las partes. La resolución podrá ser revisada en audiencia por tres (3) juezas o jueces distintos del que la dictó.- [ES COPIA Fiol UE. ORIGINAL! : 10.797"},{"n":92,"r":"COOPERACIÓN INTERNACIONAL","t":"COOPERACIÓN INTERNACIONAL. La cooperación internacional a los fines de esta Sección Cuarta se regirá por el derecho internacional vigente y por la Ley Nacional respectiva.- SECCIÓN QUINTA COMUNICACIONES"},{"n":93,"r":"REGLA GENERAL","t":"REGLA GENERAL. Las resoluciones y la convocatoria a los actos que requieran la intervención de las partes o terceros, los pedidos de cooperación o informes, serán comunicados de conformidad con las normas prácticas dictadas por el Tribunal Superior de Justicia. Estas deberán asegurar que las comunicaciones se hagan a la brevedad, sin excesos formales y ajustados a los principios de claridad, precisión y suficiencia respecto al contenido de la resolución o de la actividad requerida y las condiciones o plazos para su cumplimiento. Las decisiones que se adopten durante las audiencias quedarán comunicadas en el mismo acto. Deberá garantizarse que: a) Transmitan con claridad, precisión y en forma completa el contenido de la resolución o de la actividad requerida y las condiciones o plazos para su cumplimiento. b) Contengan los elementos necesarios para asegurar la defensa y el ejercicio de los derechos de las partes. c) Agviertan suficientemente a la persona imputada o a la víctima si el ejercicio de un derecho estuviera sujeto a un plazo o condición. No obstante, las reglas fijadas, las partes podrán acordar expresamente en cada caso una modalidad de comunicación efectiva de acuerdo con las posibilidades técnicas a las que tengan acceso. Las comunicaciones que dispongan las juezas o jueces o el Ministerio Público Fiscal serán practicadas por las oficinas respectivas de conformidad con las reglas de normas prácticas, dictadas por el Tribunal Superior de Justicia o que se establezcan en leyes pertinentes.- CAPÍTULO Il ACTIVIDAD PROCESAL DEFECTUOSA"},{"n":94,"r":"PRINCIPIOS GENERALES","t":"PRINCIPIOS GENERALES. No podrán ser valorados para fundar una decisión judicial ni utilizados como presupuesto de ella, los actos cumplidos con inobservancia de los derechos y garantías de las personas imputadas, previstos en la Constitución de la Nación, Tratados Internacionales, Constitución de la Provincia y en este Código. Tampoco podrán ser valorados los actos cumplidos con inobservancia de las formas, que obsten al ejercicio del derecho a la tutela judicial de la víctima o impidan el ejercicio de los deberes y facultades del fiscal, salvo que el defecto haya sido convalidado.- ES CODA EEC DEL ORIGINAL | ¡ES COPIA HEL DEL ORIGINAL |"},{"n":95,"r":"SANEAMIENTO","t":"SANEAMIENTO. Todos los defectos deberán ser inmediatamente saneados, renovando el acto, rectificando el error o cumpliendo el acto omitido a petición del interesado. Cuando la invalidez se funde en la violación de una garantía establecida en favor de las personas imputadas, el procedimiento no podrá retrotraerse a etapas anteriores, salvo el caso de reenvío. Se entenderá que el acto se ha saneado cuando, no obstante, la irregularidad ha conseguido su fin respecto de todos los interesados. -"},{"n":96,"r":"CONVALIDACIÓN","t":"CONVALIDACIÓN. Los defectos formales que afectan a la o al fiscal o querellante quedarán convalidados en los siguientes casos: 1.- Cuando ellos no hayan solicitado su saneamiento mientras se realiza el acto o dentro de los tres (3) días de practicado, si quien lo solicita no ha estado presente. Si por las circunstancias del acto ha sido imposible advertir oportunamente el defecto, el interesado deberá reclamarlo dentro de las 24 horas después de advertirlo. 2.- Cuando quienes tengan derecho a oponerla hayan aceptado expresa o tácitamente los efectos del acto.-"},{"n":97,"r":"DECLARACIÓN DE NULIDAD","t":"DECLARACIÓN DE NULIDAD. Cuando no sea posible sanear un acto ni se trate de casos de convalidación, la jueza o juez deberá declarar su nulidad. La nulidad de un acto invalida todos los efectos o actos que dependan de él. Al declarar la nulidad la jueza o juez interviniente establecerá necesariamente a cuáles actos anteriores o contemporáneos alcanza la nulidad, por su conexión con el acto anulado.- LIBRO II ADMISIÓN DEL CASO TÍTULO! EJERCICIO DE LA ACCIÓN PENAL CAPÍTULO 1 REGLAS GENERALES"},{"n":98,"r":"DELITOS DE ACCIÓN PÚBLICA","t":"DELITOS DE ACCIÓN PÚBLICA. Los fiscales tendrán la obligación de ejercer la acción pública en todos los casos en que sea procedente con arreglo a las disposiciones de la Ley.-"},{"n":99,"r":"DELITOS DEPENDIENTES DE INSTANCIA PRIVADA","t":"DELITOS DEPENDIENTES DE INSTANCIA PRIVADA. Cuando el ejercicio de la acción penal pública requiera de instancia privada, la o el fiscal sólo la ejercerá una vez que ella se produzca, sin perjuicio de realizar los actos imprescindibles para conservar los elementos de prueba, siempre que no afecte la protección del interés de la víctima. Sin embargo, se procederá de oficio: 1ES COPIA FIEL DEL ORIGINAL - 10.797 a) En los casos del Inciso 1) del Artículo 72% del Código Penal, cuando la víctima fuere menor de 18 años de edad o haya sido declarada incapaz. b) En los casos del Inciso 2) del Artículo 72” del Código Penal, cuando mediaren razones de seguridad o interés público. e) Enlos casos de los Incisos 2) y 3) del Artículo 72” del Código Penal, cuando el delito fuere cometido contra un menor que no tenga padres, tutor ni guardador o que lo fuere por uno de sus ascendientes, tutor o guardador o cuando existieren intereses gravemente contrapuestos entre éstos y el menor siempre que resultare más conveniente para el interés superior de aquel. La instancia privada permitirá formar caso a todos los partícipes sin limitación alguna.-"},{"n":100,"r":"DELITOS DE ACCIÓN PRIVADA","t":"DELITOS DE ACCIÓN PRIVADA. Cuando la acción sea privada, su ejercicio corresponderá exclusivamente a la víctima, conforme al procedimiento especial regulado por este Código. En el procedimiento especial por delito de acción privada no tendrá ninguna intervención la fiscalía.- CAPÍTULO Il SITUACIONES ESPECIALES"},{"n":101,"r":"INMUNIDADES CONSTITUCIONALES","t":"INMUNIDADES CONSTITUCIONALES. Si se formula denuncia o querella contra una legisladora, legislador o funcionarios sujetos a juicio político o jurado de enjuiciamiento se practicará una investigación que no vulnere su inmunidad. Cuando se formulare acusación se solicitará el desafuero ante quien corresponda, acompañando copia de las actuaciones y expresando las razones que lo justifiquen. Si la legisladora, legislador o funcionarios han sido detenidos por habérselos sorprendido en flagrancia, la jueza o juez pondrá inmediatamente el hecho en conocimiento de la Legislatura Provincial, conforme a lo previsto en la Constitución. Cuando se proceda contra varias personas imputadas y sólo alguna de ellas gocen de inmunidades constitucionales, el proceso podrá formarse y seguir con respecto a los otros. Si el desafuero es denegado se declarará que no se puede proceder y se suspenderá el proceso, de lo contrario se dispondrá su continuación. Sin perjuicio de lo dispuesto precedentemente la persona interesada tiene derecho a ejercer las facultades que le confiere la Ley a la persona imputada.-"},{"n":102,"r":"CUESTIÓN PREJUDICIAL","t":"CUESTIÓN PREJUDICIAL. La cuestión prejudicial procederá cuando sea necesario determinar por un procedimiento extrapenal la existencia de uno de los elementos constitutivos del hecho punible. La existencia de una cuestión prejudicial suspenderá el juicio hasta que exista sentencia firme en el proceso extrapenal. Resuelta la suspensión del proceso en los casos previstos en los Artículos anteriores, se ordenará la libertad del imputado, previa fijación de domicilio y sin perjuicio de la imposición de otras medidas cautelares previstas en el Código. ¡ES COPIA PEL DEL ORIGINAL! A e a nora - 10.797 Las juezas o jueces podrán apreciar si la cuestión prejudicial invocada es seria, fundada y verosímil, y en caso que aparezca opuesta con el exclusivo propósito de dilatar el proceso ordenarán que este continúe.-"},{"n":103,"r":"PRELACIÓN","t":"PRELACIÓN. Cuando la solución de un proceso penal dependa de la resolución de otro y no corresponda la acumulación de ambos, el ejercicio de la acción se suspenderá en el primero hasta que recaiga sentencia firme en el otro.-"},{"n":104,"r":"EXCEPCIONES","t":"EXCEPCIONES. Las partes podrán oponer las siguientes excepciones: 1.- Falta de jurisdicción o de competencia. 2.- Falta de acción, porque ésta no pudo promoverse, no fue iniciada legalmente o lo fue por quien no tiene legitimación o no puede proseguirse. 3.- Extinción de la acción penal. Si concurren dos o más excepciones deberán interponerse conjuntamente bajo pena de caducidad, salvo que la omitida sea una excepción perentoria. Cuando se hiciere lugar a la falta de jurisdicción o de competencia, la jueza o juez ordenará remitir las actuaciones al tribunal correspondiente. Si se declara la falta de acción el caso se archivará, salvo que el proceso pueda proseguir por otro interviniente. En ese caso, la decisión sólo desplazará del procedimiento a quien afecte. Cuando se declare la extinción de la acción penal se resolverá el sobreseimiento.- CAPÍTULO Ill REGLAS DE DISPONIBILIDAD DE LA ACCION SECCIÓN PRIMERA CRITERIOS DE OPORTUNIDAD"},{"n":105,"r":"SELECCIÓN DE CASOS","t":"SELECCIÓN DE CASOS. Se podrá prescindir total o parcialmente del ejercicio de la acción penal o limitarla a alguna de las personas que intervinieron en el hecho en los casos siguientes: 1.- Cuando se trate de un hecho insignificante o un hecho que no afecte gravemente el interés público. 2.- Cuando la intervención de la persona imputada se estime de menor relevancia. 3.- En los delitos culposos cuando la persona imputada haya sufrido a consecuencia del hecho un daño físico o moral grave que torne innecesaria y desproporcionada la aplicación de una pena. 4.- Cuando la pena que pueda imponerse por el hecho de cuya persecución se prescinde, carezca de importancia en consideración a la pena ya impuesta o a la que puede esperarse por los restantes hechos. (ES COPIA FIEL DEL ORIGINAL! 5.- Cuando se repare el daño en la medida de lo posible. 6.- Cuando exista conciliación entre las partes o cuando se haya realizado una mediación penal exitosa que haya logrado poner fin al conflicto primario, siempre que no exista un interés público prevalente. 7.- Cuando con la Fiscalía estime indispensable, respecto de alguna persona imputada para asegurar el esclarecimiento del hecho o el éxito de la pesquisa respecto de otros autores, coautores o partícipes necesarios que se consideren más relevantes y aquel hubiera dado datos o indicaciones “conducentes al efecto. La persona imputada beneficiada quedará obligada a prestar declaración como testigo y en caso de ser convocada deberá ser informada fehacientemente de esta obligación antes de disponerse el archivo. No corresponderá la aplicación de un criterio de oportunidad en los casos de delitos cometidos por funcionarios públicos en el ejercicio de su cargo o por razón de él. La decisión del Ministerio Público Fiscal sobre la aplicación o no del principio de oportunidad no es recurrible. Contra ella sólo procederá el derecho de la víctima a requerir su revisión interna.-"},{"n":106,"r":"EFECTOS","t":"EFECTOS. La decisión que prescinda de la persecución penal pública por aplicación de criterios de oportunidad determinará que la jueza o juez, siempre que se hubiese procedido a la formulación de cargos, declare extinguida la acción pública con relación al participante en cuyo favor se decide y se procederá al archivo. Caso contrario, será la o el fiscal quien archivará directamente el caso, sin posibilidad de reabrirlo. Sin embargo, el archivo no extinguirá la acción penal, cuando la víctima, constituida en parte, continúe con el ejercicio de la acción penal en forma particular.- SECCIÓN SEGUNDA CONCILIACIÓN — MEDIACIÓN"},{"n":107,"r":"CONCILIACIÓN","t":"CONCILIACIÓN. La persona imputada y la víctima pueden realizar acuerdos conciliatorios hasta la audiencia de control de la acusación, en los casos de delitos con contenido patrimonial cometidos sin grave violencia sobre las personas o en los delitos culposos, si no existen lesiones gravísimas o resultado de muerte. La conciliación no procede en los siguientes casos.- 4.- Cuando se trate de delitos sancionados con pena de prisión mayor a seis (6) años en abstracto. 2.- Cuando se trate de delitos que exigen para su realización la calidad de funcionario público como sujeto activo o que son cometidos en perjuicio de la administración pública. 3.- Cuando la víctima es menor de edad, con excepción de los delitos previstos en las Leyes Nacionales N* 13.944 (Incumplimiento de los Deberes a la Asistencia Familiar), y N* 24.270 (Impedimento u Obstrucción del Contacto de Menores de Edad con sus Padres no Convivientes). [ES COPIA Fiel DEL ORIGINAL: 4.- Cuando se trate de alguno de los delitos previstos en el Libro Segundo del Código Penal, Título |, Capítulo |: Delitos Contra la Vida; Título III: Delitos Contra la Integridad Sexual; Título X: Delitos Contra los Poderes Públicos y el Orden Constitucional.-"},{"n":108,"r":"","t":"PROCEDIMIENTO y EFECTOS DE LA CONCILIACIÓN. El acuerdo de conciliación se debe presentar ante la fiscalía y si no existe oposición de la fiscal o el fiscal del caso, se podrá solicitar una audiencia ante la jueza o juez de garantía o control para su homologación. En caso de oposición al acuerdo por parte de la fiscalía, las partes pueden acudir ante el superior de la o el fiscal para su revisión. La acreditación del cumplimiento del acuerdo extingue la acción penal; hasta tanto no se acredite dicho cumplimiento, el legajo debe ser reservado. Ante el incumplimiento del acuerdo, la víctima o la fiscalía pueden solicitar la reapertura de la investigación.-"},{"n":109,"r":"MEDIACIÓN","t":"MEDIACIÓN. A los efectos de lograr un acuerdo conciliatorio, la o el fiscal puede, de oficio o a petición de partes, someter el conflicto a mediación, hasta el cierre de la investigación penal preparatoria. En este caso, la o el fiscal debe dar intervención a un mediador oficial para la solución del conflicto. El procedimiento de mediación no puede exceder el plazo de treinta (30) días y se rige por los principios de voluntariedad, confidencialidad, celeridad e imparcialidad.-"},{"n":110,"r":"EFECTOS DE LA MEDIACIÓN","t":"EFECTOS DE LA MEDIACIÓN. Cuando se arribe a un acuerdo, la mediadora o el mediador oficial a cargo de la mediación lo debe comunicar a la o el fiscal interviniente dentro del plazo de tres (3) días, acompañando copia del acta respectiva y se reservarán las actuaciones hasta que se acredite el cumplimiento del acuerdo. En caso de cumplimiento del acuerdo, la o el fiscal o cualquiera de las partes deben instar el sobreseimiento ante la jueza o juez de Control o Garantías. Si se incumple el acuerdo, se debe eliminar toda referencia de éste del legajo de la fiscalía y no puede ser utilizado como fuente ni como medio de prueba. Si no se llega a un acuerdo, se debe labrar acta con copia para las partes y efectuar la correspondiente comunicación a la o el fiscal en el plazo de tres (3) días. La derivación del caso a mediación, después de la formalización de la investigación penal preparatoria, suspende el plazo de la investigación, el que sólo se reanuda con el informe de falta de acuerdo o ante el incumplimiento de este por parte del imputado. En el caso en que la víctima dificulte a la persona imputada el cumplimiento del acuerdo, ésta puede depositar en consignación la prestación a la que se ha obligado, dentro del mismo proceso penal.-"},{"n":111,"r":"REPARACIÓN INTEGRAL DEL PERJUICIO","t":"REPARACIÓN INTEGRAL DEL PERJUICIO. En los casos de los delitos previstos en el Título |, Capítulo !l: Lesiones Leves; Título VI, Capítulo !: Hurto Simple, Capítulo IV: Estafas, Defraudaciones Especiales, Defraudaciones Agravadas, con excepción del Fraude en perjuicio de Administración Pública, Defraudaciones menores, Usura; Capítulo VIl: Daño Simple; Título XIl, Capítulo VI: Libramiento de cheques sin provisión de fondos, del Código Penal, y en los plazos en los que procede la conciliación, la defensa de toda persona imputada podrá proponer ante la o el fiscal del caso el instituto de la reparación integral. : A PR Serial ¡ES COPIA FIEL DEL ORIGINAL! Recibido el planteo, no existiendo oposición de la víctima al mismo y previo consentimiento expreso de la o el fiscal, se presentará el acuerdo ante la jueza o juez del caso para su homologación si correspondiere. Si existe oposición de la víctima, en forma infundada o sin razón suficiente, no obsta a que el fiscal pueda presentar el acuerdo ante la jueza o juez para su evaluación y posible homologación. En caso que exista oposición de la víctima y la o el fiscal invoque razones justificadas de interés público prevalente en la persecución penal, no procede de ninguna manera la reparación integral del perjuicio. Ante la oposición de la o el fiscal, la persona imputada puede ocurrir ante la o el superior de la o el fiscal para la revisión de la decisión denegatoria.-"},{"n":112,"r":"CONTENIDO Y EFECTOS","t":"CONTENIDO Y EFECTOS. La resolución que hace lugar a la reparación integral del perjuicio debe contener la propuesta formulada, la opinión de las partes y el criterio objetivo seguido por la jueza o juez para establecer que la persona imputada la cumplirá. La jueza o juez debe dictar el sobreseimiento una vez cumplida la obligación asumida por la persona imputada. Hasta tanto se cumpla la obligación asumida, quedan suspendidos los plazos de duración del proceso penal.- SECCIÓN TERCERA SUSPENSION DEL JUICIO A PRUEBA"},{"n":113,"r":"SUSPENSIÓN DEL JUICIO A PRUEBA","t":"SUSPENSIÓN DEL JUICIO A PRUEBA. La persecución penal podrá ser suspendida a prueba cuando a la persona imputada pueda corresponderle una pena de prisión inferior a seis (6) años, siempre que no se trate de un delito imputado a una funcionaria o funcionario público ejecutado en ejercicio de sus funciones, que cause grave perjuicio al Estado. La solicitud será realizada por la Fiscalía y podrá efectuarse hasta el dictado del auto de apertura a juicio, debiéndose rechazar sin sustanciación, cualquier planteo posterior. Su procedencia requiere la conformidad de la persona imputada y su defensa técnica, la fiscalía actuará basándose en razones generales e igualitarias de política criminal. En la audiencia, a pedido de las partes, la jueza o juez resolverá las reglas de conductas que deberá cumplir la persona imputada y el plazo de cumplimiento. El contro! de las reglas de conducta para la suspensión del juicio a prueba estará a cargo de una Oficina Judicial, que dejará registro en forma periódica sobre el cumplimiento de las reglas y dará noticia a las partes de aquellas situaciones que pudieran dar base a una modificación o revocación del instituto. La víctima tendrá derecho a ser informada respecto del cumplimento de las condiciones impuestas. La Oficina de Gestión Administrativa deberá consultar a la víctima si desea ser informada acerca del cumplimiento de las condiciones; en ese caso, la víctima deberá fijar un domicilio, podrá asignar un representante legal y establecer el modo en que recibirá las comunicaciones. Cuando la persona imputada incumpliere las condiciones impuestas, la o el fiscal o la querella solicitará a la Oficina Judicial audiencia ante la jueza o juez para que las partes expongan sus fundamentos. La jueza o juez, según corresponda, podrá dar un plazo a la persona imputada para satisfacer las condiciones, modificarlas o revocar la suspensión del proceso a prueba. En este caso el procedimiento continuará de acuerdo a las reglas generales.- SECCIÓN CUARTA PUEBLOS INDIGENAS ARTÍCULO 114?.- PUEBLOS INDÍGENAS. Los fiscales no podrán iniciar o proseguir la persecución penal pública cuando el conflicto esté siendo juzgado o haya sido resuelto por las autoridades indígenas y siempre que el delito afecte bienes jurídicos propios de un pueblo indígena o bienes personales de alguno de sus miembros y tanto la persona imputada como la víctima o sus familiares sean integrantes de esa comunidad. La decisión de la autoridad indígena no deberá violar los derechos humanos fundamentales. Cuando un indígena sea juzgado por la justicia ordinaria deberá cumplirse con lo dispuesto por los instrumentos internacionales en esta materia.- TÍTULO Il MEDIDAS DE COERCIÓN Y CAUTELARES"},{"n":114,"r":"PUEBLOS INDÍGENAS","t":"PUEBLOS INDÍGENAS. Los fiscales no podrán iniciar o proseguir la persecución penal pública cuando el conflicto esté siendo juzgado o haya sido resuelto por las autoridades indígenas y siempre que el delito afecte bienes jurídicos propios de un pueblo indígena o bienes personales de alguno de sus miembros y tanto la persona imputada como la víctima o sus familiares sean integrantes de esa comunidad. La decisión de la autoridad indígena no deberá violar los derechos humanos fundamentales. Cuando un indígena sea juzgado por la justicia ordinaria deberá cumplirse con lo dispuesto por los instrumentos internacionales en esta materia.- TÍTULO Il MEDIDAS DE COERCIÓN Y CAUTELARES"},{"n":115,"r":"PRINCIPIOS GENERALES","t":"PRINCIPIOS GENERALES. Las medidas de coerción autorizadas se ajustarán a lo que disponen los Artículos 8%, 9% y 27% de este Código y su carácter es excepcional, necesario, proporcional y no podrán ser impuestas de oficio por la jueza o juez. Sólo se ejercerá coerción física para obtener la comparecencia de una persona cuando el mismo fin no pudiere lograrse en tiempo útil, ordenando su citación por las formas que prevé este Código.-"},{"n":116,"r":"MEDIDAS DE COERCIÓN","t":"MEDIDAS DE COERCIÓN. La fiscalía o el querellante podrán solicitar a la jueza o juez, en cualquier estado del proceso y con el fin de asegurar la comparecencia de la persona imputada o evitar el entorpecimiento del proceso, la imposición de cualquiera de las medidas que se indican a continuación: 1.- La promesa de la persona imputada de someterse al procedimiento y de no obstaculizar la investigación. 2.- La obligación de someterse al cuidado o vigilancia de una persona o institución determinada, en las condiciones que se le fijen. 3.- La obligación de presentarse periódicamente ante la jueza o juez o ante la autoridad que él designe. 4.- La prohibición de salir sin autorización previa del ámbito territorial que se determine. 5.- La retención de documentos de viaje. 6.- La prohibición de concurrir a determinadas reuniones o de visitar ciertos lugares o de comunicarse con personas determinadas, siempre que no se afecte el derecho a la defensa. 7.- El abandono inmediato del domicilio, cuando se trate de hechos de violencia doméstica y la víctima conviva con la persona imputada. i E E - 10.797 8.- La prestación por sí o por un tercero de una caución de contenido económico adecuada o la contratación de un seguro de caución. 9.- La vigilancia de la persona imputada mediante algún dispositivo electrónico de rastreo o posicionamiento de su ubicación física. 10.- El arresto en su propio domicilio o en el de otra persona, sin vigilancia o con la que la jueza o juez disponga. 11.- La prisión preventiva, en caso de que las medidas anteriores no fueren suficiente para asegurar los fines indicados. Siempre que el peligro de fuga o de entorpecimiento del proceso pueda ser evitado razonablemente por aplicación de otra medida menos gravosa para la persona imputada que la requerida por la fiscalía o la querella, la jueza o juez deberá imponerle alguna de las previstas en el presente Artículo, por un plazo predeterminado, en forma individual o combinada.-"},{"n":117,"r":"INCOMUNICACIÓN","t":"INCOMUNICACIÓN. La jueza o juez a pedido de la fiscalía y por resolución fundada podrá disponer la incomunicación de la persona imputada que se encuentre detenida por el término máximo de 24 horas, siempre que existan motivos concretos para temer que obstaculizará la averiguación de la verdad. La audiencia será sin público y sólo será convocado el peticionante. La fiscalía podrá disponer la incomunicación de la persona aprehendida, bajo las mismas condiciones, sólo por el plazo necesario para gestionar la orden judicial, que nunca excederá de 5 horas. La medida no impedirá que la persona imputada se comunique con una abogada o abogado, para que la represente y asista, antes de comenzar cualquier declaración o de realizar cualquier acto que requiera su intervención personal dentro del proceso. Se permitirá a la persona imputada el uso de libros, cuadernos o papeles para escribir y demás objetos que pidiere, con tal de que no puedan servir de medio para eludir la incomunicación; podrá también realizar actos civiles impostergables que no disminuyan su solvencia ni perjudiquen la investigación.-"},{"n":118,"r":"CAUCIONES","t":"CAUCIONES. Cuando procediera una caución, la jueza o juez, a pedido de parte, fijará en audiencia su tipo y monto y decidirá sobre la idoneidad de la persona fiadora, según la libre apreciación de las circunstancias del caso. Queda absolutamente prohibido fijar una caución de imposible cumplimiento para la persona imputada. La caución se depositará a la orden del tribunal o de la cuenta que la jueza o juez designe, en un banco oficial, salvo que autorizase a sustituir el depósito por la constitución de gravamen sobre un bien o mediante la contratación de un seguro de caución. Cuando la caución fuere prestada por otra persona distinta de la persona imputada, mediante la constitución de gravamen sobre un bien o un seguro de caución, ella asumirá solidariamente con aquella la obligación de pagar, sin beneficio de excusión, la suma que la jueza o juez haya fijado. La persona imputada y la fiadora podrán pedir autorización a la jueza o juez para sustituir la caución depositada, por otra equivalente, quien resolverá previa audiencia.- ¡ES COPIA FIEL DEL ORIGINAL]"},{"n":119,"r":"EJECUCIÓN DE LAS CAUCIONES","t":"EJECUCIÓN DE LAS CAUCIONES. En los casos de rebeldía o cuando la persona imputada se sustrajere a la ejecución de la pena, se fijará a la persona fiadora un plazo no menor de tres (3) días para que presente a la persona imputada o condenada, bajo la advertencia de que, si aquella no compareciere espontáneamente, o no es presentada por el fiador, la caución se ejecutará al término del plazo. Si se tratase del depósito de una suma de dinero ordenará su transferencia a la administración de la Función Judicial de la Provincia; si se tratase de otros bienes gravados, ordenará su subasta. Si se tratase de un seguro de caución intimará al dador del seguro para que deposite el dinero fijado como caución dentro del quinto día, bajo apercibimiento de ejecución.-"},{"n":120,"r":"CANCELACIÓN","t":"CANCELACIÓN. La caución será cancelada y liberados los bienes afectados a la garantía, siempre que no se hubiese ordenado su ejecución con anterioridad, cuando: 1.- La persona imputada fuere constituida en prisión. 2.- Se revoque la decisión de constituir cauciones, sean o no sean reemplazadas por otra medida. 3.- Por decisión firme, se absuelva o se sobresea a la persona imputada. 4.- Comience la ejecución de la pena privativa de libertad o ella no deba ejecutarse, 5.- La persona imputada fuese condenada a una pena no privativa de la libertad.-"},{"n":121,"r":"DETENCIÓN","t":"DETENCIÓN. La fiscalía podrá pedir la detención de la persona imputada cuando existan suficientes indicios para sostener razonablemente, que procedería la prisión preventiva, y aquella sea necesaria para preparar y fundar un pedido de imposición de esta medida. La detención durará el menor tiempo posible y no podrá superar las 48 horas sin el debido control jurisdiccional y de partes, en audiencia de control de detención.-"},{"n":122,"r":"DETENCIÓN SIN ORDEN JUDICIAL","t":"DETENCIÓN SIN ORDEN JUDICIAL. Sólo podrá privarse de la libertad de las personas con orden escrita de juez competente, salvo en los siguientes casos: 1.- Cuando haya sido sorprendida en flagrante delito; 2.- Se haya fugado de algún establecimiento penal o de cualquier otro lugar de detención. En caso de flagrancia, cualquier persona podrá practicar la aprehensión con la finalidad de impedir que el delito produzca consecuencias. La persona aprehendida será entregada inmediatamente a la autoridad más cercana. - 35 ¿ES GOPIA FIEL DEL ORIGINAL! O ——— o 1 0 \" 7 9 7 La autoridad que haya aprehendido a alguna persona lo deberá comunicar inmediatamente a la fiscalía, en un plazo que nunca podrá superar las 2 horas. Si la fiscalía estimare que debe mantenerse la privación de la libertad, la misma deberá ser requerida inmediatamente a la jueza o juez de control, en audiencia de control de detención, que no podrá superar las 48 horas. Si en ese plazo no se resolviera la aplicación de una medida de coerción privativa de libertad, el responsable del establecimiento donde se halle detenido el imputado lo dejará en libertad. El juez al inicio de la audiencia de formulación de cargos deberá realizar un control sobre la legalidad y condiciones de la detención.-"},{"n":123,"r":"FLAGRANCIA","t":"FLAGRANCIA. Habrá flagrancia cuando la persona autora del delito sea sorprendida en el momento de intentarlo o cometerlo, o inmediatamente después, o mientras sea perseguida, o cuando tenga objetos o presente rastros que permitan sostener razonablemente que acaba de participar de un delito.-"},{"n":124,"r":"LIMITACIONES A LA PRISIÓN PREVENTIVA","t":"LIMITACIONES A LA PRISIÓN PREVENTIVA. No procederá la prisión preventiva en los siguientes supuestos: 1.- Si por las características del hecho y las condiciones personales de la persona imputada pudiere resultar de aplicación una condena condicional o algunas de las modalidades de ejecución morigerada de la prisión, establecidas en la Ley N* 24.660. 2.- Cuando se trate de hechos cometidos en ejercicio de la libertad de expresión o como consecuencia de la crítica en cuestiones públicas. 3.- Enlos delitos de acción privada. 4.- Cuando se trate de personas mayores de setenta (70) años. 5.- Cuando se trate de mujeres o personas con capacidad de gestar en los últimos meses de embarazo. 6.- Cuando se trate de madres o personas con capacidad de gestar durante el primer año de lactancia de sus hijos. 7.- Cuando se trate de personas afectadas por una enfermedad grave y riesgosa. 8.- Cuando no haya peligro cierto de fuga o de entorpecimiento del proceso.-"},{"n":125,"r":"EMBARGO Y OTRAS MEDIDAS CAUTELARES","t":"EMBARGO Y OTRAS MEDIDAS CAUTELARES. La jueza o juez podrá ordenar en audiencia, a pedido de parte, el embargo de bienes, la inhibición de la persona imputada y demás medidas cautelares necesarias para garantizar la pena pecuniaria y las costas, de conformidad con las disposiciones del Código Procesal Civil y Comercial de la Provincia.- A e EQ DNA CNN SE AAA: (ES COPIA FIEL DEL ORIGINAL:"},{"n":126,"r":"DESALOJOS FORZOSOS","t":"DESALOJOS FORZOSOS. En los casos por infracción al Artículo 181? del Código Penal, la jueza o juez, a pedido de la persona damnificada, podrá disponer provisionalmente el inmediato reintegro de la posesión o tenencia del inmueble, cuando del análisis de las condiciones fácticas, surja que, en principio, se encuentran reunidos los requisitos típicos, el derecho invocado por la persona damnificada fuere verosímil y exista peligro en la demora. La jueza o juez podrá fijar una caución si lo considerare necesario. Si no se reunieran los requisitos enumerados precedentemente, la jueza o juez rechazará el pedido. Sin perjuicio de ello, en caso de corresponder, pondrá en conocimiento a las autoridades administrativas competentes, pudiendo quien se dice la persona damnificada, ocurrir por la vía judicial idónea. No se ordenará el desalojo previa existencia de una auténtica oportunidad de consultar a las personas a desalojar y demás afectadas, en la audiencia prevista en el Artículo 130, mediando la presencia de funcionarios del gobierno o sus representantes en el desalojo, con identificación exacta de todas las personas a desalojar, a los efectos de dar una respuesta efectiva. No podrá efectuarse el desalojo cuando existan condiciones climáticas adversas o en horario nocturno, salvo que las personas afectadas presten su consentimiento."},{"n":127,"r":"CONDICIONES Y REQUISITOS","t":"CONDICIONES Y REQUISITOS. A! solicitar la imposición de una o varias de las medidas de coerción enumeradas en el Artículo 116% la o el fiscal o el querellante deberán: 1.- Acreditar que existen elementos de convicción suficientes para sostener razonablemente la existencia del hecho y la participación de la persona imputada en él. 2.- Justificar suficientemente con arreglo a las circunstancias del caso y a las personales de la persona imputada, la presunción de que no se someterá al proceso u obstaculizará el mismo. 3.- Indicar el plazo de duración necesario, según las circunstancias del caso. La jueza o juez controlará la legalidad y razonabilidad del requerimiento y resolverá fundadamente.-"},{"n":128,"r":"PELIGRO DE FUGA","t":"PELIGRO DE FUGA. Para decidir acerca del peligro de fuga se podrá tener en cuenta, entre otras, las siguientes pautas: 1.- Arraigo, determinado por el domicilio, residencia habitual, asiento de la familia y de sus negocios o trabajo, y las facilidades para abandonar el país o permanecer oculto y demás cuestiones que influyan en el arraigo de la persona imputada. 2.- El comportamiento de la persona imputada durante el procedimiento, en la medida en que indique cuál es su voluntad de someterse a la persecución penal, y en particular, si incurrió en rebeldía o si hubiese ocultado información sobre su identidad o domicilio, o si hubiese proporcionado una falsa.- TEO PASA E A ABTURA E LES COPÍA FIEL Des, ORIGINAL] - 10.797"},{"n":129,"r":"PELIGRO DE ENTORPECIMIENTO Y RIESGO DE LA VÍCTIMA","t":"PELIGRO DE ENTORPECIMIENTO Y RIESGO DE LA VÍCTIMA. Para decidir acerca del peligro de entorpecimiento del proceso se tendrá en cuenta la existencia de vehementes indicios que justifiquen la grave sospecha de que la persona imputada: 1.- — Destruirá, modificará, ocultará, suprimirá o falsificará elementos de prueba. 2.- Influirá para que testigos o peritos informen falsamente o se comporten de manera desleal o reticente. 3.- Inducirá a otros a realizar tales comportamientos. 4.- Producirá actos intimidatorios, amenazantes en contra de la víctima o de su familia o violatorios de las medidas cautelares impuestas.-"},{"n":130,"r":"PROCEDIMIENTO","t":"PROCEDIMIENTO. El requerimiento de una medida de coerción se formulará y decidirá en audiencia, garantizando los principios de contradicción, inmediación, publicidad y celeridad. No se podrá aplicar una medida de coerción sin expreso pedido del fiscal o el querellante. En dicha audiencia, el fiscal deberá especificar el plazo de duración de la medida y el plazo requerido para llevar adelante la investigación penal preparatoria. En el caso de que sea solicitada únicamente por el querellante, también deberá exponer la duración y los motivos de su extensión. Cuando se solicite la prisión preventiva de la persona imputada que se encuentre previamente detenida, la audiencia deberá celebrarse dentro del plazo máximo de 48 horas contadas desde que la detención tuvo lugar. La jueza o juez dará a la persona imputada la oportunidad de ser oída, con la asistencia e intervención de su defensa técnica, quienes también podrán cuestionar el lugar y demás condiciones donde cumplirá la prisión preventiva. Asimismo, escuchará al querellante, cuando solicite tomar intervención y resolverá inmediatamente el planteo. La resolución que imponga una medida de coerción deberá individualizar a la persona imputada, enunciará los hechos que se le atribuyan, su calificación legal, expresar las circunstancias que dan fundamento a la medida, fijar el plazo por el cual se establece y lugar de cumplimiento. Si se hubiere ordenado la prisión preventiva, se fijará el plazo de su duración que no podrá exceder de tres (3) meses, vencido el cual el juez, previa audiencia en el cual oirá a las partes, decidirá si corresponde o no su extensión. Las renovaciones que se dispongan individualmente no podrán exceder de tres (3) meses y serán resueltas por el mismo procedimiento hasta el límite máximo fijado legalmente. La resolución que imponga, renueve o rechace la prisión preventiva o cualquier otra medida de coerción será revisable ante el Tribunal de Impugnación, sin efecto suspensivo, dentro del plazo máximo de 72 horas. La defensa podrá requerir un plazo adicional para la celebración de la audiencia de revisión, siempre que esta petición esté fundada en la necesidad de un mayor tiempo para presentar nuevas evidencias con las que aún cuente. Cuando la decisión que se impugna sea dictada fuera de la Primera Circunscripción Judicial, por una jueza o juez de las restantes circunscripciones judiciales de la Provincia, el impugnante, en el mismo acto de interposición, podrá requerir a la Oficina Judicial que la realización de la audiencia se produzca de forma remota virtual.- . 38 (ES COPIA diz LL UNICA!"},{"n":131,"r":"LÍMITE TEMPORAL A LA PRISIÓN PREVENTIVA","t":"LÍMITE TEMPORAL A LA PRISIÓN PREVENTIVA. Sin perjuicio de lo establecido para los procedimientos especiales, la prisión preventiva no podrá exceder de dos (2) años. En los casos en que exista condena no firme a pena privativa de la libertad de cinco (5) años o más, el tiempo total de prisión preventiva en todas las etapas del proceso no podrá superar de tres (3) años. En todos los casos las juezas o jueces al autorizar una prisión preventiva fijarán el plazo de su duración y podrán condicionar su dictado a la presentación urgente de la acusación.-"},{"n":132,"r":"CESE DE LA PRISIÓN PREVENTIVA","t":"CESE DE LA PRISIÓN PREVENTIVA. La prisión preventiva cesará en los siguientes casos: 1.- Si se hubiere superado el plazo máximo establecido para la duración de la investigación preparatoria o prórroga, sin que se formulare la acusación. 2.- Sino se hubiese abierto la audiencia de juicio dentro del plazo establecido en este Código. 3.- Sino se hubiere resuelto la impugnación contra de la sentencia condenatoria dentro de los seis (6) meses desde su interposición. 4.- Cuando la persona imputada hubiere cumplido en prisión preventiva la pena solicitada por el fiscal. 5.- Cuando la persona imputada hubiere agotado en prisión preventiva un tiempo igual al de la pena impuesta por la sentencia no firme. 6.- Cuando la persona imputada hubiere sufrido en prisión preventiva un tiempo que, de haber existido condena, le habría permitido solicitar la libertad condicional o la libertad asistida. 7.- Cuando se hubiere alcanzado el mínimo legal establecido para la escala penal aplicable para el caso. Vencidos los plazos establecidos en los párrafos anteriores la persona imputada quedará automáticamente en libertad. No podrá imponerse nuevamente la prisión preventiva cuando una anterior hubiese cesado por cualquiera de las razones enunciadas precedentemente; ello sin perjuicio de las facultades para hacer comparecer a la persona imputada a los actos necesarios del proceso o de la aplicación de otras medidas de coerción.-"},{"n":133,"r":"INCUMPLIMIENTO","t":"INCUMPLIMIENTO. En caso de incumplimiento injustificado de las obligaciones impuestas a la persona imputada, la jueza o juez, a pedido del fiscal o del querellante, podrá sustituirlas o añadir nuevas, sin perjuicio de ordenar la ejecución de la caución económica dada. También podrá imponer la prisión preventiva si el incumplimiento persistente permite presumir que la persona imputada no se someterá al procedimiento o continuará obstaculizándolo.- CEN PATEAR IE TE MOI"},{"n":134,"r":"REVOCACIÓN O SUSTITUCIÓN","t":"REVOCACIÓN O SUSTITUCIÓN. La jueza o juez, de oficio o a petición de la persona imputada o su defensa, dispondrá la revocación o sustitución de la medida de coerción que hubiere sido impuesta, cuando hayan desaparecido los presupuestos en que se hubiere fundado su imposición. La solicitud será resuelta en audiencia con presencia de las partes, en un plazo que nunca podrá ser mayor de 72 horas. La resolución que rechace el pedido será revisable por pedido de la defensa o de la persona imputada dentro del plazo de 24 horas. Cuando subsistan las medidas cautelares en la fase de actos preliminares al debate, en la etapa del juicio oral, todas las cuestiones atinentes a la imposición, prórrogas, revocaciones o sustituciones, deberán ser dirimidas mediante audiencia que fijará la Oficina Judicial por ante el Juzgado de Control que actuó en las etapas anteriores al juicio.- TÍTULO Il ETAPA PREPARATORIA CAPÍTULO | NORMAS GENERALES"},{"n":135,"r":"FINALIDAD","t":"FINALIDAD. El Ministerio Público Fiscal practicará la investigación preparatoria con la finalidad de arribar a la solución del conflicto por cualquiera de las vías legalmente previstas y promover o desechar la realización del juicio.-"},{"n":136,"r":"ACTUACIONES","t":"ACTUACIONES. La fiscalía formará un legajo de la investigación sin formalidad alguna en donde se harán constar todos los elementos de prueba recolectados o descartados, que será accesible a todas las partes. En ningún caso podrá ser consultado por el órgano jurisdiccional. La defensa podrá formar su legajo de investigación el cual no será público. Tendrá amplias facultades de investigación y en caso de pretender entrevistar a testigos de la fiscalía o querella, deberá previamente hacérselo saber, para adoptar los recaudos necesarios para que víctimas y testigos puedan ejercer los derechos expresamente reconocidos en este Código. Las actuaciones de la investigación preparatoria no tendrán valor probatorio para fundar la condena del acusado, salvo aquellas que fueran recibidas de conformidad con las reglas del anticipo jurisdiccional de prueba, acuerdos probatorios o procedimientos abreviados. No obstante, podrán invocarse para solicitar o fundar una medida de coerción o cautelar, excepciones o el sobreseimiento, en cuyo caso la jueza o juez, en audiencia, podrá eventualmente requerir determinados documentos a las partes para cerciorarse de determinada información que haya sido controvertida.-"},{"n":137,"r":"ACTUACIÓN JURISDICCIONAL","t":"ACTUACIÓN JURISDICCIONAL. Corresponderá a la jueza o juez j realizar, a pedido de parte, los anticipos jurisdiccionales de prueba, resolver excepciones y demás peticiones propias de esta etapa, otorgar autorizaciones y controlar el cumplimiento de los principios y garantías procesales.-"},{"n":138,"r":"CITACIÓN","t":"CITACIÓN. La Oficina Judicial interviniente ordenará la comparecencia por simple citación de aquellas personas que fueren requeridas, bajo apercibimiento de ser conducidas por la fuerza pública. ¡PA AE FS RAP SAR - 10.797 Si el citado no se presentare en el término que se le fije, ni justificare un impedimento legítimo, la Oficina Judicial interviniente, a solicitud de parte interesada, dispondrá su comparecencia por medio de la fuerza pública, a los efectos de cumplir el acto para el que fue convocado.-"},{"n":139,"r":"RESERVA","t":"RESERVA. Cuando resulte indispensable para garantizar el éxito de la investigación, la fiscalía, por resolución fundada y por única vez, podrá disponer la reserva parcial del legajo de investigación por un plazo no superior a diez (10) días consecutivos. El plazo se podrá prorrogar hasta por otro igual. En ese caso, cualquiera de las partes podrá solicitar a la jueza o juez que examine los fundamentos de la disposición y ponga fin a la reserva. Cuando la eficacia de un acto particular dependa de la reserva parcial del legajo de investigación, la fiscalía, previa autorización de la jueza o juez en audiencia unilateral, podrá disponerla por el plazo que resulte indispensable para cumplir el acto en cuestión, que nunca superará las 48 horas. La revisión o autorización, salvo el caso del párrafo anterior, se resolverá en audiencia con la fiscalía y la defensa en forma inmediata, sin publicidad. En los supuestos en que la jueza o juez autorice o mantenga la medida, la reserva se extenderá a los registros pertinentes de la Oficina Judicial.- CAPÍTULO Il ACTOS INICIALES"},{"n":140,"r":"DENUNCIA","t":"DENUNCIA. Toda persona que tenga conocimiento de un delito de acción pública podrá denunciarlo ante la fiscalía o la policía. La denuncia podrá efectuarse en forma escrita o verbal, personalmente o por mandato especial. Cuando sea verbal se registrará en forma audiovisual y se labrará un acta que será suscripta por la persona denunciante; en la denuncia por mandato se requerirá una autorización expresa. En ambos casos, el o la persona responsable que la reciba comprobará y dejará constancia de la identidad y domicilio de la persona denunciante. En ningún caso se aceptará una denuncia anónima. La denuncia debe contener, en cuanto fuese posible, la relación circunstanciada -del hecho con indicación de sus partícipes, personas damnificadas, testigos y demás elementos que puedan conducir a su comprobación y calificación legal. Cuando la acción penal dependa de instancia privada, sólo podrá denunciar quien tenga facultad para instar.-"},{"n":141,"r":"OBLIGACIÓN DE DENUNCIAR","t":"OBLIGACIÓN DE DENUNCIAR. Deben denunciar el conocimiento que tienen sobre un hecho punible de acción pública, salvo los que requieren una instancia para su persecución, los funcionarios públicos que conozcan el hecho en ejercicio de sus funciones o con ocasión de ese ejercicio, las escribanas o escribanos y contadoras o contadores en los casos de fraude y evasión impositiva y las personas que por disposición de la ley, de la autoridad o por algún acto jurídico tengan a su cargo el manejo, la administración, el cuidado o control de bienes o intereses de una institución, entidad o persona, respecto de los delitos cometidos en perjuicio de ésta o de la masa o patrimonio puesto bajo su cargo o control, siempre que conozcan del hecho por el ejercicio de sus funciones. ¿E9 COPA Pe A En todos estos casos la denuncia no será obligatoria si razonablemente arriesga la persecución penal propia, la del cónyuge, conviviente o pariente dentro del cuarto grado de consanguinidad o segundo de afinidad, o cuando los hechos hubiesen sido conocidos bajo secreto profesional.-"},{"n":142,"r":"AVERIGUACIÓN PRELIMINAR","t":"AVERIGUACIÓN PRELIMINAR. Cuando la fiscalía tenga conocimiento directo de un delito de acción pública promoverá la averiguación preliminar, la que deberá ser concluida en el plazo de sesenta (60) días, a contar desde que se encontrare individualizada la persona imputada. Vencido el plazo, la fiscalía podrá solicitar a la jueza o juez, en audiencia, una prórroga de dicho plazo por el tiempo que se considere, el que deberá ser proporcional a la importancia de la investigación, la complejidad del caso y de las medidas pendientes de realización. La prórroga podrá ser otorgada por un plazo superior a la inicial, que no podrá superar los noventa (90) días. En los casos de delitos cometidos por funcionarios públicos en ejercicio de sus funciones, la averiguación preliminar no estará sujeta a plazo alguno. Los funcionarios de la policía que tengan noticia de un delito de acción pública lo informarán a la fiscalía inmediatamente, continuando la investigación bajo su dirección y control.-"},{"n":143,"r":"FORMALIZACIÓN DE LA IMPUTACIÓN","t":"FORMALIZACIÓN DE LA IMPUTACIÓN. La formalización de la imputación deberá ser realizada por la Fiscalía cuando en la Investigación Preliminar tuviere identificada a la persona imputada. El acto se hará en presencia del imputado y con asistencia letrada y deberá: a) Informar los hechos que le atribuye, descriptos en la forma más precisa y circunstanciada que permita el grado de verificación que haya alcanzado la investigación. b) Indicar las pruebas de cargo que considera suficientes para atribuirle los hechos. c) Le hará saber la tipificación penal que provisoriamente le adjudica a los hechos. La o el fiscal podrá delegar la realización del acto en una o un fiscal adjunto, funcionaria o funcionario jerarquizada/o de la fiscalía, cuando otras obligaciones funcionales impostergables le impidieran cumplirlo personalmente.-"},{"n":144,"r":"INFORMACIÓN DE DERECHOS","t":"INFORMACIÓN DE DERECHOS. COMPROMISOS DEL IMPUTADO, ADVERTENCIAS. Finalizada la comunicación de la información, la o el fiscal le hará saber a la persona imputada los derechos que le asisten, en especial su derecho a declarar ante la o el fiscal o ante la jueza o juez en cualquier momento. La persona imputada se comprometerá a: a) Someterse al proceso, presentarse a cada citación que se le curse y abstenerse de obstaculizar la investigación. A mn b) Informar sobre cualquier ausencia de su domicilio que pudiera prolongarse por más de un (1) mes. Por su parte, la o el fiscal le advertirá que de no presentarse a una citación de la fiscalía dispondrá su comparendo por la fuerza pública y que la ausencia prolongada de su domicilio dará motivo para que la jueza o juez ordene su detención y, en su caso, declare su rebeldía y disponga su captura.-"},{"n":145,"r":"REGISTRACIÓN","t":"REGISTRACIÓN. EFECTOS. El acto, en su totalidad, será registrado en soporte de audio o audiovisual. Si el fiscal hubiese delegado la realización del acto deberán quedar registradas las razones de la delegación. Separadamente se labrará un acta en la que se asentará la descripción del hecho que se ha imputado y la tipificación provisional adjudicada. La formalización de la imputación surtirá los efectos que prevé el Artículo 67* Inciso b) del Código Penal.-"},{"n":146,"r":"INTERVENCIÓN DE LA JUEZA O JUEZ","t":"INTERVENCIÓN DE LA JUEZA O JUEZ. La defensa, dentro de los diez (10) días de formalizada la imputación, podrá solicitar al juez una audiencia para plantear las excepciones y revisiones que considere procedentes. La audiencia se celebrará dentro de los cinco (5) días de solicitada.-"},{"n":147,"r":"MODIFICACIÓN O AMPLIACIÓN DE LA IMPUTACIÓN","t":"MODIFICACIÓN O AMPLIACIÓN DE LA IMPUTACIÓN. Si el fiscal, conforme a los resultados de la investigación, decidiera modificar los hechos de la formalización efectuada o ampliar la imputación en relación a hechos no contenidos en ella, convocará nuevamente al imputado y procederá a modificar o ampliar la imputación cumpliendo con los requisitos previstos en el Artículo 143\". En los casos de modificación o ampliación de la imputación, la defensa podrá proceder conforme a lo dispuesto por el"},{"n":148,"r":"PRESERVACIÓN DE LA ESCENA","t":"PRESERVACIÓN DE LA ESCENA. Cuando en el primer momento de la investigación de un hecho no sea posible individualizar a la persona autora, a los partícipes ni a los testigos y se deba proceder con urgencia para no perjudicar la investigación, la autoridad policial interviniente en el lugar podrá disponer que los presentes no se alejen del lugar ni se comuniquen entre sí antes de informar ni se modifique el estado de las cosas ni de los lugares. En ningún caso esa medida podrá superar las 6 horas debiendo informarse inmediatamente a la fiscalía.-"},{"n":149,"r":"VALORACIÓN INICIAL","t":"VALORACIÓN INICIAL. Dentro del: plazo estipulado para la finalización de la averiguación preliminar, la fiscalía dispondrá lo siguiente: 1.- La desestimación de la denuncia, querella o de las actuaciones policiales, si el hecho no constituye delito. 2.- La aplicación de un criterio de oportunidad. 3.- La remisión a una instancia de conciliación o mediación. 4.- —Elarchivo, si no se ha podido individualizar a la persona autora o partícipes o si es manifiesta la imposibilidad de reunir información o no se puede proceder. Z 1 0 197 5.- La apertura de la investigación preparatoria, determinando el objeto procesal y requiriendo audiencia de formulación de cargos. Ni la desestimación ni el archivo constituyen cosa juzgada y puede reabrirse la investigación si aparece nueva información conducente.-"},{"n":150,"r":"CONTROL DE LA DECISIÓN FISCAL","t":"CONTROL DE LA DECISIÓN FISCAL. Dentro del plazo de tres (3) días de notificada, la víctima podrá solicitar a la fiscalía del caso la revisión de la desestimación, archivo o la aplicación de criterios de oportunidad. El archivo será revisable por una o un fiscal superior que se determinará a través de los reglamentos y normativa de! Ministerio Público Fiscal. En el plazo de tres (3) días, si él o la fiscal superior decidiera que debe revocarse la decisión adoptada, dispondrá la sustitución del o la fiscal que intervenía en el caso y designará su sustituto para que continúe la investigación conforme a los parámetros fijados. . Cuando la o el fiscal superior confirmare el archivo, la decisión no será susceptible de revisión alguna. En estos casos, dentro del quinto día de notificada, la víctima estará habilitada para constituirse en parte si aún no era querellante, peticionar ante una jueza o juez la conversión de la acción penal pública en privada y continuar con el ejercicio de la acción penal en forma autónoma.-"},{"n":151,"r":"AUDIENCIA DE FORMULACIÓN DE CARGOS","t":"AUDIENCIA DE FORMULACIÓN DE CARGOS. Cuando la o el fiscal deba formalizar la investigación preparatoria respecto de una persona imputada, solicitará a la jueza o juez la realización de una audiencia, en el cual deberá individualizar a la persona imputada, indicar el hecho que se le atribuye, la fecha y lugar de su comisión, su calificación jurídica, el grado de participación si fuere posible y la información en la que lo sustenta. A esta audiencia se citará a la persona imputada, a su defensora o defensor y a las demás partes en el procedimiento. Si la o las personas imputadas se encontraren detenidas, la formulación de cargos se hará dentro de las 48 horas. En este caso, también se deberá controlar la legalidad y condiciones de la detención. Se deberá establecer el plazo de duración de la investigación preparatoria. Cuando se atribuyan nuevos hechos a un imputado cuya investigación preparatoria ya fue formalizada o se amplíe a nuevos imputados, se convocará a una nueva audiencia.- CAPÍTULO Ill DESARROLLO DE LA INVESTIGACION"},{"n":152,"r":"ATRIBUCIONES","t":"ATRIBUCIONES. El o la fiscal, la defensa y la querella en su caso, practicarán las diligencias y actuaciones de la investigación preparatoria que no tengan contenido jurisdiccional. Se permitirá la presencia de las partes en los actos que se practiquen, más su ausencia no será causal de invalidez. El Estado creará un fondo para posibilitar los trabajos de investigación de la Defensa Penal Pública. Por ley se lo instrumentará e integrará al presupuesto anual de la misma y se reglamentará la utilización y contralor de tal fondo.-"},{"n":153,"r":"INSPECCIÓN","t":"INSPECCIÓN. El o la fiscal podrá inspeccionar lugares y cosas, cuando exista motivo suficiente para presumir que se encontrarán elementos útiles a la investigación. EII TI (E Pas HL PER PEA IRE En toda orden de registro, que sólo la autoridad judicial podrá expedir a solicitud de la fiscalía o querellante particular, en su caso, se expresará el lugar que ha de inspeccionarse, la persona o personas que hayan de aprehenderse y los objetos que se buscan, a lo que únicamente debe limitarse la diligencia. La medida se registrará por medios audiovisuales y se levantará un acta que será firmada por, al menos, una (1) persona como testigo, que no pertenezca a la policía, propuesta por el ocupante del lugar inspeccionado o en su ausencia o negativa, por la autoridad que practique la diligencia. La persona testigo podrá pertenecer a la policía, en casos de urgencia o imposibilidad de conseguirlo, lo que deberá ser justificado. Para realizar las inspecciones o registros podrá ordenarse que durante la diligencia no se ausenten quienes se encuentren en el lugar o que cualquier otra persona comparezca inmediatamente."},{"n":154,"r":"REQUISA","t":"REQUISA. La requisa personal será efectuada por las o los funcionarios de la policía y fuerzas de seguridad, y sólo podrá llevarse a cabo con orden judicial, a excepción que: 4.- Concurran circunstancias previas o concomitantes que razonable y objetivamente permitan justificar la medida respecto de persona o vehículo determinado. 2.- Existan elementos que razonablemente impidan en razón de la urgencia obtener la orden en forma eficaz. 3.- Selleve a cabo en la vía pública o en lugares de acceso público. Antes de proceder a la requisa se deberá advertir a la persona acerca de la sospecha y del objeto buscado, invitándolo a exhibirlo. La advertencia y la inspección se realizarán en presencia de dos (2) testigos, que no podrán pertenecer a la policía, salvo en caso de suma urgencia o imposibilidad de conseguirlo, lo que deberá ser justificado. . Las requisas se practicarán separadamente, respetando el pudor y la dignidad de las personas. Las requisas de mujeres serán hechas por otras mujeres. En el supuesto que se hubiere actuado sin orden judicial, se deberá consignar bajo pena de invalidez, en forma detallada y precisa, las circunstancias que justificaron el accionar y la excepción a la regla.- :"},{"n":155,"r":"INFORMES DE EXPERTOS","t":"INFORMES DE EXPERTOS. Se podrán requerir informes a expertos o peritos cuando para descubrir o valorar alguna evidencia sea necesario poseer conocimientos especiales en alguna ciencia, arte o técnica. Las o los peritos deberán tener título habilitante o acreditar experiencia e idoneidad en la materia relativa al punto sobre el que serán requeridos. Los informes deberán ser fundados y contendrán, de manera clara y precisa, una relación detallada de las operaciones practicadas y sus resultados, las observaciones de las partes o de sus consultores técnicos y las conclusiones que se formulen respecto de : cada tema estudiado.- pa AD) Su ari Asusuatasr Í"},{"n":156,"r":"RECONOCIMIENTOS","t":"RECONOCIMIENTOS. Se podrá ordenar el reconocimiento de una persona aún sin su consentimiento, tomando los siguientes recaudos: Previo al inicio del reconocimiento que será dirigido por la jueza o juez designado al efecto, quien deba efectuarlo será interrogado por la o el fiscal o las demás partes, para que describa a la persona de que se trata, diga si antes de ese acto la ha conocido, o visto personalmente o en imagen fotográfica o de otro tipo, o si la ha vuelto a ver antes de la diligencia. La misma se practicará acto seguido advirtiéndole previamente a la persona reconociente que en la rueda de personas puede o no estar la persona a reconocer manifestada en su testimonio. La rueda se formará, además de la persona imputada, con al menos tres (3) personas de características morfológicas y vestimenta que sean similares a las de la persona imputada. La defensa podrá incorporar en la rueda a otras tres (3) personas. La persona imputada elegirá su colocación en la rueda y la reconociente procederá al reconocimiento desde donde no pueda ser vista, manifestando si se encuentra, entre las personas que conforman la rueda, la persona que describiera previamente. En caso afirmativo la designará específicamente, si es o no es, manifestando las diferencias y semejanzas que observara, entre su estado actual y el que presentaba en la época del hecho y qué conducta desplegó, conforme a lo referido en su declaración. Todo reconocimiento, fotográfico o en rueda de personas, deberá ser registrado en video filmación tanto el sector donde esté la persona a reconocer como la persona reconociente. Se deberá hacer constar el tiempo exacto que demandó el reconocimiento y luego, interrogar a la persona testigo para que explique cuáles han sido los motivos por los que reconoció al imputado. Los documentos, objetos y otros elementos de convicción podrán ser exhibidos a la persona imputada, a los testigos y a los peritos para que los reconozcan o informen sobre ellos. También se podrá ordenar el reconocimiento de voces, sonidos u otros objetos de percepción sensorial.-"},{"n":157,"r":"EXÁMENES CORPORALES","t":"EXÁMENES CORPORALES. Si fuere necesario para constatar circunstancias relevantes para la investigación, podrán efectuarse exámenes corporales a la persona imputada y a la presunta víctima por el hecho punible, tales como pruebas de carácter biológico, extracciones de sangre u otros análogos, siempre que no fuere de temer menoscabo para la salud o dignidad del interesado. Si la persona que ha de ser objeto del examen, informada de sus derechos, consintiere en hacerlo, la o el fiscal ordenará directamente que se le practique. En caso de negarse, se solicitará la correspondiente autorización judicial.-"},{"n":158,"r":"REGISTRO DE VEHÍCULOS Y OTRAS COSAS MUEBLES","t":"REGISTRO DE VEHÍCULOS Y OTRAS COSAS MUEBLES. Se podrá registrar un vehículo, siempre que haya motivos objetivos suficientes para presumir que una persona oculta en él objetos útiles a la investigación. En los mismos casos también procederá el registro de maletines, valijas, bolsos, armarios, escritorios, gabinetes u otros muebles cerrados. En lo que sea aplicable, se realizará el procedimiento y se cumplirán las formalidades previstas para la requisa de personas.-"},{"n":159,"r":"ALLANAMIENTO Y REGISTRO DE MORADA","t":"ALLANAMIENTO Y REGISTRO DE MORADA. Si el registro debe efectuarse en un lugar destinado a habitación, residencia particular o sus dependencias cerradas, el allanamiento se debe realizar en horario diurno. Excepcionalmente, en los 46 ] AO A ORIGINAL | | E 25 ee A Pais ib OPIGINAL casos en que existe peligro en la demora, se puede proceder al allanamiento en cualquier horario. La orden de la jueza o juez que lo disponga deberá explicitar las circunstancias extraordinarias. El allanamiento será autorizado por la jueza o juez por escrito, en el marco del Artículo 35% de la Constitución Provincial. La comunicación de la orden a quien se le encomiende el allanamiento podrá realizarse por medios electrónicos. En ese caso, la persona destinataria de la orden comunicará inmediatamente su recepción a la jueza o juez emisor y corroborará que los datos de la orden sean correctos. En el caso de correo electrónico u otro medio similar se hará mediante uso de firma digital. Cuando por existir evidente riesgo para la seguridad de los testigos de actuación, cuando fuera necesario que la autoridad preventora irrumpa en el lugar previamente, lo hará por el tiempo estrictamente necesario para neutralizar el peligro. Procederá a continuación a hacer ingresar necesariamente a los testigos de actuación.-"},{"n":160,"r":"AUTORIZACIÓN","t":"AUTORIZACIÓN. La fiscalía deberá solicitar a la jueza o juez en audiencia unilateral y sin publicidad, la autorización para el allanamiento por cualquier medio siempre y cuando sea fundado, y contenga: 1.- La determinación concreta del lugar o los lugares que deberán ser registrados. 2.- La finalidad del registro, mencionando los objetos a secuestrar o las personas a detener. 3.- La identidad del o la fiscal responsable del control o de la ejecución de la medida y, en caso de delegación, el funcionario que se encuentra autorizado a diligenciarlo. 4.- Los motivos que fundan la necesidad del allanamiento. La juez o juez resolverá en audiencia la procedencia de la medida, constatando los requisitos formales como la razonabilidad de los motivos. En el caso de autorizar la medida, deberá hacer constar la fecha y el horario de la ejecución de la misma. Una copia será reservada en el legajo de la oficina judicial y otra será entregada a la persona titular o encargada, a quien se encuentre en el domicilio o a un vecino en el momento del allanamiento.- :"},{"n":161,"r":"ALLANAMIENTO SIN AUTORIZACIÓN JUDICIAL","t":"ALLANAMIENTO SIN AUTORIZACIÓN JUDICIAL. Podrá procederse al allanamiento sin orden judicial cuando: 4.- Si por incendio, inundación u otra causa semejante se hallare amenazada la vida de los habitantes o la propiedad. 2.- Ante el anoticiamiento que personas extrañas han sido vistas mientras se introducían en una casa o local, con indicios manifiestos de ir a cometer un delito. 3.- Si voces provenientes de un inmueble anunciaren que se está cometiendo un delito, o desde ella pidieran socorro. AA AA - 1 0 ” 797 4.- En caso de que se introduzca en una propiedad ajena alguna persona a quién se persiga para su aprehensión.-"},{"n":162,"r":"ENTREGA DE OBJETOS O DOCUMENTOS","t":"ENTREGA DE OBJETOS O DOCUMENTOS. Todo aquel que tenga en su poder objetos o documentos que puedan servir como medio de prueba estará obligado a presentarlos y entregarlos cuando le sean requeridos, siendo de aplicación las medidas de coacción permitidas para el testigo que rehúsa declarar. Si los objetos requeridos no son entregados se dispondrá su secuestro. Quedan exceptuadas de esa obligación las personas que deban o puedan abstenerse de declarar como testigos.-"},{"n":163,"r":"PROCEDIMIENTO PARA EL SECUESTRO","t":"PROCEDIMIENTO PARA EL SECUESTRO. De todo lo obrado durante la diligencia de registro deberá dejarse constancia audiovisual y/o escrita. Los objetos y documentos que se incautaren serán puestos en custodia y sellados, entregándose un recibo detallado de los mismos al propietario o encargado del lugar. Se establecerá una cadena de custodia que resguardará la identidad, estado y conservación de todos aquellos objetos secuestrados, con el fin de asegurar los elementos de prueba. Se identificará a todas las personas que hayan tomado contacto con esos elementos, siendo responsables los funcionarios públicos y particulares intervinientes. : Podrá disponerse la obtención de copias, reproducciones o imágenes de los objetos cuando resulte más conveniente para la investigación.-"},{"n":164,"r":"OBJETOS NO SOMETIDOS A SECUESTRO","t":"OBJETOS NO SOMETIDOS A SECUESTRO. No podrán ser objeto de secuestro: 1.- Las comunicaciones entre las personas imputadas con las personas obligadas a guardar secreto profesional, 2.- Las notas que hayan tomado los nombrados anteriormente sobre comunicaciones confiadas por la persona imputada o sobre cualquier circunstancia a la cual se extienda el derecho o el deber de abstenerse de declarar. 3.- Los resultados de exámenes o diagnósticos relativos a las ciencias médicas realizados a la persona imputada bajo secreto profesional. La limitación sólo regirá cuando las comunicaciones u objetos estén en poder de aquellas personas que deban abstenerse de declarar o en el caso de profesionales obligados por el secreto profesional, si están en su poder o archivadas en sus oficinas o en establecimientos hospitalarios.-"},{"n":165,"r":"INTERCEPTACIÓN DE COMUNICACIONES","t":"INTERCEPTACIÓN DE COMUNICACIONES. Si fuere útil para la averiguación de la existencia del hecho y sus circunstancias de comisión, con autorización judicial, se procurará la obtención, aun en tiempo real, de los datos de tráfico de las comunicaciones transmitidas por un sistema informático y también el contenido de las mismas; podrá ordenarse: 4.- El secuestro de correspondencia epistolar. 2.- La interceptación, por cualquier medio técnico, de otras formas de comunicación personal. Pee A Lao UTA o a e A AAA o ron. 3.- La obtención, aún en tiempo real, de los datos de tráfico de las comunicaciones transmitidas por un sistema informático y también el contenido de las mismas. Estas medidas tendrán carácter excepcional y deberán ser requeridas del mismo modo que el allanamiento, debiendo el juez fijar un plazo prudencial para su producción. Su prórroga deberá justificarse y no podrá superar los noventa (90) días.-"},{"n":166,"r":"APERTURA Y EXAMEN DE CORRESPONDENCIA","t":"APERTURA Y EXAMEN DE CORRESPONDENCIA. SECUESTRO. Recibida la correspondencia o efectos interceptados, el Ministerio Público Fiscal procederá a su apertura. Examinará los objetos y leerá el contenido de la correspondencia. El Ministerio Público Fiscal en audiencia unilateral explicará los fundamentos por los cuales solicita mantener el secuestro de los objetos que tuvieran relación con el proceso. Del resto de los efectos la jueza o juez mantendrá la reserva del contenido y dispondrá la entrega al destinatario o a sus representantes o parientes próximos, bajo constancia. Regirán las limitaciones del secuestro de cosas y de preservación de la cadena de custodia.-"},{"n":167,"r":"INTERCEPTACIONES TELEFÓNICAS","t":"INTERCEPTACIONES TELEFÓNICAS. Cuando existieren fundadas sospechas, basadas en hechos determinados, que una persona cometió un hecho punible o participó o participa en la preparación o comisión y la investigación lo hiciere imprescindible, la jueza o juez a pedido de parte podrá ordenar, mediante resolución fundada, la intervención de comunicaciones telefónicas de la persona imputada, por un plazo prudencial, que no podrá exceder de sesenta (60) días. La jueza o juez, a pedido de parte, podrá prorrogar el plazo por períodos de igual término que el fijado con anterioridad. La petición de renovación deberá ser efectuada por el fiscal superior. No podrán interceptarse las comunicaciones telefónicas entre la persona imputada y su defensa. En ningún caso la desgrabación por escrito, podrá ser utilizada como prueba documental. No podrán interceptarse las comunicaciones de la persona imputada con sus defensoras o defensores. 1.- Personas afectadas. La medida descripta precedentemente sólo podrá afectar a la persona imputada o a personas respecto de las cuales existieren sospechas fundadas, basadas en hechos determinados, de que ellas sirven de intermediarias de dichas comunicaciones y, asimismo, de aquellas que facilitaren sus medios de comunicación a la persona imputada o sus intermediarios. 2.- Requisitos de la orden de interceptación. La orden que dispusiere la interceptación y grabación deberá indicar circunstanciadamente nombre y dirección de la persona afectada por la medida y señalar la forma de interceptación y la duración de la misma. 3.- Deber de colaboración. Obligación de guardar secreto. Las empresas telefónicas y de comunicaciones deberán otorgar a los funcionarios encargados de la diligencia las facilidades necesarias para cumplirlas. Asimismo, los encargados de realizar la diligencia y los empleados de las empresas mencionadas deberán guardar secreto de todo conocimiento que tomarán como consecuencia de la medida, bajo responsabilidad personal, salvo que se les citare como testigos al proceso. LO LUMA CEL EL AL) e 1 0 1] 7 9 7 4.- Interrupción. Casos. Si las sospechas que motivaron ordenar la medida desaparecieran o hubiere transcurrido el plazo de duración fijado, ella deberá ser interrumpida inmediatamente. 5.- Métodos de Interceptación. La interceptación telefónica será registrada mediante su grabación magnetofónica u otros medios técnicos análogos que aseguren la fidelidad del registro. En tal caso, ordenarán la versión escrita de la grabación por un funcionario que deberá responder por la fidelidad de aquella, bajo su responsabilidad personal, sin perjuicio que deberán guardarse los originales. Caso contrario, mantendrá en reserva su contenido disponiendo la destrucción de toda la grabación o de las partes que no tengan utilidad, previa conformidad de la persona imputada y su defensa, o su entrega a las personas afectadas con la medida. 6.- Notificación al afectado. La medida de interceptación será notificada a la persona afectada c"},{"n":168,"r":"INFORMACIÓN DIGITAL","t":"INFORMACIÓN DIGITAL. INCAUTACIÓN DE DATOS. Cuando se hallaren dispositivos de almacenamiento de datos informáticos que por las circunstancias . del caso hicieren presumir que contienen información útil a la investigación, se procederá a su secuestro, y de no ser posible, se obtendrá una copia o podrá ordenarse la conservación de los datos contenidos en los mismos por un plazo que no podrá superar los noventa (90) días. Quien deba cumplir esta orden deberá adoptar las medidas necesarias para mantenerla en secreto. También podrá disponerse el registro del dispositivo por medios técnicos y en forma remota. FUNCION LEGISLATIVA : A cualquier persona física o jurídica que preste un servicio a distancia por vía electrónica, podrá requerírsele la entrega de la información que esté bajo su poder o control referida a los usuarios o abonados, o los datos de los mismos. Las empresas que brinden el servicio de comunicación deberán posibilitar el cumplimiento inmediato de la diligencia, bajo apercibimiento de incurrir en responsabilidad penal. La información que no resulte útil a la investigación no podrá ser utilizada y deberá ser devuelta, previo ser puesta a disposición de la defensa que podrá pedir su preservación. Regirán las limitaciones aplicables a los documentos. Las modalidades de actuación para secuestro, identificación y adquisición de videos de cámaras de seguridad generados en un Grabador de Video en Red (Network Video Recorder-NVR-) o una Grabadora de Video Digital (Digital Video Recorder -DVR-), serán determinadas en el protocolo que dicte el Tribunal Superior de Justicia, asegurando la cadena de custodia de la evidencia obtenida.-"},{"n":169,"r":"AGENTE ENCUBIERTO DIGITAL","t":"AGENTE ENCUBIERTO DIGITAL. En los casos de investigación de delitos en que resulte necesaria la intervención del agente en entornos o plataformas digitales, la o el fiscal podrá requerir fundadamente al juez de control la actuación encubierta de un agente bajo las premisas anteriores y las condiciones aquí previstas. La autorización de este medio de investigación excepcional, se emitirá por decreto fundado, en el marco de la investigación de delitos previstos en los Artículos 128% y 131\" del Código Penal, en delitos concretos de especial gravedad o de investigación compleja y siempre que existan motivos suficientes que acrediten: a) Que el éxito de la investigación esté seriamente dificultado de no recurrirse a este medio, b) Que se trata de delitos cometidos a través de medios informáticos que no permiten otra forma de investigación. La actuación encubierta no podrá exceder de ciento ochenta (180) días a contar desde que la autorización otorgada por la jueza o juez de control sea notificada a la o el fiscal. Los perfiles o identidades digitales, en ningún caso podrán ser imágenes de personas reales, serán creados y administrados por personal técnico idóneo del Ministerio Público fiscal, funcionarios o auxiliares de la Fuerza de Seguridad en Función Judicial con experiencia y desarrollo en la materia, y bajo el control directo de la o el fiscal a cargo de la investigación, quien hará constar las directivas, reservando en caja de seguridad: 1) La denominación y características del perfil utilizado por el agente encubierto; 2) Plataformas digitales donde se actuará; 3) Claves de acceso validadas y; 4) Actividad concreta a desarrollar por el agente. Una vez concluida la intervención del agente encubierto digital, la o el fiscal dejará constancias de su existencia en el legajo. El agente encubierto digital, con autorización específica para ello, podrá intercambiar o enviar por sí mismo archivos ilícitos por razón de su contenido. El agente encubierto digital estará exento de responsabilidad criminal por aquellas actuaciones que sean consecuencia necesaria del desarrollo de la investigación, siempre que guarden la debida proporcionalidad con la finalidad de ésta y no constituyan una provocación al delito. los efectos del presente Artículo se considera agente encubierto digital al funcionario de - 10.797 las fuerzas de seguridad o miembro del Ministerio Público Fiscal autorizado, que previo prestar su consentimiento, oculte o utilice un perfil digital encubierto, interactúe y se relacione digitalmente a través de tecnologías de la información y de la comunicación con el objeto de: 1) Identificar o detener a los autores, partícipes o encubridores de un delito; 2) Impedir la consumación de un delito; o 3) Para reunir información o elementos de prueba necesarios para la investigación.-"},{"n":170,"r":"ORDEN DE PRESENTACIÓN DE DATOS INFORMÁTICOS","t":"ORDEN DE PRESENTACIÓN DE DATOS INFORMÁTICOS. Siempre que se vincule con la investigación de un delito de su competencia, la o el Fiscal podrá ordenar por resolución fundada, a cualquier persona humana o jurídica en el territorio provincial, la presentación de datos informáticos, electrónicos o digitales o en un dispositivo de almacenamiento informático que obre en su poder o bajo su control, relativos a la identificación o localización u otra información asociada de un usuario y/o abonado, y que se pueda acceder al sistema legítimamente aunque no se encuentre dentro del territorio. La o el fiscal podrá ordenar a toda persona humana o jurídica que preste un servicio de comunicaciones o a los proveedores de internet de cualquier clase en jurisdicción argentina, la entrega de datos personales o de identificación de los usuarios y/o abonados u otra información asociada, que tengan bajo su poder o a los que pueda acceder de manera legítima, aunque estén fuera de esa jurisdicción. La orden podrá contener la indicación de que la medida deberá mantenerse secreta bajo apercibimiento de sanción penal y con las limitaciones establecidas en el Artículo 164? de este código. El destinatario quedará obligado a adoptar todas las medidas técnicas de seguridad necesarias, para mantener en secreto la medida ordenada por la jueza o juez.- ARTÍCULO 171”.. ASEGURAMIENTO DE DATOS INFORMÁTICOS ALMACENADOS. Cuando existieren motivos para sospechar que los datos almacenados en un sistema informático dentro del territorio provincial pudieren ser alterados o suprimidos, la o el Fiscal podrá ordenar a cualquier persona humana o jurídica el aseguramiento de datos informáticos concretos y que estén a su disposición o para el que tiene legítimo acceso. Dicho aseguramiento podrá consistir en la conservación rápida de datos informáticos almacenados y la conservación y revelación parcial rápida de datos relativos al tráfico. La orden deberá especificar los datos concretos que se pretende conservar y la duración de la medida que no podrá exceder de noventa (90) días, prorrogables por igual periodo si se mantuvieren los motivos que fundamentaron la orden. La persona requerida deberá mantener en secreto la medida bajo apercibimiento de sanción penal.-"},{"n":171,"r":"ASEGURAMIENTO DE DATOS INFORMÁTICOS ALMACENADOS","t":"ASEGURAMIENTO DE DATOS INFORMÁTICOS ALMACENADOS. Cuando existieren motivos para sospechar que los datos almacenados en un sistema informático dentro del territorio provincial pudieren ser alterados o suprimidos, la o el Fiscal podrá ordenar a cualquier persona humana o jurídica el aseguramiento de datos informáticos concretos y que estén a su disposición o para el que tiene legítimo acceso. Dicho aseguramiento podrá consistir en la conservación rápida de datos informáticos almacenados y la conservación y revelación parcial rápida de datos relativos al tráfico. La orden deberá especificar los datos concretos que se pretende conservar y la duración de la medida que no podrá exceder de noventa (90) días, prorrogables por igual periodo si se mantuvieren los motivos que fundamentaron la orden. La persona requerida deberá mantener en secreto la medida bajo apercibimiento de sanción penal.-"},{"n":172,"r":"SECUESTRO, APERTURA Y ANÁLISIS","t":"SECUESTRO, APERTURA Y ANÁLISIS. DE SISTEMA INFORMÁTICO E INCAUTACIÓN DE DATOS. A pedido de la o el fiscal, la jueza o juez de control podrá ordenar por decreto fundado, el registro de un sistema informático o de una parte de éste o de un medio de almacenamiento de datos informáticos o electrónicos, con el objeto de secuestrar los componentes del sistema, obtener copia o preservar datos o elementos de interés para la investigación, bajo las condiciones y limitaciones establecidas en este código para el registro de personas, lugares y cosas. La ejecución de la actuación se hará bajo la responsabilidad de la o el fiscal que solicitó la medida y necesariamente la o el fiscal deberá indicar a la jueza o juez: 52 : A e j O IA lla nds AGINAL. a) La individualización de los dispositivos o sistemas informáticos que serán objeto del registro. b) Una descripción del objeto concreto de la medida. c) La identificación de los mecanismos, metodología y herramientas mediante los cuales se almacenará la información obtenida que permitan asegurar la integridad de los datos y el resguardo de la cadena de custodia. d) El funcionario y/o quien designe como encargado de la ejecución del registro, copia o incautación de datos. Rigen en cuanto son aplicables todos los límites y garantías referidos al secuestro de cosas, documentos privados y correspondencia epistolar. En caso de que durante la ejecución de esta medida surjan elementos que permitan considerar que los datos buscados se encuentran almacenados en otro dispositivo o sistema conectado a la inicial o estén disponibles para éste dentro de la misma jurisdicción, quienes lleven adelante la medida podrán extenderla o ampliar el registro al otro sistema, previa comunicación con la o el Fiscal actuante, quien deberá solicitar autorización telefónica de la Jueza o Juez de Control competente. La mencionada comunicación no podrá ser delegada por la o el Fiscal actuante a ningún funcionario judicial. La o el Juez, por decreto fundado deberá disponer la autorización o rechazo de la medida, notificándola por correo electrónico y/o en forma telefónica. En caso que la medida sea autorizada, la o el Fiscal deberá acompañar por escrito la solicitud fundada dentro de las 48 horas de realizada la medida. En caso de ser necesario, por la complejidad del asunto la o el Juez podrá librar la orden, consignando únicamente su parte dispositiva, difiiéndose los fundamentos de las mismas. Esta se efectuará, bajo pena de nulidad, en el plazo máximo de 24 horas a contar del momento de autorización de la orden. En los supuestos en que los datos se encuentren almacenados en otra jurisdicción, la medida de registro de datos podrá ampliarse a dispositivos o sistemas informáticos, sólo en los siguientes supuestos: a) Cuando se obtenga el consentimiento voluntario y lícito de la persona con facultades para disponer de la revelación de los datos desde el dispositivo o sistema informático inicial al que se accedió legalmente. Las partes podrán a"},{"n":173,"r":"CLAUSURA DE LOCALES","t":"CLAUSURA DE LOCALES. Procederá a petición de parte la clausura cuando sea necesario para preservar la escena del hecho o inmovilizar cosas muebles que por su naturaleza o dimensiones no puedan ser trasladadas a otro lugar. La clausura podrá ser dispuesta por la o el fiscal siempre que existan razones urgentes y no podrá extenderse por más de 48 horas. Esta decisión deberá ser confirmada. Si es necesario mantener por más tiempo, deberá requerirlo a la jueza o juez.-"},{"n":174,"r":"CUSTODIA Y DEVOLUCIÓN DE LOS EFECTOS SECUESTRADOS","t":"CUSTODIA Y DEVOLUCIÓN DE LOS EFECTOS SECUESTRADOS. Los efectos secuestrados serán inventariados y puestos bajo segura custodia, a disposición del Ministerio Público Fiscal. Se podrá ordenar la obtención de copias o reproducciones de las cosas secuestradas si éstas pudieran desaparecer, alterarse o fueran de difícil custodia. Será obligación de las autoridades devolver los objetos secuestrados que no estén sometidos a decomiso, restitución o embargo a las personas legitimadas para poseerlos, inmediatamente después de realizadas las diligencias para las cuales se obtuvieron. Esta devolución podrá ordenarse provisionalmente, en calidad de depósito judicial y al poseedor se le podrá imponer la obligación de exhibirlos.-"},{"n":175,"r":"CADENA DE CUSTODIA","t":"CADENA DE CUSTODIA. Con el fin de asegurar los elementos de prueba, se establecerá una cadena de custodia que resguardará su identidad, estado y conservación. Se identificará a todas las personas que hayan tomado contacto con esos elementos, siendo responsables los funcionarios públicos y particulares intervinientes.-"},{"n":176,"r":"ANTICIPO JURISDICCIONAL DE PRUEBA","t":"ANTICIPO JURISDICCIONAL DE PRUEBA. Las partes podrán solicitar el anticipo jurisdicciona! de prueba únicamente en los siguientes casos: 1.- Cuando se trate de una diligencia de prueba que deba ser considerada de naturaleza no reproducible. 2.- Cuando se trate de un testimonio que por razones excepcionales y debidamente acreditadas se considere que no podrá recibirse durante el juicio. 3.- Cuando la persona imputada esté prófuga, o exista un obstáculo fundado en un privilegio constitucional y se tema que el transcurso del tiempo pueda dificultar o impedir la conservación de la prueba. ¡ES COPIA FIEL DEL ORIGINAL 4.- Cuando deba recibirse testimonio de víctimas y testigos menores de edad se tomará con la modalidad de Cámara Gesell y con el auxilio de profesionales especializados. En ese caso, previo a la iniciación del acto, la jueza o juez debe hacer saber al profesional a cargo de la entrevista las inquietudes propuestas por las partes, así como las que surgieren durante el transcurso del acto, las que deben ser canalizadas teniendo en cuenta las características del hecho y el estado emocional del menor, Sin perjuicio de ello, se podrá prescindir de esta modalidad, previa opinión favorable de la institución a cargo del cuidado del menor, si de las circunstancias del caso y de la edad del menor, no se advierte ningún riesgo para aquel. La jueza o juez examinará el pedido en audiencia, admitiendo o rechazando la solicitud. Todo anticipo probatorio deberá ser realizado frente a una jueza o juez y quedar registrado en soporte de video digital. En la audiencia preparatoria de juicio, las partes podrán debatir sobre la viabilidad de la admisión de la prueba en el juicio oral.-"},{"n":177,"r":"REALIZACIÓN","t":"REALIZACIÓN. La jueza o juez practicará el acto, citando la Oficina Judicial a todas las partes, quienes tendrán derecho de asistir, con las facultades y obligaciones previstas en este Código. La diligencia será documentada en la forma prevista en este código. La prueba quedará bajo la custodia de la o el fiscal, quien será responsable por su conservación inalterada, suministrando copia auténtica a las demás partes a su pedido, los que deberán aportar los soportes técnicos del caso.-"},{"n":178,"r":"PUBLICIDAD DE LAS ACTUACIONES","t":"PUBLICIDAD DE LAS ACTUACIONES. Quien invoque un interés legítimo será informado sobre el hecho que se investiga y sobre los imputados o detenidos que existan.-"},{"n":179,"r":"DURACIÓN","t":"DURACIÓN. La etapa preparatoria tendrá una duración máxima de cuatro (4) meses desde la formulación de cargos. Fenecido ese plazo, o en su caso, vencida la prórroga, sin que se emita el requerimiento de apertura a juicio, el incumplimiento constituirá falta grave de la o el representante del Ministerio Público Fiscal. No obstante, la persona imputada o el querellante podrán solicitar al juez que fije un plazo menor cuando no exista razón para la demora. Se resolverá en audiencia.-"},{"n":180,"r":"PRÓRROGA","t":"PRÓRROGA. Con anterioridad al vencimiento del plazo establecido en el Artículo anterior, la o el fiscal, la parte constituida como querellante o la persona imputada podrán solicitar a la jueza o juez una prórroga de la etapa preparatoria. A esos efectos, dentro de los tres (3) días, la jueza o juez convocará a las partes a una audiencia y, luego de escucharlas, establecerá prudencialmente el plazo en el cual la investigación preparatoria quedará cerrada, que nunca podrá exceder de noventa (90) días contados desde la fecha en que aquella tuvo lugar. Si fenecido el nuevo plazo la o el representante del Ministerio Público Fiscal o el querellante no formularen acusación, la jueza o juez procederá a intimarlos bajo apercibimiento de falta grave. Cuando una investigación preparatoria se hubiere formalizado respecto de varias personas imputadas, los plazos establecidos en estos Artículos correrán individualmente salvo que, por las características de los hechos atribuidos, no resultare posible cerrar la investigación preparatoria respecto de aquellos de manera independiente. cia COPIA FIEL dia URINAL: 1 0 . 797 Si con posterioridad a la formalización de la investigación preparatoria se descubrieran nuevos hechos o se individualizaran nuevas personas imputadas que obligaren a la ampliación de aquella los plazos establecidos comenzarán a correr desde este último acto. Los plazos previstos en este Artículo se suspenderán cuando: 1.- Se declare la rebeldía de la persona imputada. 2.- Se resuelva la suspensión del proceso a prueba. 3.- Desde que se alcanzare un acuerdo reparatorio hasta el cumplimiento de las obligaciones contraídas por la persona imputada a favor de la víctima o hasta que hubiere debidamente garantizado su cumplimiento a satisfacción de ésta última.- ) CAPÍTULO IV CONCLUSIÓN DE LA INVESTIGACIÓN PREPARATORIA"},{"n":181,"r":"ACTOS CONCLUSIVOS","t":"ACTOS CONCLUSIVOS. La etapa preparatoria concluirá a través de los siguientes actos: 1.- Con la acusación del o la fiscal o la parte querellante. 2.- Con el sobreseimiento. 3.- Con la suspensión del proceso a prueba. 4.- Con el cumplimiento de un acuerdo reparatorio.-"},{"n":182,"r":"SOBRESEIMIENTO","t":"SOBRESEIMIENTO. El sobreseimiento procederá cuando: 1.- El hecho no se cometió. 2.- La persona imputada no es autora o partícipe del mismo. 3.- El hecho no se adecua a una figura legal. 4.- Media una causa de justificación, inculpabilidad o ausencia de punibilidad. 5.- Porextinción de la acción penal. 6.- Agotada las tareas de investigación, no existe la posibilidad razonable de incorporar nuevos elementos de prueba ni fundamentos para requerir la apertura a juicio. 7.- Se ha aplicado un criterio de oportunidad, conciliación, reparación o suspensión del proceso a prueba y se han cumplido las condiciones previstas en el Código Penal y en este Código.-"},{"n":183,"r":"TRÁMITE","t":"TRÁMITE. Cuando la o el fiscal considere que corresponde dictar el sobreseimiento de una persona imputada lo fundará por escrito y la pondrá en conocimiento a la víctima —sea o no parte-, quien en el plazo de tres (3) días podrá solicitar su revisión ante una o un fiscal superior. En el plazo de tres (3) días, si la o el fiscal superior decidiera que debe revocarse el dictamen de sobreseimiento formulado, dispondrá la sustitución de la o el fiscal que intervenía en el caso y designará su sustituto para que concluya la investigación o presente acusación, según sea el caso. Cuando la o el fiscal superior confirme el dictamen de sobreseimiento, la decisión no será susceptible de recurso alguno. En estos casos, dentro del quinto día de notificada, la víctima estará habilitada para constituirse en parte si aún no era querellante y peticionar ante una jueza o juez la conversión de la acción penal pública en privada y formular la acusación de manera autónoma ante la Oficina Judicial. Vencido dicho término sin que se haya presentado acusación, la o el fiscal solicitará a la Oficina Judicial que se fije audiencia de sobreseimiento.-"},{"n":184,"r":"ACUERDO DE FISCALES","t":"ACUERDO DE FISCALES. En los casos en los que no haya víctima ni querellante y se trate de delitos de trascendencia pública, crimen organizado o hayan intervenido funcionarios públicos, la o el fiscal, previo a solicitar el sobreseimiento a la jueza o juez, deberá contar con el acuerdo de la o el fiscal superior.-"},{"n":185,"r":"AUDIENCIA ANTE EL JUEZ","t":"AUDIENCIA ANTE EL JUEZ. La o el fiscal solicitará el sobreseimiento en audiencia ante la jueza o juez y con la citación de todas las partes. Si no existiere oposición, la jueza o juez deberá resolver el sobreseimiento de la persona imputada.-"},{"n":186,"r":"","t":"CONTENIDO DEL SOBRESEIMIENTO y EFECTOS. El sobreseimiento deberá contener la identidad de la persona imputada, la enunciación de los hechos objeto de la investigación preparatoria que le fueron atribuidos, los : fundamentos fácticos y jurídicos o la imposibilidad de proceder por falta de acusación, y la parte dispositiva, con cita de las normas aplicables. Siempre que fuera posible, se analizarán las causales del sobreseimiento. La resolución hará cesar todas las medidas de coerción. El sobreseimiento firme cierra definitiva e irrevocablemente el proceso con relación a la persona imputada en cuyo favor se dicta e inhibe su nueva persecución penal por el mismo hecho. Será dictado en forma oral y su contenido quedará registrado en soporte digital.- LIBRO Ill ETAPA INTERMEDIA, / CONTROL DEL MÉRITO DE LA ACUSACIÓN. TÍTULO 1 REQUERIMIENTO DE APERTURA DEL JUICIO"},{"n":187,"r":"REQUERIMIENTO DE APERTURA A JUICIO","t":"REQUERIMIENTO DE APERTURA A JUICIO. ACUSACIÓN. Si la fiscalía estima que la investigación proporciona fundamento para someter a juicio a la persona imputada, presentará la acusación. Para ello, sin perjuicio de lo dispuesto en el Artículo 8%, procederá de esa forma, cuando todas las pruebas presentadas, tomadas en conjunto son tales que, en su concepto, justificarían un veredicto condenatorio, en caso de no ser refutadas o contradichas en la audiencia.- ES ITA PU A > 10.797 La acusación será por escrito y deberá contener: 1.- Los datos de identificación de la persona imputada y los de la abogada o abogado a cargo de su defensa. 2.- La relación precisa y circunstanciada del hecho que se le atribuye. En caso de contener varios hechos independientes, la separación y el detalle circunstanciado de cada uno de ellos. 3.- La calificación legal. 4.- La pretensión punitiva provisoria, estableciendo el quantum máximo de la pena que requerirá en el juicio, siendo ella necesaria para fijar la competencia. 5.- La petición de que se proceda de acuerdo a procedimientos de salidas alternativas si lo estima conveniente. 6.- El ofrecimiento de prueba. Se deberá presentar por separado la lista de testigos y peritos, con indicación del nombre, ocupación y domicilio. También deberá ofrecerse la documental, acompañando copia o indicando donde se encuentra para su compulsa. La acusación sólo podrá referirse a hechos y personas incluidas en la formalización de la investigación, aunque se invocare una calificación jurídica distinta de la asignada en esa oportunidad. La formulación de cargos no será obligatoria, cuando el fiscal acusare en forma directa, luego de la averiguación preliminar.-"},{"n":188,"r":"COMUNICACIÓN A LA QUERELLA","t":"COMUNICACIÓN A LA QUERELLA. La o el fiscal deberá poner el requerimiento de apertura a juicio en conocimiento del querellante. En el plazo de cinco días éstos podrán: 1.- Adherir a la acusación del fiscal; 2.- Presentar un requerimiento de apertura a juicio autónoma, en cuyo caso deberá cumplir con todos los requisitos previstos para la acusación fiscal. Recibida la presentación de éstos o transcurrido el plazo fijado, la o el fiscal remitirá a la Oficina Judicial la acusación o acusaciones, con el ofrecimiento de pruebas.- :"},{"n":189,"r":"COMUNICACIÓN A LA DEFENSA","t":"COMUNICACIÓN A LA DEFENSA. La Oficina Judicial comunicará a la defensa las acusaciones presentadas dentro de las 48 horas. En el plazo de cinco (5) días, la defensa deberá poner a disposición de la o el fiscal o del querellante, la lista de las pruebas que ofrece para la instancia de juicio oral y público, en las mismas condiciones requeridas para los acusadores. El plazo se extenderá a quince (15) días, en el supuesto de no haber dado trámite a la investigación penal preparatoria.- as TÍTULO !l INICIO ETAPA INTERMEDIA"},{"n":190,"r":"CONTROL DE LA ACUSACIÓN","t":"CONTROL DE LA ACUSACIÓN. Recibido el ofrecimiento de pruebas de la defensa o vencido el plazo, se fijará la audiencia pertinente.-"},{"n":191,"r":"AUDIENCIA","t":"AUDIENCIA. La Oficina Judicial convocará a las partes a una audiencia, dentro de los cinco (5) días, para debatir y resolver las cuestiones propias de esta etapa. Al inicio de la audiencia, la fiscalía y la querella explicarán la acusación. La defensa podrá objetar la acusación por defectos formales, solicitar que se unifiquen los hechos objeto de las acusaciones, oponer excepciones o solicitar el saneamiento o la declaración de invalidez de un acto. También podrá proponer una reparación concreta, siempre que no hubiere fracasado antes una conciliación o instar el sobreseimiento, siempre que para ello no deban discutirse cuestiones que son propias del juicio oral. Asimismo, si la persona imputada se encontrare privada de su libertad, se podrá solicitar la revisión de la medida que así lo dispuso. En la audiencia se examinarán los ofrecimientos de prueba de acuerdo a las reglas de los Artículos siguientes.-"},{"n":192,"r":"CORRECCIÓN DE VICIOS FORMALES","t":"CORRECCIÓN DE VICIOS FORMALES. Cuando la jueza o juez concluya que el requerimiento de apertura adolece de vicios formales, a pedido de parte, ordenará que sean subsanados en la misma audiencia. Si no es posible, suspenderá la misma por un plazo no mayor a cinco (5) días para que se efectúen las correcciones. El juez debe resolver fundadamente todas las cuestiones en el orden que son planteadas. -"},{"n":193,"r":"LIBERTAD PROBATORIA","t":"LIBERTAD PROBATORIA. Podrán probarse los hechos y circunstancias de interés para la solución correcta del caso, por cualquier medio de prueba, aún los no regulados en este código, en tanto no se afecten derechos ni garantías constitucionales. Las formas de admisión y producción se adecuarán al medio de prueba que resulte más acorde a los previstos en este Código.- :"},{"n":194,"r":"ADMISIBILIDAD Y CONVENCIONES PROBATORIAS","t":"ADMISIBILIDAD Y CONVENCIONES PROBATORIAS. Es admisible la prueba que se refiera al objeto de la investigación y resulte útil para el caso. Podrán limitarse los medios de prueba ofrecidos, cuando ellos resulten manifiestamente sobreabundantes. Cada parte podrá formular solicitudes y planteamientos con relación a las pruebas ofrecidas por los demás. Las partes podrán practicar convenciones probatorias y/o hechos que no serán sometidas a contradicción en el debate. La jueza o juez deberá intervenir activamente para que las partes intenten arribar a las aludidas convenciones.-"},{"n":195,"r":"DECISIÓN","t":"DECISIÓN. Oídos progresivamente cada uno de los planteos de las partes, la jueza o juez decidirá inmediatamente. La jueza o juez también examinará los ofrecimientos probatorios y planteos que con ellos se vinculen, ordenando la admisión o rechazo de las pruebas y de las convenciones probatorias. Sólo podrán ser excluidas las pruebas impertinentes desde un plano lógico ron AA ¿ES CO>á PE de A PL por ser ajenas al objeto procesal, las impertinentes por procurar generar un prejuicio en el juzgador, las sobreabundantes, las que tuvieran por objeto acreditar hechos públicos y notorios y las que provengan de actuaciones declaradas inválidas que se hubiesen obtenido con inobservancia de las garantías fundamentales. Lo resuelto será irrecurrible, sin perjuicio de poder hacer reserva de impugnación de la sentencia.-"},{"n":196,"r":"APERTURA A JUICIO","t":"APERTURA A JUICIO. Si la jueza o juez dispone la apertura a juicio, al término de la audiencia, dictará el auto de apertura a juicio oral, el que contendrá lo siguiente: 1.- El tribunal competente para intervenir en el juicio oral. 2.- La descripción de los hechos de la acusación por los que se autorizó la apertura a juicio, su calificación jurídica y la pena que estimativamente se pedirá. 3.- Los hechos que se dieron por acreditados en virtud de las convenciones probatorias. 4.- Las pruebas que se admiten para su producción en el juicio. El rechazo de pruebas se asentará en acta por separado que no será remitida al Tribunal de Juicio. 5.- La individualización de las partes y de quienes deben ser citados a juicio. 6.- La subsistencia de medidas cautelares.El auto de apertura a juicio oral será agregado al legajo de la Oficina Judicial. Los legajos de cada una de las partes, como las evidencias y documentos admitidos continuarán en poder de las partes, hasta su efectiva presentación en la recepción de pruebas en la audiencia de debate.-"},{"n":197,"r":"SUBSISTENCIA DE LAS MEDIDAS DE COERCIÓN","t":"SUBSISTENCIA DE LAS MEDIDAS DE COERCIÓN. Las prórrogas, revocaciones o sustituciones, cuando subsistan las medidas cautelares en la fase de actos preliminares al debate, en la etapa del juicio oral, deberán ser dirimidas mediante audiencia que fijará la Oficina Judicial por ante la jueza o juez de control que actuó en las etapas anteriores al juicio.- LIBRO IV JUICIO ORAL Y PÚBLICO TÍTULO | JUICIO CON JUECES PROFESIONALES CAPITULO | NORMAS GENERALES"},{"n":198,"r":"PREPARACIÓN DEL JUICIO","t":"PREPARACIÓN DEL JUICIO. Dentro de los tres (3) días de haberse ordenado la apertura a juicio, la Oficina Judicial hará el sorteo de la integración de la jueza, juez o tribunal de juicio y lo hará conocer a las partes. Las partes podrán estar presentes en el sorteo, de haberlo solicitado previamente, y se fijará día, hora y lugar donde se realizará la audiencia de juicio, que no se realizará antes de cinco (5) días ni después de sesenta (60) días. 3 O RUTA Shi ia hlla Elida ATA rain : 10.797 Las partes procederán a la citación de los testigos y peritos; bajo sanción de tenerlos por desistidos. Además, deberán concurrirán con los objetos y documentos admitidos para el juicio y organizarán el orden de presentación de su prueba. De ser necesario para la organización del debate, la Oficina Judicial dispondrá convocar a las partes a una audiencia. Las partes podrán pedir el auxilio judicial a fin de lograr el comparendo de los testigos que no se hayan presentado.-"},{"n":199,"r":"DIRECCIÓN DE LA AUDIENCIA","t":"DIRECCIÓN DE LA AUDIENCIA. La jueza o juez que presida dirigirá la audiencia, hará las advertencias legales, recibirá los juramentos y las declaraciones, moderará la discusión y los interrogatorios. También ejercerá el poder de disciplina. El tribunal en pleno resolverá cuando una decisión de quien presida sea impugnada.-"},{"n":200,"r":"INMEDIACIÓN","t":"INMEDIACIÓN. El juicio se realizará con la presencia ininterrumpida de las juezas o jueces y de todas las partes. La persona imputada no podrá alejarse de la audiencia sin permiso del tribunal y será representada por la defensora o el defensor si se reúsa a permanecer y será custodiado en una sala próxima o contigua. La persona imputada asistirá a la audiencia libre en su persona, pero el tribunal dispondrá la vigilancia y cautelas necesarias para impedir su fuga o violencias. Si se rehúsa a asistir o asistiendo altera el orden u observa una conducta inconveniente será debidamente custodiado en una sala próxima y se procederá como si estuviere presente; para todos los efectos será representado por el defensor o defensora. Cuando la o el profesional a cargo de la defensa se ausente de la audiencia se considerará abandonada la defensa y corresponderá su reemplazo. Si la o el fiscal no comparece o se aleja de la audiencia se intimará a su superior jerárquico para que provea a su reemplazo. Si en el término fijado en la intimación éste no se produce, se tendrá por abandonada la acusación. Cuando el querellante no concurra a la audiencia o se aleje de ella se tendrá por abandonada, sin perjuicio de que pueda ser obligado a comparecer como testigo.-"},{"n":201,"r":"CONTINUIDAD Y SUSPENSIÓN","t":"CONTINUIDAD Y SUSPENSIÓN. La audiencia del juicio oral se desarrollará en forma continua y podrá prolongarse en sesiones sucesivas hasta su conclusión. Constituirán, para estos efectos, sesiones sucesivas, aquellas que tuvieren lugar en el día siguiente o subsiguiente de funcionamiento ordinario del tribunal, El tribunal podrá suspender la audiencia solamente por razones de absoluta necesidad y por el tiempo mínimo necesario de acuerdo con el motivo de la suspensión. Al reanudarla efectuará un breve resumen de los actos realizados hasta ese momento. La suspensión de la audiencia o la interrupción del juicio oral por un período que excediere de diez (10) días impedirá su continuación. En tal caso, el tribunal deberá decretar la nulidad de lo obrado en él y ordenar la realización de un nuevo juicio. Cuando fuere necesario suspender la audiencia, el tribunal comunicará verbalmente la fecha y hora de su continuación, lo que se tendrá como suficiente citación. Para evitar suspensiones, el tribunal, en los juicios que se celebren en más de diez (10) jornadas, podrá requerir la presencia desde el inicio de una jueza o juez, una o un fiscal o un defensor o una defensora suplente.- ea Pam a mel Anar. MA 1 PEL PPNSIaps IES COPIA FEEL DEL OAISINAL"},{"n":202,"r":"REALIZACIÓN DEL DEBATE EN DOS FASES","t":"REALIZACIÓN DEL DEBATE EN DOS FASES. El juicio será dividido en dos partes. En la primera se tratará todo lo relativo a la existencia del hecho, su calificación y la responsabilidad penal de la persona acusada; y en la segunda, lo relativo a la individualización de la pena. Al finalizar la primera parte del juicio, el tribunal absolverá o declarará culpable a la persona acusada. Seguidamente, se procederá al ofrecimiento de pruebas a fin de fijar la pena. La admisibilidad se hará en forma inmediata y la audiencia se deberá realizar dentro de los cinco (5) días.-"},{"n":203,"r":"JUICIO SOBRE LA PENA","t":"JUICIO SOBRE LA PENA. El juicio sobre la pena comenzará con la recepción de la prueba según las normas comunes. Al finalizar el debate y la deliberación, el tribunal dictará la sentencia fijando la pena, la modalidad de cumplimiento, las condiciones de ejecución. El plazo para recurrir la sentencia comenzará a partir de este último momento.-"},{"n":204,"r":"APLICACIÓN SUPLETORIA","t":"APLICACIÓN SUPLETORIA. Las normas previstas en este Libro se aplicarán en los procedimientos especiales, en cuanto sean compatibles y a falta de reglas particulares.- CAPÍTULO Il DESARROLLO DEL JUICIO SECCIÓN PRIMERA APERTURA"},{"n":205,"r":"INICIO DE LA AUDIENCIA","t":"INICIO DE LA AUDIENCIA. Constituido el tribunal en el día y hora indicado, se declarará abierto el juicio, advirtiendo al imputado sobre la importancia y el significado de lo que va a suceder. Inmediatamente se cederá la palabra a la fiscalía, al querellante y a la defensa, en ese orden, para que presenten sus exposiciones iniciales. En el curso de la audiencia, el imputado podrá hacer las declaraciones que considere oportunas. Las partes podrán formularle preguntas o requerirle aclaraciones.-"},{"n":206,"r":"AMPLIACIÓN DE LA ACUSACIÓN","t":"AMPLIACIÓN DE LA ACUSACIÓN. Cuando durante el debate, por una revelación o retractación, se tuviera conocimiento de una circunstancia del hecho de la acusación no contenida en ella, que resulte relevante para la calificación legal, la fiscalía o el querellante podrán ampliar la acusación. En tal caso, la fiscalía o la querella harán conocer a la persona imputada las nuevas circunstancias que se le atribuyen y la jueza o juez informará a todas las partes que tendrán derecho a pedir la suspensión del juicio para ofrecer nuevas pruebas o preparar la defensa. La corrección de simples errores materiales se podrá realizar durante la audiencia sin que sea considerada una ampliación.- SECCIÓN SEGUNDA PRODUCCIÓN DE PRUEBA"},{"n":207,"r":"REGLAS","t":"REGLAS. Después de las presentaciones iniciales se recibirá la prueba ofrecida. En primer lugar, se recibirá la prueba de la fiscalía, luego la de la querella y, por último, la de la defensa. je 2LABIEA FPS Put ARufusral di ¿ES COPIA FIEL DEL ORIGINAL: La prueba que hubiese de servir de base a la sentencia deberá producirse en la audiencia de juicio, salvo excepciones expresamente previstas. Sólo podrán ser incorporadas al juicio por su lectura o exhibición las pruebas recibidas conforme a las reglas del anticipo jurisdiccional de prueba, sin perjuicio de que las partes o el tribunal exijan la reproducción cuando sea posible. Toda otra prueba que se pretenda introducir al juicio por su lectura no tendrá ningún valor, salvo acuerdo de partes o que, en la audiencia preparatoria de juicio, la jueza o juez la haya admitido de ese modo por tratarse de prueba suficientemente estandarizada. Ello, sin perjuicio de la presentación de documentos o declaraciones previas al juicio a la persona testigo, perito o a la persona imputada para facilitar su memoria, cuando incurra en contradicciones o dar explicaciones sobre lo que allí consta, previa acreditación del supuesto por el litigante y autorización de la jueza o juez. En todo caso, se valorarán los dichos vertidos en la audiencia. Si en el curso del juicio se tuviere conocimiento de nuevos medios de prueba manifiestamente útiles o se hicieren indispensables otros ya conocidos para desacreditar determinada información -prueba sobre prueba», las partes podrán solicitar la recepción de ellos.-"},{"n":208,"r":"PERITOS, TESTIGOS E INTÉRPRETES","t":"PERITOS, TESTIGOS E INTÉRPRETES. Antes de declarar, la Oficina Judicial se encargará de que las personas que asistan como testigos no se comuniquen entre sí o con otras personas, ni deberán ver, oír o ser informados de lo que ocurre en la sala de audiencia. No obstante, el incumplimiento de la incomunicación no impedirá la declaración, pero el tribunal apreciará esta circunstancia al valorar la prueba. Los peritos podrán consultar sus informes escritos o valerse de todos los elementos auxiliares útiles para explicar las operaciones periciales realizadas, pero las conclusiones deberán ser presentadas oralmente. El informe escrito no será agregado al debate como prueba. Los peritos serán interrogados bajo las reglas de los testigos.-"},{"n":209,"r":"INTERROGATORIOS","t":"INTERROGATORIOS. Los testigos y peritos, luego de prestar juramento, serán interrogados por las partes, comenzando por aquella que ofreció la prueba. No se podrá autorizar un nuevo interrogatorio después del contraexamen, salvo cuando fuere indispensable para considerar información novedosa que no hubiera sido consultada en el examen directo. En el examen directo no se admitirán preguntas sugestivas o indicativas, salvo que se autorice el tratamiento para el testigo hostil o que se trate de preguntas sugestivas introductorias, de transición, o preguntas sugestivas por la negación. En el contraexamen las partes podrán confrontar al testigo o perito con sus propios dichos o con otras versiones, a través de preguntas sugestivas de un sólo punto. En ningún caso, se admitirán preguntas engañosas, repetitivas, ambiguas o destinadas a coaccionar ¡legítimamente al testigo o perito. Las juezas o jueces no podrán formular preguntas.-"},{"n":210,"r":"OBJECIONES","t":"OBJECIONES. Las partes podrán objetar las preguntas inadmisibles indicando el motivo. El tribunal hará lugar de inmediato al planteo si fuere manifiesto el exceso o decidir luego de permitir la réplica de la contraparte. El tribunal procurará que no se utilicen las objeciones para alterar la continuidad de los interrogatorios.-"},{"n":211,"r":"LECTURA DE DECLARACIONES PREVIAS","t":"LECTURA DE DECLARACIONES PREVIAS. Cuando sea necesario para demostrar o superar contradicciones o fuere indispensable para ayudar a la memoria de la persona testigo o perito, se podrá leer parte de las declaraciones previas prestadas antes del juicio. En esos casos, sólo se permitirá que el testigo efectúe la lectura de la declaración a viva voz cuando se trate de evidenciar una inconsistencia. Para el presente, se considerará declaración previa del testigo, cualquier manifestación dada con anterioridad al juicio, ya sea en un organismo oficial o en cualquier sede.-"},{"n":212,"r":"DOCUMENTACIÓN Y OBJETOS","t":"DOCUMENTACIÓN Y OBJETOS. Los objetos y evidencias introducidas en el juicio, a través de los testigos y peritos, serán exhibidos a aquellos para su reconocimiento. Sólo podrán incorporarse al juicio aquellos objetos que fueran exhibidos. Las grabaciones y elementos de prueba audiovisuales serán reproducidas.- SECCIÓN TERCERA REGLAS ESPECIALES SOBRE LOS TESTIMONIOS"},{"n":213,"r":"CAPACIDAD DE ATESTIGUAR","t":"CAPACIDAD DE ATESTIGUAR. Toda persona será capaz de atestiguar, sin perjuicio de la facultad del tribunal para valorar su testimonio.-"},{"n":214,"r":"DEBER DE TESTIFICAR","t":"DEBER DE TESTIFICAR. Salvo las excepciones establecidas por la Ley, toda persona tendrá la obligación de concurrir al llamamiento judicial y declarar la verdad de cuanto conozca y le sea preguntado. Asimismo, no podrá ocultar hechos, circunstancias o elementos relacionados con la investigación. La persona testigo no tendrá la obligación de declarar sobre hechos que le puedan significar responsabilidad penal.-"},{"n":215,"r":"DEBER Y FACULTAD DE ABSTENCIÓN","t":"DEBER Y FACULTAD DE ABSTENCIÓN. Deberán abstenerse de declarar quienes según la ley deban guardar secreto. Podrán abstenerse de declarar el cónyuge o conviviente de la persona imputada, ligado por especiales vínculos de afectos, los parientes hasta el cuarto grado de consanguinidad y segundo de afinidad. Las personas mencionadas serán informadas sobre su facultad de abstenerse antes de iniciar la declaración. Ellas podrán ejercerla aun durante su declaración, incluso en el momento de responder determinadas preguntas. Si la jueza o juez o tribunal estima que el testigo invoca erróneamente la facultad de abstenerse ordenará, ha pedido de parte, su declaración mediante resolución fundada.-"},{"n":216,"r":"COMPULSIÓN","t":"COMPULSIÓN. Si la persona testigo no se presenta a la primera convocatoria sin motivo atendible podrá hacérselo comparecer por medio de la fuerza pública. Si después de comparecer se niega a declarar sin derecho a hacerlo, se dispondrá su arresto hasta 24 horas, salvo que desista de su negativa y de no hacerlo, se dará intervención al fiscal.- SECCIÓN CUARTA DISCUSIÓN FINAL Y CLAUSURA DEL DEBATE"},{"n":217,"r":"ALEGATOS","t":"ALEGATOS. Terminada la recepción de las pruebas, quien preside concederá sucesivamente la palabra a la fiscalía, al querellante y a la defensa para que | en ese orden expresen sus alegatos finales. a a ua No se podrán leer memoriales sin perjuicio de la lectura parcial de notas. Si intervinieron más de una o un fiscal, querellante o defensora o defensor todos podrán hablar repartiendo sus tareas para evitar repeticiones o dilaciones. Todas las partes podrán replicar, pero corresponderá a la defensa la última palabra. La réplica deberá limitarse a la refutación de los argumentos adversos que antes no hubieren sido discutidos. Al finalizar sus alegatos, las partes oradoras expresarán sus peticiones de un modo concreto. Finalmente, se preguntará a la persona imputada si tiene algo más que manifestar y se declarará cerrado el debate. Durante la recepción de la prueba, la fiscalía podrá solicitar la absolución y, en cuyo caso, no se continuará con el curso del debate y se dictará sentencia absolutoria inmediata.-"},{"n":218,"r":"","t":"DELIBERACIÓN y SENTENCIA. Las juezas o jueces pasarán de inmediato y sin interrupción a deliberar en sesión secreta. La deliberación no podrá extenderse más de 24 horas ni podrá suspenderse, salvo enfermedad grave de algunas de las juezas o jueces. En este caso, la suspensión no podrá durar más de tres (3) días, luego de los cuales se deberá realizar el juicio nuevamente. Mientras dure la deliberación, las juezas o jueces no podrán intervenir en otro juicio. Se deliberará y votará individualmente respecto de todas las cuestiones apreciando las pruebas de un modo integral, según las reglas de la sana crítica. Las decisiones se adoptarán por mayoría. En caso de disidencia, el voto dirimente deberá ser fundado. -"},{"n":219,"r":"REQUISITOS DE LA SENTENCIA","t":"REQUISITOS DE LA SENTENCIA. La sentencia contendrá: 1.- La composición del órgano jurisdiccional, el lugar y la fecha en que se ha dictado, el nombre de las juezas o los jueces y las partes, los datos personales de la persona imputada y la enunciación del hecho que ha sido objeto de acusación. 2.- El voto de las juezas o jueces sobre cada una de las cuestiones planteadas con la explicación de la valoración hecha, individualmente, de cada uno de los elementos de prueba o datos producidos y la forma en que, conjuntamente, éstos sostienen la base fáctica de la decisión. 3.- La determinación precisa y circunstanciada del hecho que se estima acreditado. 4.- La calificación jurídica. 5.- La parte dispositiva con mención de las normas aplicables. 6.- La firma de las juezas o jueces.-"},{"n":220,"r":"","t":"REDACCIÓN y LECTURA. La sentencia será redactada y firmada inmediatamente después de la deliberación. El tribunal se constituirá nuevamente en la sala de audiencia, después de convocar verbalmente a las partes y al público. El documento será leído en voz alta ante quienes comparezcan. Cuando por la complejidad del asunto sea necesario diferir la redacción de la sentencia se leerá tan sólo su parte dispositiva y una de las juezas o jueces relatará al público, sintéticamente, todos los fundamentos que motivaron la decisión. Asimismo, anunciará día y hora de la audiencia para la lectura integral, la que se llevará a cabo en el plazo máximo de los cinco (5) días posteriores al pronunciamiento de la parte dispositiva. La sentencia quedará notificada con la lectura integral.-"},{"n":221,"r":"SENTENCIA","t":"SENTENCIA. La sentencia sólo podrá dar por acreditados hechos o circunstancias contenidos en la acusación. La sentencia tampoco podrá dar al hecho una calificación jurídica distinta a la de la acusación, salvo que sea en beneficio de la persona imputada. La sentencia condenatoria fijará con precisión las penas que correspondan, no pudiendo el tribunal aplicar penas más graves que las requeridas por los acusadores. También resolverá sobre la entrega o decomiso de los objetos secuestrados y sobre la imposición de las costas del juicio. La sentencia absolutoria ordenará la libertad de la persona imputada, la cesación de todas las medidas cautelares, la restitución de los objetos afectados al procedimiento que no estén sujetos a comiso y las inscripciones necesarias. Será comunicada a la jueza o juez de ejecución cuando correspondiere.- TÍTULO II PROCEDIMIENTOS ESPECIALES CAPÍTULO | ) PROCEDIMIENTO POR DELITOS DE ACCIÓN PRIVADA"},{"n":222,"r":"FORMA Y CONTENIDO DE LA QUERELLA","t":"FORMA Y CONTENIDO DE LA QUERELLA. La querella será presentada por escrito personalmente o por mandatario con poder especial, siempre con patrocinio de abogado matriculado y deberá expresar bajo pena de inadmisibilidad: 1.- Datos de identidad, domicilio y firma de la persona querellante y, en su caso, también de la mandataria o mandatario. 2.- Datos de identidad y el domicilio de la persona querellada o, si se ignora, cualquier descripción que sirva para identificarlo. 3.- Una relación clara, precisa y circunstanciada del hecho, con indicación del lugar y el momento en que se ejecutó. 4.- Calificación legal de los hechos. También indicará las pruebas que se ofrezcan, señalando en su caso los datos que permitan llevar adelante su producción. Si se trata de testigos o peritos, además de los datos personales y domicilio se deberán indicar los hechos sobre los que deberán ser examinados o requeridos. La presentación deberá acompañarse con una copia del escrito para cada persona querellada.-"},{"n":223,"r":"DESESTIMACIÓN","t":"DESESTIMACIÓN. La querella será desestimada por autofundado cuando sea manifiesto que el hecho imputado no constituye delito o cuando no se pueda proceder o faltare alguno de los requisitos para constituirse como parte querellante. El escrito y demás elementos acompañados serán devueltos a la parte querellante, quien podrá reiterar su petición, corrigiendo sus defectos si fuere posible, con mención de la desestimación anterior dispuesta.-"},{"n":224,"r":"AUXILIO JUDICIAL PREVIO","t":"AUXILIO JUDICIAL PREVIO. Cuando no se haya logrado identificar o individualizar a la persona acusada o determinar su domicilio o cuando para describir clara, precisa y circunstanciadamente el delito sea imprescindible llevar a cabo diligencias que el querellante no pueda realizar por sí mismo, requerirá el auxilio judicial indicando las medidas pertinentes. La jueza o juez prestará el auxilio si corresponde. La parte querellante presentará su acusación dentro de los cinco (5) días de obtenida la información faltante. En caso de no hacerlo será condenado en costas y se procederá al archivo de las actuaciones.-"},{"n":225,"r":"AUDIENCIA DE CONCILIACIÓN","t":"AUDIENCIA DE CONCILIACIÓN. Admitida la querella, a pedido de parte, la Oficina Judicial convocará a una audiencia de conciliación dentro de los diez (10) días. Por acuerdo entre las personas acusadora y acusada podrán designar un amigable componedor para que realice la audiencia. La jueza o juez podrá designar un mediador habilitado.-"},{"n":226,"r":"OFRECIMIENTO DE PRUEBA Y JUICIO","t":"OFRECIMIENTO DE PRUEBA Y JUICIO. Si no se logra la conciliación, a pedido de parte, convocará a una audiencia preliminar para que la persona querellada ofrezca pruebas y para decidir sobre la admisión o rechazo de la que ofrezcan ambas partes. Con posterioridad, en audiencia, previo oír a las partes, la jueza o juez dictará el auto de apertura a juicio y dispondrá que la Oficina Judicial sortee la jueza o juez con funciones de juicio que intervendrá, en el que se observarán las reglas del procedimiento común en cuanto sea posible. Quien ha ofrecido prueba tomará a su cargo la presentación en el juicio. En caso necesario se podrá requerir auxilio judicial.- CAPÍTULO Il PROCEDIMIENTOS ABREVIADOS SECCIÓN PRIMERA ACUERDO PLENO"},{"n":227,"r":"ADMISIBILIDAD","t":"ADMISIBILIDAD. Durante la etapa preparatoria, con Tribunal Unipersonal, se podrá aplicar el procedimiento abreviado cuando: 1.- La persona imputada admita el hecho que se le atribuye y consienta la aplicación de este procedimiento, con previa asistencia de su defensor a tales efectos. 2.- La fiscalía manifieste su conformidad. 3.- En»caso de acción privada, o procesos con conversión de acción privada, la parte querellante manifieste su conformidad. a a ia zo ora EL CEL ORIGINAL | 4.- La pena acordada no supere los doce años de privación de libertad o se trate de otra especie de pena. La existencia de personas coimputadas no impide la aplicación de estas reglas a alguno de ellos.-"},{"n":228,"r":"PROCEDIMIENTO Y RESOLUCIÓN","t":"PROCEDIMIENTO Y RESOLUCIÓN. Las partes solicitarán la aplicación de los hechos por parte de la persona acusada del procedimiento abreviado, Si se sustancia por requerimiento de la fiscalía, ante la confesión de la persona imputada, la fiscalía no podrá retractarse sin fundar su pretensión. En audiencia fundarán sus pretensiones en base a la confesión del imputado y las evidencias recolectadas en la investigación penal preparatoria y la jueza o juez, aceptado el acuerdo de partes, absolverá o condenará. Si condena, la pena que imponga no podrá superar la acordada por las partes ni modificar su forma de ejecución y la sentencia no podrá fundarse exclusivamente en la aceptación.-"},{"n":229,"r":"INADMISIBILIDAD","t":"INADMISIBILIDAD. Cuando la jueza o juez estime que el acuerdo no cumple con los requisitos legales, la fiscalía deberá continuar el procedimiento según el trámite ordinario. En este caso, el requerimiento anterior sobre la pena no vincula a la fiscalía durante el juicio, ni la admisión de los hechos por parte de la persona imputada, podrán ser considerados como reconocimiento de culpabilidad.-"},{"n":230,"r":"UNIFICACIÓN DE PENAS","t":"UNIFICACIÓN DE PENAS. El acuerdo puede comprender la unificación de pena con una condena anterior. En este caso no se tendrá en cuenta el límite previsto. El tribunal no podrá disponer ninguna consecuencia más gravosa que la acordada por las partes.- SECCIÓN SEGUNDA ACUERDO PARCIAL"},{"n":231,"r":"ADMISIBILIDAD","t":"ADMISIBILIDAD. Durante la etapa preparatoria las partes podrán acordar exclusivamente sobre los hechos y solicitar un juicio sobre la culpabilidad y la pena. Esta petición se hará ante la jueza o juez de garantías y contendrá la descripción del hecho acordado y el ofrecimiento de prueba para su determinación. La jueza o juez comprobará en audiencia el cumplimiento de los requisitos formales, permitirá el debate sobre la calificación y aceptará o rechazará el ofrecimiento de la prueba relacionada con la pena. El tribunal absolverá o declarará culpable a la persona imputada y, en su caso, se pronunciará sobre la prueba ofrecida, fijando audiencia de determinación de la pena.- SECCIÓN TERCERA ACUERDO PARA LA REALIZACIÓN DIRECTA DEL JUICIO"},{"n":232,"r":"ACUERDO","t":"ACUERDO. En la audiencia de formulación de cargos, las partes podrán acordar la realización directa del juicio. La solicitud contendrá la descripción del hecho por el que acusa, el ofrecimiento de prueba de las partes o las convenciones probatorias y fácticas y la pretensión punitiva provisional cuando fuere necesario para fijar la integración del tribunal. La acusación se fundamentará directamente en el juicio. En lo demás se aplicarán las normas comunes.- ES COMA MEL DEL OIL Phal SSL lr cdo - AAA RI AAA AAA AAA e 1 0 ” 7 9 7 ] CAPÍTULO Ill PROCEDIMIENTO PARA ASUNTOS COMPLEJOS"},{"n":233,"r":"PROCEDENCIA","t":"PROCEDENCIA. Cuando la investigación sea compleja a causa de la pluralidad de hechos, del elevado número de personas imputadas o víctimas o por tratarse de casos de delincuencia organizada, a solicitud de la fiscalía o la querella, la jueza o juez podrá autorizar la aplicación de las normas especiales previstas en este Título. La autorización podrá ser revocada a petición de quien considere afectados sus derechos por el procedimiento.-"},{"n":234,"r":"PLAZOS","t":"PLAZOS. Una vez autorizado este procedimiento, producirá los siguientes efectos: 1.- El plazo ordinario de la prisión preventiva se extenderá hasta un máximo de tres (3) años y la duración del proceso será de cuatro (4) años improrrogables. 2.- El plazo acordado para concluir con la averiguación preliminar será de ciento veinte (120) días, sin perjuicio de la facultad de requerir prórrogas. 3.- El plazo acordado para concluir la investigación preparatoria será de un (1) año y las prórrogas de un (1) año más cada una. 4.- Los plazos establecidos a favor de las partes para realizar alguna actuación y aquellos que establecen un determinado tiempo para celebrar las audiencias, se duplicarán. 5.- Cuando la duración del debate sea menor de treinta (30) días, el plazo máximo de la deliberación se extenderá a cinco (5) días, y el de dictar sentencia a diez (10) días. Cuando la duración del debate sea mayor, esos plazos serán de diez (10) y veinte (20) días, respectivamente. 6.- Los plazos de impugnación se duplicarán. 7.- El plazo autorizado para la reserva parcial de actuaciones se extenderá a veinte (20) días. 8.- El plazo para la intervención, grabación o registro de comunicaciones se duplicará.-"},{"n":235,"r":"INVESTIGADORES BAJO RESERVA","t":"INVESTIGADORES BAJO RESERVA. La o el fiscal podrá solicitar a la jueza o juez que se autorice la reserva de identidad de una o varias personas investigadoras de la fiscalía cuando ello sea manifiestamente útil para el desarrollo de la investigación. La jueza o juez fijará el plazo de la reserva de identidad de las personas que sólo será prorrogado si se renuevan los fundamentos de la petición. En ningún caso podrá superar los seis (6) meses. Concluido el plazo, la fiscalía presentará a la jueza o juez un informe del resultado de las investigaciones, revelando la identidad de las personas investigadoras, las que podrán ser citadas como testigos en el juicio. La fiscalía será responsable directa de la actuación de estos investigadores.- lea Area Sl ml RT raas ¡ED LUMIA Pol CL UTA! - 10.797 LA RIOJA :"},{"n":236,"r":"REGLAS COMUNES","t":"REGLAS COMUNES. En todo lo demás, regirán las reglas del procedimiento común. Las juezas o jueces deberán velar para que la aplicación de las normas reguladas en este Título no desnaturalice los derechos y garantías previstos en la Constitución Nacional, en los instrumentos internacionales de derechos humanos, en la Constitución Provincial y en este Código.- CAPÍTULO IV ) PROCESOS CONTRA PERSONAS JURÍDICAS"},{"n":237,"r":"REGLAS DEL PROCESO","t":"REGLAS DEL PROCESO. El proceso contra las personas jurídicas se regirá por las disposiciones de este Título y las demás reglas del proceso común, en la forma que le sean aplicables. Las personas jurídicas tendrán los derechos y las obligaciones previstos para el imputado en este Código, en todo cuanto les sean aplicables. El Ministerio Público podrá ejercer la acción penal en contra de las personas jurídicas, con excepción de las instituciones estatales, independientemente de la acción penal que pudiera ejercer contra las personas físicas involucradas en el delito cometido.-"},{"n":238,"r":"REPRESENTACIÓN Y DEFENSA","t":"REPRESENTACIÓN Y DEFENSA. La persona jurídica será representada por su representante legal o por cualquier persona con poder especial para el caso, otorgado con las formalidades que correspondan al tipo de entidad de que se trate, debiendo designar en cualquier caso abogado defensor. El representante deberá informar el domicilio de la entidad y constituir domicilio procesal en la primera presentación. A partir de entonces, las notificaciones a la persona jurídica se cursarán a ese domicilio procesal. En cualquier momento del proceso, la persona jurídica podrá sustituir a su representante. Si la sustitución tuviere lugar una vez iniciada la audiencia de juicio, deberá ser motivada, y no podrá interrumpir el proceso por más de tres (3) días. La sustitución no perjudicará la eficacia de los actos cumplidos por su anterior representante. En caso de no designar representante o si habiéndolo designado éste no compareciere al proceso, la persona jurídica será declarada rebelde. Si no designare defensor, se le proveerá el defensor público que por turno corresponda. La designación, facultades, número e intervención de los defensores que la asistan se regirán por las disposiciones de este Código.-"},{"n":239,"r":"CONFLICTO DE INTERESES Y ABANDONO DE LA REPRESENTACIÓN","t":"CONFLICTO DE INTERESES Y ABANDONO DE LA REPRESENTACIÓN. Si se detectare la existencia de un conflicto de intereses entre la persona jurídica y la persona designada como representante, o si en el curso de la investigación se produjere el abandono de la función por el representante, la o el fiscal o la jueza o juez intimarán a aquella para que lo sustituya en el plazo de cinco (5) días. Si no lo sustituyere, será declarada rebelde.-"},{"n":240,"r":"CITACIÓN Y COMUNICACIONES","t":"CITACIÓN Y COMUNICACIONES. Cuando la persona jurídica no se hubiera presentado al proceso, las comunicaciones se le cursarán al domicilio legal, que tendrá carácter de domicilio constituido. Sin perjuicio de ello, se le podrán cursar comunicaciones a cualquier otro domicilio que se conozca, según lo establecido en el Artículo 93% de este Código. a a e adas - A NE FUNCION LEGISLATIVA : Cuando no hubiera sido posible citarla o si la persona jurídica no se presentara, la o el fiscal la citará mediante edictos publicados por tres (3) días en el Boletín Oficial y dos (2) días en un diario de circulación nacional. Los edictos identificarán la causa en la que se la cita, la fiscalía y el juez que intervienen en el caso, el plazo de citación y la advertencia de que, en caso de no presentarse, se la declarará rebelde y se continuará el trámite hasta la acusación.- ARTÍCULO 241\".. REBELDÍA. En caso de incomparecencia injustificada a la citación o de omitir designar representante habiendo sido intimada a hacerlo, la persona jurídica será declarada rebelde por la jueza o juez, a requerimiento de la fiscalía, en la forma y con los alcances establecidos en el Artículo 50% de este Código. La jueza o juez que disponga la rebeldía deberá informar dicha resolución a la Inspección General de Justicia y a la Administración Federal de Ingresos Públicos para que suspendan de manera preventiva la personería jurídica y la Clave Única de Identificación Tributaria de la rebelde, respectivamente. También deberá comunicarla al Registro Nacional de Reincidencia, a sus efectos. Además, deberá disponer de inmediato todas las medidas cautelares necesarias para asegurar la oportuna continuación y finalidad del proceso, de conformidad con el último párrafo del Artículo 23% del Código Penal.-"},{"n":241,"r":"REBELDÍA","t":"REBELDÍA. En caso de incomparecencia injustificada a la citación o de omitir designar representante habiendo sido intimada a hacerlo, la persona jurídica será declarada rebelde por la jueza o juez, a requerimiento de la fiscalía, en la forma y con los alcances establecidos en el"},{"n":242,"r":"LEGITIMACIÓN PARA CELEBRAR ACUERDOS","t":"LEGITIMACIÓN PARA CELEBRAR ACUERDOS. ACEPTACIÓN. La persona jurídica podrá realizar acuerdos de colaboración, conciliación, de suspensión del proceso a prueba y de juicio abreviado, pleno o parcial, en las condiciones establecidas por este Código y las demás leyes, en cuanto les sean aplicables. En todo tipo de acuerdo, el representante de la persona jurídica deberá garantizar que haya sido aceptado por el órgano directivo de su representada.- CAPÍTULO Y PROCEDIMIENTO ESPECIAL PARA NIÑAS, NIÑOS Y ADOLESCENTES"},{"n":243,"r":"DERECHOS Y GARANTÍAS","t":"DERECHOS Y GARANTÍAS. La niña, niño o adolescente gozará de todos los derechos y garantías previstos por la Constitución Nacional, los Tratados Internacionales con jerarquía constitucional, la Constitución Provincial, este Código y normas especiales.-"},{"n":244,"r":"ÁMBITO DE APLICACIÓN","t":"ÁMBITO DE APLICACIÓN. Cuando se le atribuya a una persona menor de dieciocho (18) años de edad participación en un acto u omisión que, al momento de ocurrir, estuviere definido por la Ley Penal como delito, serán de aplicación las disposiciones de este Título, sin perjuicio de las normas legales pertinentes.-"},{"n":245,"r":"FINALIDAD","t":"FINALIDAD. En el supuesto previsto en el Artículo 238% se procurará que la niña, niño o adolescente sea tratado de manera acorde a su edad, acreciente su sentido de la propia dignidad y valor, fortalezca su respeto por los derechos humanos y las libertades fundamentales de terceros, promueva su reintegración y asuma una función constructiva en la sociedad. El logro de estos fines se buscará mediante la participación activa de la niña, niño o adolescente en la sustanciación del proceso y, en su caso, en la ejecución de las medidas que se dispongan a su respecto. : Se priorizará el fortalecimiento de los vínculos familiares y comunitarios.- a (ES ONDA E CAS ¡ES E - 10.797"},{"n":246,"r":"COMPROBACIÓN DE LOS HECHOS","t":"COMPROBACIÓN DE LOS HECHOS. En todos los casos se procurará establecer la existencia del hecho delictivo atribuido y la participación de la niña, niño o adolescente en el mismo. Sin la probable concurrencia de ambos extremos no podrá ordenarse ninguna medida procesal que afecte sus derechos. La imposición de cualquiera de las medidas socioeducativas previstas en este Código requerirá la plena convicción judicial, motivada en pruebas legítimas, sobre aquellos extremos fácticos, siempre que no concurra alguna de las hipótesis del Artículo 34% del Código Penal. En ningún supuesto se aplicarán medidas de protección en el sistema penal. En caso de archivo, sobreseimiento o absolución, si se hubiera verificado alguna otra situación que requiera la intervención estatal en protección de la niña, niño o adolescente, se remitirán los antecedentes a la Autoridad de Aplicación local del sistema de protección integral de niñas, niños y adolescentes. Aun cuando se acredite la probable existencia del hecho y la participación de la niña, niño o adolescente, en el supuesto de detectarse paralelamente alguna situación de vulneración de derechos, el juez competente, a petición de parte o aún de oficio, deberá proceder como lo dispone el párrafo anterior.-"},{"n":247,"r":"ARCHIVO","t":"ARCHIVO. En cualquier momento del proceso, la jueza o juez competente podrá, a petición del o la fiscal o la defensa, archivar la causa. A tal fin, deberá considerar especialmente su edad, la menor gravedad de las consecuencias del delito atribuido, la personalidad y contexto familiar y social de aquel, la forma y grado de su participación y el favorable pronóstico sobre el logro de los objetivos del"},{"n":248,"r":"MEDIACIÓN","t":"MEDIACIÓN. La jueza o juez podrá autorizar que, por medio del Ministerio Público Pupilar, procure un acercamiento entre la niña, niño o adolescente y quien aparezca como víctima del delito que se le atribuye. Si esta mediación diera como resultado una composición del conflicto entre ambos, podrá también disponerse el archivo de la causa. En los supuestos procedentes se dispondrá el sobreseimiento.-"},{"n":249,"r":"MEDIDAS PROCESALES DE DISPOSICIÓN PROVISORIA","t":"MEDIDAS PROCESALES DE DISPOSICIÓN PROVISORIA. Durante el proceso y previa verificación de los extremos exigidos por el Artículo 240\", la jueza o juez, a pedido del o la fiscal y con resguardo del derecho de defensa y el debido proceso, podrá ordenar provisoriamente medidas de coerción personal que podrán consistir en: 1.- La obligación de concurrir periódicamente ante la Oficina de Gestión Judicial (OGA) o autoridad que se disponga, acompañado por sus padres, tutor o guardador. 2.- La abstención de frecuentar determinados lugares y personas. 3.- La abstención de ingesta de alcohol u otras sustancias tóxicas. 4.- La disposición provisoria del menor en su domicilio bajo supervisión. 5.- La disposición provisoria del menor durante el fin de semana. 6.- La disposición provisoria del menor durante el proceso en un establecimiento para niñas, niños o adolescentes. ... Basa 231 pa prisas: Ñ o 1 0 . 7 9 7 En todos los casos, la jueza o juez fijará la duración máxima de las medidas precedentes. En los casos de los Incisos 4), 5) y 6), la medida no deberá exceder de seis (6) meses, pero podrá ser prorrogada a su vencimiento por un término similar.-"},{"n":250,"r":"CONTROL DE LAS MEDIDAS POR JUEZA O JUEZ","t":"CONTROL DE LAS MEDIDAS POR JUEZA O JUEZ. Cada seis (6) meses, sin perjuicio de aquellas oportunidades en que la Ley lo dispone expresamente, la jueza o juez que ordenó las medidas controlará los presupuestos de su cumplimiento y, conforme al caso, ordenará su continuación, su sustitución por otra medida o la finalización de las mismas. El examen se producirá en audiencia oral, a la cual serán citados todos los intervinientes, con aquellos que concurran, y después de la audiencia el tribunal decidirá inmediatamente. El tribunal podrá, por un lapso breve, interrumpir la audiencia o la decisión, con el fin de practicar una averiguación sumaria.-"},{"n":251,"r":"REGLAS PARA EL JUICIO","t":"REGLAS PARA EL JUICIO. Cuando el acusado sea una niña, niño o adolescente menor de dieciocho (18) años, el debate tramitará conforme a las siguientes reglas generales y especiales: 4.- El debate será público o a puertas cerradas, conforme a la voluntad de la persona acusada menor de edad, que procurará la jueza o juez que presida la audiencia preliminar y hará constar en la decisión de apertura del debate. La regla rige incluso para los casos en los cuales el adolescente sea enjuiciado en conjunto con otras personas acusadas mayores de aquella edad, siempre que el tribuna! no decida la separación de los debates. 2.- Los representantes legales o el guardador de la niña, niño o adolescente podrán designarle defensor cuando él no haga uso de su derecho a designarlo. 3.- La sentencia sobre la niña, niño o adolescente se limitará, en todos los casos, al veredicto de culpabilidad o inocencia, sin fijar la pena aplicable. El debate sobre la pena será realizado posteriormente, conforme al Artículo 196%, y su imposición estará supeditada a lo dispuesto en el Régimen Penal de la Minoridad, Ley Nacional N* 22,278 y sus modificatorias. 4.- Lao el fiscal, cuando postule que la persona adolescente sea declarada autora responsable de delito, deberá también manifestar si considera procedente la imposición de una medida socioeducativa, informando en este caso al tribunal sobre el plan de cumplimiento que hubiere acordado previamente con el organismo administrativo encargado de su ejecución. La procedencia de la medida solamente podrá ser fundada en alguno de los supuestos previstos en el Régimen Penal de la Minoridad, Ley Nacional N* 22.278 y sus reformas. De esta postulación se dará traslado a la defensa técnica y a la Defensoría de Menores en el mismo acto. El tribunal resolverá fundadamente de inmediato. ¡ES COPIA FEEL DE. ORIGINAL: AAA A A A - 10.797 5.- Enel debate sobre la pena se escuchará, después de los informes finales, a la madre, al padre, al tutor y al guardador que estuvieren presentes en la audiencia o en el tribunal y que, invitados a tomar la palabra, quisieren hacerlo, sin perjuicio de conceder la última palabra al adolescente, según las reglas comunes. Nunca se impondrá pena si esta decisión no es precedida de una acción tendiente a ofrecer una posibilidad razonable de que la persona adolescente supere las circunstancias que originaron el proceso criminal seguido en su contra.-"},{"n":252,"r":"JUICIO ABREVIADO","t":"JUICIO ABREVIADO. Podrá aplicarse el procedimiento previsto en los Artículos 221% al 226% y concordantes, si se hubiera acordado la realización del juicio abreviado con aceptación de responsabilidad por la persona adolescente y, eventualmente, la imposición de una medida socioeducativa. Sin perjuicio de lo acordado, el tribunal podrá aplicar lo previsto en el Artículo 4% del Régimen Penal de la Minoridad, Ley Nacional N* 22.278 y reformas, según corresponda. En el acuerdo de juicio abreviado se podrá prever la absolución por considerar innecesaria la aplicación de pena y, si se acordare pena, en ningún caso podrá ser el máximo de la escala penal, ni pena perpetua, aún para los delitos que la tuvieran legalmente prevista.-"},{"n":253,"r":"MEDIDAS SOCIOEDUCATIVAS","t":"MEDIDAS SOCIOEDUCATIVAS. Siempre que concurran las exigencias del Párrafo Tercero del Artículo 240%, en la sentencia por la que se declare la autoría responsable se podrá ordenar, teniendo en cuenta la capacidad de la persona ' adolescente para cumplirla, el mejor logro de los objetivos del Artículo 239% y la naturaleza, circunstancias y consecuencias del hecho, la aplicación de las siguientes medidas: 1.- Amonestación severa para evitar que se repita el mal comportamiento, en presencia de sus padres, tutor o guardador y el defensor. 2.- Disculpas presentadas a la víctima o a sus representantes. 3.- Adopción de oficio o profesión. 4.- Realizar el trabajo que se le ordene, a favor de la víctima o de sus representantes, de acuerdo a la edad, desarrollo físico y capacidad del adolescente. 5.- Realizar el trabajo que se le ordene a través de la prestación de servicios a la comunidad de acuerdo a su edad, desarrollo físico y capacidad.-"},{"n":254,"r":"REDUCCIÓN Y SUSTITUCIÓN","t":"REDUCCIÓN Y SUSTITUCIÓN. En caso de que durante la ejecución de las medidas previstas en este Título se advirtiera una razonable consecución de los fines previstos en el Artículo 239%, a instancia de parte podrán reducirse en su duración, o sustituirse por otras de las previstas que sean menos gravosas.-"},{"n":255,"r":"RECURSOS","t":"RECURSOS. La declaración de autoría responsable, la imposición de una medida socioeducativa y la imposición de pena serán recurribles conforme a lo que se legisla en el Artículo 269” y siguientes.- 20 PACA EL EL ADA [ES GUA MEL YES ORIGINAL: CAPÍTULO VI PROCEDIMIENTO PARA LA APLICACIÓN DE MEDIDAS DE SEGURIDAD"},{"n":256,"r":"PROCEDENCIA","t":"PROCEDENCIA. Cuando la o el fiscal o las demás partes estimen que sólo corresponde adoptar una medida de seguridad, lo solicitarán a la jueza o juez indicando los antecedentes y circunstancias que motiven el pedido. La presentación de la fiscalía deberá reunir, en lo demás, los requisitos de la acusación, debiendo precisar el hecho atribuido y mencionar la prueba de cargo. La resolución atenderá todos los puntos de la acusación, ordenará cuando corresponda la medida de seguridad o dispondrá la remisión de antecedentes a la justicia civil. Si la jueza o juez considera que es imputable ordenará la aplicación del procedimiento ordinario.- CAPÍTULO VII HABEAS CORPUS"},{"n":257,"r":"PROCEDENCIA","t":"PROCEDENCIA. La acción de hábeas corpus procede contra todo acto u omisión de autoridad pública, de un particular o grupo de éstos que directa o indirectamente, de modo actual o inminente, en forma ¡legal o arbitraria, lesione, restrinja, altere o amenace la libertad física de las personas. Igualmente es procedente en caso de agravamiento arbitrario de las condiciones de detención legal o en el de desaparición forzada de personas.- :"},{"n":258,"r":"FACULTAD DE DENUNCIAR","t":"FACULTAD DE DENUNCIAR. La petición de hábeas corpus puede ser interpuesta por el afectado o por terceros en su favor, sin necesidad de mandato.-"},{"n":259,"r":"COMPETENCIA","t":"COMPETENCIA. Es competente para conocer en el procedimiento de hábeas corpus el Juez de Control de Garantías que, por razones de competencia territorial y de turno, corresponde al lugar de acaecimiento del hecho que lo motiva. : Si el juez se considera incompetente así lo debe declarar y, en este caso, remitir de inmediato lo actuado al juez que estime competente. En caso de conflicto de competencia, el Tribunal Superior de Justicia lo debe resolver dentro del término de 24 horas de recibidos los autos, remitiendo los mismos al juez que determine. El juez de hábeas corpus ejerce su potestad jurisdiccional por sobre todo otro poder o autoridad pública.-"},{"n":260,"r":"RECUSACIÓN Y EXCUSACIÓN","t":"RECUSACIÓN Y EXCUSACIÓN. En el procedimiento de hábeas corpus no se admite recusación alguna. El juez o tribunal que se considere comprendido en alguna de las causales de excusación previstas en este Código así lo debe declarar, debiendo procederse conforme a lo que establece la normativa de aplicación.-"},{"n":261,"r":"REQUISITOS DE LA DENUNCIA","t":"REQUISITOS DE LA DENUNCIA. La denuncia de hábeas corpus no requiere formalidad procesal alguna. Sin perjuicio de ello, quien la ejerza debe proporcionar en lo posible: 4.- Nombre y domicilio real del denunciante. 2.- Nombre, domicilio real y demás datos personales conocidos de la persona en cuyo favor se denuncia. [ES COPIA REL DEL CRIGIRAL A A : 10.797 3.- Autoridad o particular de quien emana el acto denunciado como lesivo, 4.- Causa o pretexto del acto denunciado como lesivo en la medida del conocimiento del denunciante. 5.- Expresar en qué consiste la ilegitimidad del acto y ofrecer la prueba que estime pertinente. Si el denunciante ignora alguno de los requisitos contenidos en los Incisos 2), 3) y 4), debe proporcionar los datos que mejor conduzcan a su averiguación. La denuncia puede ser formulada a cualquier hora del día, por escrito u oralmente valiéndose de cualquier medio de comunicación, en cuyo caso se debe labrar acta por el funcionario autorizado; en ambos casos se debe comprobar inmediatamente la identidad del denunciante y cuando ello no es posible, sin perjuicio de la prosecución del trámite, la jueza o juez debe arbitrar los medios necesarios a tal efecto.-"},{"n":262,"r":"DESESTIMACIÓN","t":"DESESTIMACIÓN. La jueza o juez debe rechazar in límine la denuncia que no se refiere a uno de los casos establecidos en este Capítulo, pero en ningún supuesto lo puede hacer fundándose en defectos formales que, si existe, debe proveer de inmediato las medidas que considere conducentes para subsanarlos.-"},{"n":263,"r":"AUTO DE HÁBEAS CORPUS","t":"AUTO DE HÁBEAS CORPUS. Cuando se trate de la privación de la libertad de una persona, formulada la denuncia, la jueza o juez debe ordenar inmediatamente que la autoridad requerida, en su caso, presente ante él al detenido, salvo que circunstancias especiales determinen lo contrario, con un informe circunstanciado del motivo que funda la medida, la forma y condiciones en que se cumple, si ha obrado por orden escrita de autoridad competente, supuesto en el cual debe acompañarla, y si el detenido ha sido puesto a disposición de otra autoridad, a quién, por qué causa y en qué oportunidad se efectuó la transferencia. Cuando se trate de amenaza actual de privación de la libertad de una persona, de agravamiento arbitrario de las condiciones de detención legal o desaparición forzada de personas, la jueza o juez debe ordenar que la autoridad requerida presente el informe a que se refiere el párrafo anterior, en lo pertinente. Si se ignora la autoridad que detenta la persona privada de su libertad o de la cual emana el acto denunciado como lesivo, la jueza o juez debe librar la orden a los superiores jerárquicos de la dependencia que la denuncia indique. La orden se emitirá por escrito, con expresión de fecha y hora, salvo que la jueza o juez considere necesario constituirse personalmente en el lugar donde se encuentre el detenido, caso en el cual puede emitirla oralmente, pero debe dejar constancia en acta. Asimismo, la jueza o juez puede disponer de oficio todas las diligencias que estime necesarias y ordenar la producción de la prueba ofrecida que considere pertinente y útil. -"},{"n":264,"r":"ACTUACIÓN DE OFICIO","t":"ACTUACIÓN DE OFICIO. Cuando la jueza o juez competente tome conocimiento por denuncia o por vehementes indicios de que alguna persona es mantenida en custodia, detención o confinamiento por funcionario público o un particular y que es de temerse que sea transportada fuera del territorio de su jurisdicción o que se le hará sufrir un perjuicio irreparable antes de que pueda ser socorrida por un auto de hábeas corpus, debe expedirlo de oficio, ordenando a quien la detente o a cualquier funcionario judicial o policial para que la traiga a su presencia a fin de resolver lo que corresponda.- ¿52 AAA E AZ Srs ¡Ed COMA ii e"},{"n":265,"r":"INTERVENCIÓN DEL MINISTERIO PÚBLICO FISCAL","t":"INTERVENCIÓN DEL MINISTERIO PÚBLICO FISCAL. Presentada la denuncia, se debe notificar al Ministerio Público Fiscal, por escrito u oralmente, dejando en este caso constancia en acta, quien tiene en el procedimiento todos los derechos otorgados a los demás intervinientes, pero no es necesario citario o notificarlo para la realización de los actos posteriores. : El Ministerio Público Fiscal puede presentar las instancias que crea convenientes y recurrir la decisión cualquiera sea el sentido de ella.-"},{"n":266,"r":"CUMPLIMIENTO DE LA ORDEN","t":"CUMPLIMIENTO DE LA ORDEN. Todo funcionario o empleado público, sin excepción de ninguna clase, está obligado a cumplir las órdenes que imparte la jueza o juez del hábeas corpus, en forma inmediata o en el plazo que éste determine de acuerdo con las circunstancias del caso, el que no puede exceder de 12 horas. Si por un impedimento físico la persona detenida no puede ser llevada a presencia de la jueza o juez, la autoridad requerida debe presentar en el mismo plazo un informe complementario sobre la causa que impide el cumplimiento de la orden, estimando el término en que podrá ser cumplida. La jueza o juez debe decidir expresamente sobre el particular, debiendo constituirse donde se encuentra la persona detenida si estima necesario realizar alguna diligencia y aun autorizar a un familiar o persona de confianza para que lo vea en su presencia. Desde el conocimiento de la orden de hábeas corpus la persona detenida queda a disposición de la jueza o juez que la emitió para la realización del procedimiento. La jueza o juez adoptará las medidas pertinentes para localizar a la persona en cuyo favor se denuncia y para que permanezca en un lugar adecuado, ajena a la acción del denunciado y alejada de su presencia, hasta que se resuelva definitivamente la cuestión planteada.- :"},{"n":267,"r":"PROCEDIMIENTO CON EL PARTICULAR DENUNCIADO","t":"PROCEDIMIENTO CON EL PARTICULAR DENUNCIADO. Cuando la persona denunciada es un particular o grupo de éstos, la jueza o juez comunicará por medio de la Oficina de Gestión Judicial al Ministerio Público Fiscal, remitiendo las : constancias de sus actuaciones, para su actuación de competencia.-"},{"n":268,"r":"CITACIÓN A LA AUDIENCIA","t":"CITACIÓN A LA AUDIENCIA. La orden de hábeas corpus implica para la autoridad requerida, cuando corresponde, la citación a la audiencia oral, a la que puede comparecer representada por un funcionario de la repartición debidamente autorizado, con derecho a asistencia letrada. Cuando la persona amparada no esté privada de su libertad, la jueza o juez la debe citar inmediatamente para la audiencia oral, comunicándole que, en su ausencia, puede ser representado por el defensor oficial. La persona amparada puede nombrar un defensor o ejercer la defensa por sí misma, siempre que ello no perjudique su eficacia, caso en el cual se designa un defensor oficial.-"},{"n":269,"r":"AUDIENCIA ORAL","t":"AUDIENCIA ORAL. La jueza o juez interviniente puede convocar a una audiencia oral, citando a tal fin a los interesados cuya presencia estime necesaria. En ? su caso, tanto el requirente como el requerido deben contar con asistencia letrada cuando corresponda. La audiencia comienza con la lectura de la denuncia y del informe o acta respectiva. Luego la jueza o juez ordena la incorporación de la prueba y da oportunidad a los intervinientes para que se pronuncien por sí o por intermedio de sus letrados.-"},{"n":270,"r":"DECISIÓN","t":"DECISIÓN. Recibidos los informes o terminada la audiencia, la jueza O juez debe dictar inmediatamente la resolución, que debe contener: 1.- Día y hora de su emisión. 2.- Mención del acto denunciado como lesivo, de sus autores y de la persona que lo sufre, 3.- Motivación de la decisión. 4.- La parte resolutiva, que debe versar sobre el rechazo de la denuncia o su acogimiento, caso en el cual se ordena la inmediata libertad de la persona detenida o la cesación del acto lesivo. 5.- Pronunciamiento sobre costas y sanciones que pueden corresponder. 6.- La firma de la jueza o juez. Si se tiene conocimiento de la probable comisión de un delito de acción pública, la jueza o juez debe ordenar la remisión de las copias pertinentes de las actuaciones a la fiscalía que resulte competente.-"},{"n":271,"r":"LECTURA DE LA DECISIÓN","t":"LECTURA DE LA DECISIÓN. La decisión debe ser leída inmediatamente por la jueza o juez o funcionario autorizado ante los intervinientes y éstos quedan notificados, aunque alguno de ellos se haya alejado de la sala de audiencias.-"},{"n":272,"r":"RECURSOS","t":"RECURSOS. Contra la decisión se puede interponer recurso en el plazo de 24 horas, por escrito u oralmente por el ante la misma jueza o juez que la dictó, y se concederá por ante el Tribunal de Impugnaciones. Puede interponer recurso la persona amparada, su defensor, la autoridad requerida, el particular o grupo de éstos, el denunciante o sus representantes. Cuando ha comparecido la persona amparada, el denunciante únicamente puede recurrir por la sanción o costas, en caso de que le fueran impuestas. El recurso procede siempre con efecto suspensivo, salvo en lo que respecta a la libertad de la persona que se hace efectiva inmediatamente. Contra la decisión que deniega el recurso procede la queja por escrito ante el Tribunal de impugnaciones que debe resolver dentro de las 24 horas previo a requerir las actuaciones.-"},{"n":273,"r":"PROCEDIMIENTO DE IMPUGNACIÓN","t":"PROCEDIMIENTO DE IMPUGNACIÓN. Concedido el recurso, la Oficina de Gestión Administrativa deberá fijar una audiencia en el término de 24 horas ante el Tribunal de Impugnaciones y emplazará a los intervinientes para que comparezcan. El Tribunal de Impugnaciones se conformará en Sala Unipersonal, conocerá de todo cuanto resulte pertinente y decidirá en la misma audiencia.-"},{"n":274,"r":"INTERVENCIÓN DEL DENUNCIANTE","t":"INTERVENCIÓN DEL DENUNCIANTE. El denunciante, cuando no ha comparecido la persona amparada, puede intervenir en el procedimiento de hábeas corpus con asistencia letrada y tiene en él los derechos otorgados a los demás intervinientes.- . 10.797 LIBRO V CONTROL DE LAS DECISIONES JUDICIALES TÍTULO 1 NORMAS GENERALES"},{"n":275,"r":"PRINCIPIO GENERAL","t":"PRINCIPIO GENERAL. Las decisiones judiciales sólo serán impugnables en los casos, por los motivos y en las condiciones establecidas por este Código. El derecho de impugnar una decisión corresponderá tan sólo a quien le sea expresamente acordado. Las partes sólo podrán impugnar las decisiones judiciales que les causen agravio.-"},{"n":276,"r":"DECISIONES DURANTE LAS AUDIENCIAS","t":"DECISIONES DURANTE LAS AUDIENCIAS. Durante las audiencias, sólo será admisible la revocatoria, que será resuelta de inmediato. Su planteamiento significará la reserva de impugnar la sentencia, siempre que el vicio o defecto señalado no sea saneado y provoque un gravamen irreparable a quien lo dedujo.-"},{"n":277,"r":"COMPETENCIA","t":"COMPETENCIA. El tribunal a quien corresponda el control de una decisión judicial sólo será competente en relación a los puntos que motivan los agravios, salvo el control de constitucionalidad.-"},{"n":278,"r":"EXTENSIÓN","t":"EXTENSIÓN. REFORMA EN PERJUICIO. Cuando existan personas coimputadas, la impugnación interpuesta por una de ellas favorecerá también a las demás, a menos que se base en motivos exclusivamente personales. Cuando la resolución haya sido impugnada sólo por la persona imputada, no podrá modificarse en su perjuicio. La impugnación deducida por cualquier parte permitirá modificar o revocar la resolución a favor de la persona imputada.-"},{"n":279,"r":"EFECTO SUSPENSIVO","t":"EFECTO SUSPENSIVO. Las decisiones judiciales no serán ejecutadas durante el plazo para impugnar y mientras tramite la instancia de control, salvo disposición expresa en contrario. Las decisiones que versen sobre la aplicación de medidas cautelares serán impugnables sin efecto suspensivo.-"},{"n":280,"r":"DESISTIMIENTO","t":"DESISTIMIENTO. Las partes podrán desistir de la impugnación, sin perjudicar el derecho de las restantes. El defensor no podrá desistir de su impugnación, salvo que se acredite de manera fehaciente la conformidad de la persona imputada.- TÍTULO Il ) DECISIONES IMPUGNABLES Y LEGITIMACIÓN"},{"n":281,"r":"","t":"Sólo podrán impugnarse las sentencias definitivas, el sobreseimiento, las excepciones, la aplicación de medidas cautelares y de coerción, la denegatoria o revocatoria de la suspensión del proceso a prueba, los procedimientos. abreviados, el sometimiento del caso bajo el sistema de asuntos complejos y las decisiones que se tomen durante la ejecución de la pena.-"},{"n":282,"r":"SOBRESEIMIENTO","t":"SOBRESEIMIENTO. El sobreseimiento podrá impugnarse por los siguientes motivos: 1.- Cuando su motivación se funde en una valoración de la prueba arbitraria o absurda. 2.- Cuando se haya inobservado o aplicado erróneamente un precepto legal.-"},{"n":283,"r":"SENTENCIA CONDENATORIA","t":"SENTENCIA CONDENATORIA. La sentencia condenatoria podrá ser impugnada, al igual que la que impone una medida de seguridad, ya sea por defectos formales o sustanciales, o por errónea valoración de la prueba, por el imputado y su defensor.-"},{"n":284,"r":"SENTENCIA ABSOLUTORIA","t":"SENTENCIA ABSOLUTORIA. La sentencia absolutoria podrá impugnarse únicamente por la fiscalía y por la parte querellante que acusó, exclusivamente por los siguientes motivos: 1.- Arbitrariedad de la sentencia. . 2.- Apreciación manifiestamente absurda de las pruebas recibidas en el juicio.-"},{"n":285,"r":"LEGITIMACIÓN DE LA PERSONA IMPUTADA","t":"LEGITIMACIÓN DE LA PERSONA IMPUTADA. Además de la sentencia condenatoria, tratada en las disposiciones anteriores, la persona imputada podrá impugnar la revocatoria del sobreseimiento, la denegatoria de la suspensión del juicio a prueba, las medidas de coerción y demás cautelares, la transformación de un proceso en complejo, y las disposiciones que se adopten durante la etapa de la ejecución de la pena. El derecho al recurso corresponde indistintamente a la persona imputada y a su defensa técnica. En caso de duda debe presumirse que la persona imputada ha ejercido su derecho a impugnar.-"},{"n":286,"r":"LEGITIMACIÓN DE LA QUERELLA","t":"LEGITIMACIÓN DE LA QUERELLA. La parte querellante podrá impugnar el sobreseimiento, la absolución y la condena cuando la pena aplicada fuere inferior a la mitad de la pena pretendida.-"},{"n":287,"r":"LEGITIMACIÓN DE LA FISCALÍA","t":"LEGITIMACIÓN DE LA FISCALÍA. El o la fiscal podrá impugnar las decisiones judiciales en los siguientes casos: 1.- Enlos sobreseimientos y demás resoluciones que pongan fin a la acción o a la pena o hagan imposible que continúen las actuaciones y la denegación de medidas cautelares, cuando no hubiese habido dos pronunciamientos en el mismo sentido. 2.- En la sentencia absolutoria, si hubiere requerido una pena superior a los tres (3) años de privación de libertad. 3.- En la sentencia condenatoria, si la pena aplicada fuera inferior a la mitad de la pena pretendida. 4.- —Enlas decisiones que se tomen durante la ejecución de la pena. Estos límites no regirán si la persona imputada es funcionario público y el hecho se ha cometido en el ejercicio de la función o en ocasión de ella.- A a a AAA] ¿ES COPIA FlEL DEL ORIGINAL: l 10.797 TÍTULO Il . PROCEDIMIENTO DE LA IMPUGNACIÓN"},{"n":288,"r":"INTERPOSICIÓN","t":"INTERPOSICIÓN. La impugnación se interpondrá por escrito ante el mismo tribunal que dictó la resolución, dentro del plazo de diez (10) días si se trata de sentencia y de tres (3) días en los demás casos. En la presentación sólo deberán individualizarse los motivos y agravios de la impugnación, salvo que el recurso sea interpuesto directamente por el imputado. Sin perjuicio de ello, podrán incluirse nuevos agravios en la presentación oral. La fundamentación del recurso será desarrollada en audiencia. No se admitirá la presentación de escritos que pretendan suplir la argumentación oral del recurso. Se deberá también designar el domicilio electrónico para recibir las comunicaciones de la Oficina Judicial correspondiente al tribunal de la impugnación.-"},{"n":289,"r":"PRUEBA","t":"PRUEBA. Si el impugnante requiere la producción de prueba, la ofrecerá o individualizará junto con el escrito de interposición, señalando en forma concreta la circunstancia o motivo que se pretende probar. No se admitirá ninguna prueba que no se vincule con los motivos invocados.-"},{"n":290,"r":"COMUNICACIÓN Y REMISIÓN","t":"COMUNICACIÓN Y REMISIÓN. Formulada la impugnación, la Oficina Judicial comunicará la interposición a las otras partes, poniendo a su disposición su : contenido y la fecha de la audiencia. En los supuestos en que se haya ofrecido prueba, la valoración de su procedencia será decidida en la misma audiencia del recurso.-"},{"n":291,"r":"AUDIENCIA","t":"AUDIENCIA. Recibidas las actuaciones, la Oficina Judicial sorteará la jueza o juez que intervendrá y fijará fecha para la audiencia oral y pública dentro de los cinco (5) días desde la última comunicación. La audiencia se celebrará con todas las partes o sus abogados, quienes deberán presentar oralmente sus fundamentos y explicar la decisión cuestionada. Las juezas o jueces promoverán la contradicción entre ellas a los efectos de escuchar las distintas opiniones objeto de impugnación. Las partes podrán ampliar la fundamentación o desistir de alguna de las cuestiones. En este acto, el imputado podrá introducir motivos nuevos. En la audiencia, las juezas o jueces podrán interrogar a los recurrentes sobre las cuestiones planteadas y sus fundamentos legales, doctrinarios o jurisprudenciales. Si la parte impugnante requiere la producción de prueba, la ofrecerá junto con el escrito de interposición, señalando en forma concreta el hecho que se pretende probar. Quien la ofreció tomará a su cargo la presentación y las juezas o jueces resolverán únicamente con la prueba admitida y que se produzca.-"},{"n":292,"r":"RESOLUCIÓN","t":"RESOLUCIÓN. Cuando la revisión de la decisión sea una sentencia condenatoria o absolutoria, a excepción de los procedimientos abreviados, intervendrán tres (3) juezas o jueces con funciones de revisión que dictarán por escrito la resolución dentro de los veinte (20) días a contar desde que se produjo la celebración de la audiencia. En los demás supuestos, las juezas o jueces actuarán en forma unipersonal y deberán resolver oralmente y de inmediato, brindando los fundamentos al finalizar la misma. Si la anulación es parcial, se indicará el objeto concreto del nuevo juicio o resolución. Si por efecto de la resolución debe cesar la prisión del imputado, se ordenará directamente la libertad. isa pan 1 O PRNA ¿ ES UASD ia AE Cuando de la correcta aplicación de la Ley resulte la absolución de la persona sujeta al proceso, la extinción de la acción penal o sea evidente que para dictar una nueva sentencia no es necesaria la realización de un nuevo juicio, el tribunal resolverá directamente sin reenvío. En estos casos, si la impugnación fue promovida por la o el fiscal o el querellante y fuera adversa para la persona imputada, ésta podrá solicitar su revisión ante otros tres (3) juezas o jueces.-"},{"n":293,"r":"REENVÍO","t":"REENVÍO. Si se reenvía a un nuevo juicio no podrán intervenir las juezas o jueces que conocieron del juicio anulado. Si el reenvío procede como consecuencia de un recurso de la persona imputada, en el nuevo juicio no podrá aplicarse una pena superior a la impuesta en el primero, Si en el nuevo juicio se obtiene una segunda absolución, esta decisión no será susceptible de impugnación alguna.- TÍTULO IV CONTROL EXTRAORDINARIO"},{"n":294,"r":"PROCEDENCIA Y MOTIVOS","t":"PROCEDENCIA Y MOTIVOS. La impugnación extraordinaria procederá contra las sentencias dictadas por las juezas o jueces con funciones de impugnación ordinaria. Procederá en los siguientes casos: 1.- Cuando se cuestione la validez de una ley, ordenanza, decreto o reglamento que estatuyan sobre materia regida por la Constitución y la decisión sea contraria a las pretensiones del impugnante. 2- En los supuestos que correspondiere la interposición del recurso extraordinario federal. 3.- Cuando la sentencia de las juezas o jueces con funciones de impugnación ordinaria resulte contradictoria con la doctrina sentada en fallos anteriores de los mismos jueces o del Tribunal Superior de Justicia sobre la misma cuestión.-"},{"n":295,"r":"PROCEDIMIENTO","t":"PROCEDIMIENTO. Para lo relativo al procedimiento y la decisión se aplican analógicamente las disposiciones relativas a la impugnación ordinaria de las sentencias, a excepción del plazo para decidir que podrá extenderse hasta el plazo máximo de cuarenta (40) días.-"},{"n":296,"r":"COMUNICACIÓN Y REMISIÓN","t":"COMUNICACIÓN Y REMISIÓN. Formulada la impugnación extraordinaria, la Oficina Judicial comunicará la interposición a las otras partes, poniendo a su disposición su contenido para que en el plazo común de diez (10) días formulen su contestación de agravios. Vencido ese plazo se remitirá al Tribunal Superior de Justicia los escritos presentados por las partes, la sentencia cuestionada y aquellos elementos de juicio que las partes hubieren solicitado que se adjunten.- ES COPIA EL CEL CAL Ñ O]"},{"n":297,"r":"AUDIENCIA","t":"AUDIENCIA. Dentro de los diez (10) días de recibidas las actuaciones, el Tribunal Superior de Justicia convocará a una audiencia oral y pública, a la que las partes deberán comparecer bajo apercibimiento de tenerse por desistido al recurrente. En la audiencia, el recurrente expresará los fundamentos de su impugnación, pudiendo ampliar los que manifestará en su expresión de agravios y los debatirá en forma oral con la contraria. En la audiencia, los jueces podrán requerir precisiones a los recurrentes sobre las cuestiones planteadas y sus fundamentos legales, doctrinarios o jurisprudenciales. Regirán en lo pertinente las reglas del juicio oral.- ARTÍCULO 298% RESOLUCIÓN. Una vez finalizada la audiencia, el Tribunal Superior de Justicia pasará a resolver, debiendo emitir su veredicto en un plazo máximo de cuarenta (40) días, convocando a una audiencia para su lectura. Si la anulación es parcial se indicará el objeto concreto del nuevo juicio o resolución. Si por efecto de la resolución debe cesar la prisión de la persona imputada, el Tribunal Superior de Justicia ordenará directamente la libertad. Cuando de la correcta aplicación de la ley resulte la absolución de la persona imputada, la extinción de la acción penal, o sea evidente que para dictar una nueva sentencia no es necesaria la realización de un nuevo juicio, el Tribunal Superior de Justicia resolverá directamente sin reenvío.-"},{"n":298,"r":"RESOLUCIÓN","t":"RESOLUCIÓN. Una vez finalizada la audiencia, el Tribunal Superior de Justicia pasará a resolver, debiendo emitir su veredicto en un plazo máximo de cuarenta (40) días, convocando a una audiencia para su lectura. Si la anulación es parcial se indicará el objeto concreto del nuevo juicio o resolución. Si por efecto de la resolución debe cesar la prisión de la persona imputada, el Tribunal Superior de Justicia ordenará directamente la libertad. Cuando de la correcta aplicación de la ley resulte la absolución de la persona imputada, la extinción de la acción penal, o sea evidente que para dictar una nueva sentencia no es necesaria la realización de un nuevo juicio, el Tribunal Superior de Justicia resolverá directamente sin reenvío.-"},{"n":299,"r":"REENVÍO","t":"REENVÍO. Si se reenvía a un nuevo juicio no podrán intervenir las juezas o jueces titulares que integraron el tribunal del juicio anulado. Si el reenvío procede como consecuencia de un recurso de la persona imputada, en el nuevo juicio no podrá aplicarse una pena superior a la impuesta en el primero. Si en el nuevo juicio se obtiene una segunda absolución, esta decisión no será susceptible de impugnación alguna.- ) TÍTULO V REVISIÓN DE LA SENTENCIA CONDENATORIA"},{"n":300,"r":"PROCEDENCIA","t":"PROCEDENCIA. Procederá la revisión de una sentencia firme, en todo tiempo y únicamente a favor de la persona condenada, por los motivos siguientes: 1.- Cuando los hechos tenidos como fundamento de la sentencia resulten incompatibles con los establecidos por otra sentencia penal. 2.- Cuando la sentencia impugnada se haya fundado en prueba documental o testimonial, cuya falsedad se haya declarado en fallo posterior o resulte evidente, aunque no exista un pronunciamiento posterior. 3.- Cuando la sentencia condenatoria haya sido pronunciada a consecuencia de prevaricato, cohecho u otro delito cuya existencia se haya declarado en fallo posterior. 4.- Cuando después de la sentencia sobrevengan hechos nuevos o elementos de prueba que solos o unidos a los ya examinados en el procedimiento hagan evidente que el hecho no existió, que la persona imputada no lo cometió o que el hecho cometido no es punible o corresponde aplicar una norma más favorable. E ear 1 10 PRADA 2 e e as CO E A - 10.797 FUNCION LEGISLATIVA - 5.- Cuando corresponda aplicar una ley más benigna o se produzca un cambio en la jurisprudencia de la Corte Interamericana de Derechos Humanos, la Corte Suprema de Justicia de la Nación, el Tribunal Superior de Justicia o en los tribunales de impugnación que favorezca a la persona condenada. El rechazo de la solicitud de revisión no impedirá un nuevo pedido fundado en motivos distintos.-"},{"n":301,"r":"LEGITIMACIÓN","t":"LEGITIMACIÓN. Podrán solicitar la revisión: 1.- La persona condenada, su defensora o defensor. 2.- Laoel fiscal a favor de la persona condenada. 3.- Lao el cónyuge, conviviente, ligado por especiales vínculos de afectos y ascendientes o descendientes de la persona condenada, si esta hubiese fallecido.-"},{"n":302,"r":"INTERPOSICIÓN","t":"INTERPOSICIÓN. El pedido de revisión se interpondrá por escrito ante la Oficina Judicial, quien sorteará a tres (3) juezas o jueces para que lo resuelvan. Deberá contener la concreta referencia de los motivos en que se funda, las disposiciones legales aplicables y copia de la sentencia de condena. Junto con el escrito se ofrecerán las pruebas y, en lo posible, se agregarán los documentos o se designará el lugar donde podrán ser requeridos.-"},{"n":303,"r":"PROCEDIMIENTO","t":"PROCEDIMIENTO. Para el procedimiento regirán las reglas previstas para las impugnaciones, en cuanto sean aplicables. Las juezas o jueces podrán disponer todas las indagaciones y diligencias preparatorias que consideren útiles y delegar su ejecución en alguno de sus integrantes. Podrá suspender la ejecución de la sentencia y disponer la libertad provisional de la persona condenada.-"},{"n":304,"r":"RESOLUCIÓN","t":"RESOLUCIÓN. Se podrá anular la sentencia remitiendo a un nuevo juicio cuando el caso lo requiera o pronunciar directamente la sentencia definitiva. . Cuando la sentencia sea absolutoria o declare la extinción de la acción penal se ordenará la libertad de la persona imputada, la restitución de la multa pagada y de los objetos decomisados, sin perjuicio de la indemnización civil que podrá reclamarse en el fuero correspondiente.- ) TÍTULO VI EJECUCIÓN, COSTAS E INDEMNIZACIONES CAPÍTULO | EJECUCION PENAL"},{"n":305,"r":"JUEZA O JUEZ CON FUNCIONES DE EJECUCIÓN","t":"JUEZA O JUEZ CON FUNCIONES DE EJECUCIÓN. La jueza o juez con funciones de ejecución deberá velar por el cumplimiento de las normas constitucionales, los instrumentos internacionales de derechos humanos ratificados por la República Argentina, la Ley de Ejecución Penal, en el trato otorgado a las personas condenadas que se encuentren bajo potestad del Servicio Penitenciario Provincial y a las personas sometidas a medidas de seguridad personal. La jueza o juez con funciones de ejecución resuelve en audiencia oral con presencia de las partes sobre: AY 1 an paris 0 (el Ci - 10.797 1.- Las impugnaciones a las sanciones disciplinarias dictadas por la autoridad administrativa del Servicio Penitenciario Provincial. 2.- La concesión o rechazo de los derechos de semilibertad, salida transitoria, semidentencion, prisión discontinua, libertad condicional, salidas transitorias, prisión domiciliaria y todo derecho o beneficio contemplado en las leyes de ejecución de penas privativas de la libertad; frente al rechazo de la libertad condicional, sólo podrá requerirse la misma pasado seis (6) meses desde el dictado de la misma. 3.- La suspensión o revocación por incumplimiento reiterado de las reglas de conducta de semilibertad, salidas transitorias, libertad condicional, libertad asistida, prisión domiciliaria.-"},{"n":306,"r":"DERECHOS","t":"DERECHOS. La persona condenada podrá ejercer durante la ejecución de la pena todos los derechos y facultades que le otorgan la Constitución Nacional, los instrumentos internacionales de derechos humanos, la Constitución Provincial, las leyes de ejecución penal y plantear ante las juezas o jueces que correspondan las quejas y asuntos que estime convenientes. La ejecución penal se realizará con observancia a la aplicación de normas interamericanas sobre las obligaciones diferenciadas de los Estados para decidir respecto de la situación de desigualdad real de grupos en situación especial de riesgo en el contexto de privación de libertad. En particular, de mujeres o personas embarazadas con otras identidades de género con capacidad de gestar, en período de posparto y lactantes; personas LGBT; personas indígenas; personas mayores; y niños y niñas que viven con sus madres en prisión.-"},{"n":307,"r":"DEFENSA TÉCNICA Y ACCESO A LA INFORMACIÓN","t":"DEFENSA TÉCNICA Y ACCESO A LA INFORMACIÓN. La defensa técnica de la persona condenada podrá ser ejercida por la defensora o el defensor que actuó hasta la sentencia definitiva, siempre que aquel ratificare la aceptación del cargo ante la jueza o juez con funciones de ejecución o por otra defensora o defensor de confianza que proponga la persona condenada. En el caso de que la persona condenada no tenga abogada o abogado de confianza se designará una defensora o defensor público. La persona condenada y su defensa técnica podrán tomar vista de todos los informes que realice el Servicio Penitenciario que tengan vinculación o puedan influir en la forma de cumplimiento de la pena.-"},{"n":308,"r":"DERECHOS DE LA VÍCTIMA","t":"DERECHOS DE LA VÍCTIMA. La víctima tendrá derecho a ser informada y a expresar su opinión y todo cuanto estime conveniente, ante la jueza o juez de ejecución, también en la vía recursiva ante la jueza o juez de revisión o impugnación, cuando se sustancie cualquier planteo en el que se pueda decidir la incorporación de la persona condenada a: a) Salidas transitorias. b) Régimen de semilibertad. c) Libertad condicional. ie pona E OL A] A A A A A d) Prisión domiciliaria. e) Prisión discontinua o semidetención. f) Libertad asistida. g) Régimen preparatorio para su liberación. La Oficina Judicial, inmediatamente posterior al momento del dictado de la sentencia condenatoria, deberá consultar a la víctima si desea ser informada acerca de los planteos referidos en el párrafo que antecede. En ese caso, la víctima deberá fijar un domicilio, podrá designar a una o un representante legal, proponer peritos y establecer el modo en que recibirá las comunicaciones. Incurrirá en falta grave la jueza o juez y responsable de la Oficina Judicial que incumpliere las obligaciones establecidas en este Artículo.-"},{"n":309,"r":"SENTENCIA ABSOLUTORIA","t":"SENTENCIA ABSOLUTORIA. La sentencia absolutoria será ejecutada por las juezas o jueces de juicio inmediatamente, aunque sea recurrida. Cuando adquiera firmeza, las juezas o jueces con funciones de juzgamiento ordenarán, por medio de la Oficina Judicial, las inscripciones y comunicaciones correspondientes. -"},{"n":310,"r":"REMISIÓN DE LA SENTENCIA CONDENATORIA","t":"REMISIÓN DE LA SENTENCIA CONDENATORIA. Sólo podrán ser ejecutadas las sentencias firmes. En tal caso, el órgano jurisdiccional remitirá a la Oficina Judicial la parte dispositiva de la sentencia condenatoria para que forme la carpeta de ejecución penal y pondrá en conocimiento a la jueza o juez y a las partes que intervengan cuando ello se produzca.-"},{"n":311,"r":"CÓMPUTO Y REMISIÓN","t":"CÓMPUTO Y REMISIÓN. La jueza o juez o quien preside el Tribunal de Juicio deben hacer practicar por intermedio de la Oficina Judicial el cómputo de la pena, de acuerdo a lo previsto en el Código Penal, fijando en su caso la fecha de vencimiento o su monto. Dicho cómputo debe ser notificado al Ministerio Público Fiscal, a la persona condenada y a su defensora o defensor, quienes pueden observarlo dentro de los tres (3) días. Si se deduce oposición, el Tribunal de Juicio, previa sustanciación, debe resolverla en el plazo de tres (3) días. Si no media oposición o resuelta la que sea deducida, el cómputo se aprueba y la sentencia debe ser comunicada inmediatamente al Juzgado de Ejecución, a quien se remite copia de la misma para que forme la carpeta de ejecución penal dando inmediato conocimiento a las partes. El Juzgado de Ejecución, en el ejercicio de su competencia, tiene las atribuciones contenidas en este Código. En lo sucesivo cuando el cómputo debe ser modificado, se debe seguir el mismo trámite por ante la jueza o juez de ejecución. El cómputo es siempre revisable aun de oficio, cuando se compruebe un error formal, material o nuevas circunstancias lo tornen necesario. Recibido el cómputo por el Juzgado de Ejecución deberá informar a la persona condenada del monto, vencimiento de la pena y las fechas en las que puede acceder a los beneficios que por derecho le corresponden en el régimen de progresividad de la ejecución penal.- : 86 a ES LGA IIS dol SAL"},{"n":312,"r":"CÓMPUTO DEFINITIVO","t":"CÓMPUTO DEFINITIVO. Si se modificare la sanción impuesta en la sentencia dictada por el tribunal de juicio, la jueza o juez con funciones de ejecución en audiencia con las partes practicará el cómputo de pena fijando la fecha en que finalizará la condena, y todo aquel instituto que implique un egreso transitorio o definitivo, de conformidad con la Ley de Ejecución Penal. La decisión es revisable por otra jueza o juez. El cómputo será comunicado a las partes quienes podrán observarlo dentro de los tres (3) días. Sin perjuicio de ello, el cómputo será siempre revisable, aun de oficio, si se comprueba un error formal, material o cuando nuevas circunstancias lo hagan necesario. Aprobado el cómputo, la Oficina Judicial dispondrá de inmediato las comunicaciones e inscripciones que correspondan para comenzar la ejecución de la pena.-"},{"n":313,"r":"UNIFICACIÓN DE PENAS O CONDENAS","t":"UNIFICACIÓN DE PENAS O CONDENAS. Si durante la ejecución de la pena las partes advierten que procede la unificación de penas o condenas se aplicarán las normas pertinentes establecidas en el Código Penal. La jueza o juez de ejecución debe resolver previa audiencia de las partes.-"},{"n":314,"r":"TRÁMITES DE EJECUCIÓN","t":"TRÁMITES DE EJECUCIÓN. El Ministerio Público Fiscal, la persona condenada y su defensora o defensor podrán realizar los planteos que consideren necesarios ante la jueza o juez de ejecución, por intermedio de la Oficina Judicial, relativos a la ejecución, sustitución, modificación o extinción de la pena. Estos deberán ser resueltos en audiencia oral, previa intervención de las partes. Si para la audiencia fuera necesario producir prueba, la parte que la propone se ocupará de presentarla, previa orden de la Jueza o Juez o de la Oficina Judicial cuando ello fuere . menester para cumplimentarla. El Servicio Penitenciario deberá remitir a la Oficina Judicial todos los informes legalmente previstos para resolver los pedidos de egresos transitorios o definitivos un mes antes de la fecha prevista en el cómputo de la pena. En los demás casos, si para la sustanciación de las audiencias se requieren informes del Servicio Penitenciario, deberán expedirse en el plazo máximo de cinco (5) días de haber sido solicitados. La solicitud de los pedidos de informes se practicará a través de la Oficina Judicial. En la resolución se fijarán las condiciones e instrucciones que sean necesarias conforme al instituto solicitado y se ordenará la autoridad competente para vigilarla. Se aplicarán estas normas a los demás institutos previstos en la Ley de Ejecución Penitenciaria en cuanto sean compatibles y a falta de reglas particulares.-"},{"n":315,"r":"REVOCACIÓN","t":"REVOCACIÓN. Cuando se verifique el incumplimiento injustificado de las reglas fijadas o de las condiciones establecidas en el Código Penal o en la Ley de Ejecución Penal se podrá revocar el instituto concedido; previa audiencia de partes.-"},{"n":316,"r":"CONTROL JUDICIAL DE REGLAS DE CONDUCTA","t":"CONTROL JUDICIAL DE REGLAS DE CONDUCTA. El contro! de las reglas de conducta y obligaciones impuestas en las sentencias se hará a través de la Oficina Judicial, quien pondrá la información a disposición de las partes para que puedan hacer peticiones. De igual modo se procederá en relación a las reglas de conducta y obligaciones impuestas con la Suspensión del Proceso a Prueba.- - 10.797"},{"n":317,"r":"CUMPLIMIENTO EN UN ESTABLECIMIENTO DE SALUD","t":"CUMPLIMIENTO EN UN ESTABLECIMIENTO DE SALUD. Sí durante la ejecución de la pena privativa de libertad la persona condenada sufriera alguna enfermedad, la jueza o juez con funciones de ejecución, previo dictamen pericial, dispondrá su internación en un establecimiento adecuado, si no fuere posible atenderlo en aquel donde estuviere alojado o ello importare grave peligro para su salud. El tiempo de internación se computará a los fines de la pena, siempre que la persona condenada se hallare privada de su libertad y que la enfermedad no hubiere sido simulada o procurada para sustraerse a la ejecución de la pena en un establecimiento penitenciario. La internación no podrá afectar el avance en el sistema progresivo de la ejecución.-"},{"n":318,"r":"PRISIÓN DOMICILIARIA","t":"PRISIÓN DOMICILIARIA. La jueza o juez con funciones de ejecución o jueza o juez competente podrá disponer el cumplimiento de la pena impuesta en detención domiciliaria: a) Ala persona interna enferma, cuando la privación de la libertad en el establecimiento carcelario le impida recuperarse o tratar adecuadamente su dolencia y no correspondiere su alojamiento en un establecimiento hospitalario. b) Ala persona interna que padezca una enfermedad incurable en período terminal. c) Ala persona interna discapacitada, cuando la privación de la libertad en el establecimiento carcelario resulte inadecuada por su condición implicándole un trato indigno, inhumano o cruel. d) Ala persona interna mayor de 70 años. e) A las mujeres internas embarazadas o personas embarazadas con otras identidades de género con capacidad de gestar. f Ala interna madre o al padre de un niño menor de 5 años o de una persona con discapacidad a su cargo.-"},{"n":319,"r":"CUMPLIMIENTO EN ESTABLECIMIENTO NACIONAL","t":"CUMPLIMIENTO EN ESTABLECIMIENTO NACIONAL. Si la pena impuesta se debe cumplir en un establecimiento de la Nación, la jueza o juez de ejecución por intermedio de la Oficina Judicial debe cursar comunicación a la Función Ejecutiva, a fin de que solicite al Gobierno de la Nación la adopción de las medidas pertinentes.-"},{"n":320,"r":"EJECUCIÓN DE PENA DE INHABILITACIÓN","t":"EJECUCIÓN DE PENA DE INHABILITACIÓN. Cuando la sentencia de condena imponga pena de inhabilitación, la jueza o juez con funciones de ejecución practicará el cómputo y, por intermedio de la Oficina Judicial, ordenará las inscripciones, anotaciones y demás medidas que correspondan. Los planteos que se susciten relativos a su cumplimiento y el trámite de la rehabilitación se regirán por lo dispuesto en el Título II! del presente Libro.- AE A AM] - 10.797"},{"n":321,"r":"INHABILITACIÓN ACCESORIA","t":"INHABILITACIÓN ACCESORIA. Cuando la pena privativa de la libertad importe la accesoria que establece el Artículo 12 del Código Penal, la Oficina Judicial debe ordenar las inscripciones y anotaciones que correspondan.-"},{"n":322,"r":"INHABILITACIÓN ABSOLUTA","t":"INHABILITACIÓN ABSOLUTA. La parte resolutiva de la sentencia que condene a inhabilitación absoluta deberá hacerse publicar por la Oficina Judicial en el Boletín Oficial, quien además debe cursar las comunicaciones a la Junta Electoral ya las reparticiones o poderes que correspondan, según el caso.-"},{"n":323,"r":"INHABILITACIÓN ESPECIAL","t":"INHABILITACIÓN ESPECIAL. Cuando la sentencia imponga inhabilitación especial, la Oficina Judicial deberá hacer las comunicaciones pertinentes.-"},{"n":324,"r":"EJECUCIÓN DE PENA DE MULTA","t":"EJECUCIÓN DE PENA DE MULTA. La multa debe ser abonada mediante depósito judicial dentro de los diez (10) días desde que la sentencia quede firme o en el plazo que se indique en la sentencia. Vencido este término, la jueza o juez de ejecución, a iniciativa de la o el Fiscal, procederá con arreglo a los Artículos 21” y 22” del Código Penal. Si es necesario, la jueza o juez procederá al embargo y a la venta pública de los bienes embargados, procederá por vía de ejecución de sentencia, conforme al trámite previsto por el Código Procesal Civil de la Provincia. El importe de la multa debe ser transferido a la cuenta especial denominada Fondo de Justicia, creado por el Artículo 21% de la Ley N? 9.241, en el ámbito de la Función Judicial y del Tribunal Superior de Justicia. Determinada la imposibilidad de satisfacer la pena de multa, la jueza o juez de ejecución debe reenviar los antecedentes a la jueza, juez o tribunal de juicio para que cite a la persona condenada para que indique si pretende sustituirla por trabajo comunitario, solicitar plazo para pagarla o pagar en cuotas.-"},{"n":325,"r":"REVISIÓN","t":"REVISIÓN. Las decisiones de la juezas o juez de ejecución que conceda o deniegue las salidas anticipadas, semilibertad, salidas transitorias, libertad asistida, libertad condicional, el cómputo de pena practicado y la unificación de penas podrán ser revisadas en audiencia por ante el Tribunal de Impugnaciones. La solicitud deberá realizarse inmediatamente y la audiencia cumplida en el término de cinco (5) días. El Tribunal resolverá inmediatamente.- CAPÍTULO Il OTRAS DECISIONES SECCIÓN PRIMERA MEDIDAS DE SEGURIDAD :"},{"n":326,"r":"REMISIÓN Y REGLAS ESPECIALES","t":"REMISIÓN Y REGLAS ESPECIALES. Las reglas establecidas en el Capítulo anterior regirán para las medidas de seguridad en lo que sean aplicables. No obstante, se observarán las siguientes disposiciones: 1.- En caso de incapacidad intervendrá la o el representante legal, quien tendrá la obligación de vigilar la ejecución de la medida. 2.- La jueza o juez determinará el establecimiento adecuado para la ejecución y podrá modificar su decisión, incluso a petición del o la representante legal o de la dirección del establecimiento. Via SEAN Y te Le a Al Ll Dr Abe 3.- La jueza o juez examinará periódicamente la situación de quien sufre una medida, fijando un plazo no mayor de seis (6) meses entre cada examen; la decisión versará sobre la cesación o continuación de aquella. 4.- La denegación de la externación será revisable en la forma prevista para la libertad condicional.- SECCIÓN SEGUNDA COSTAS"},{"n":327,"r":"IMPOSICIÓN","t":"IMPOSICIÓN. Toda decisión que ponga término al procedimiento o a un incidente se pronunciará sobre el pago de las costas procesales. Estas serán impuestas a la parte vencida, salvo que el tribunal considere razonable las razones invocadas por la vencida para eximirla total o parcialmente.-"},{"n":328,"r":"CONTENIDO","t":"CONTENIDO. Las costas comprenderán: 1.- Las tasas judiciales. 2.- Los gastos originados por la tramitación del procedimiento. 3.- El pago de los honorarios.-"},{"n":329,"r":"CONDENA","t":"CONDENA. Las costas serán impuestas a la persona acusada cuando sea condenada o cuando se le imponga una medida de seguridad. El precepto no regirá para la ejecución penal ni para las medidas cautelares. . Si en una sola sentencia se pronuncian absoluciones y condenas, el tribunal establecerá el porcentaje que corresponde a cada uno de los responsables. Las personas condenadas por un mismo hecho responderán solidariamente por las costas.- ."},{"n":330,"r":"ACCIÓN PRIVADA","t":"ACCIÓN PRIVADA. En el procedimiento por delito de acción privada, el tribunal decidirá sobre las costas de conformidad a lo previsto en este Título, salvo acuerdo de las partes.-"},{"n":331,"r":"LIQUIDACIÓN Y EJECUCIÓN","t":"LIQUIDACIÓN Y EJECUCIÓN. la directora, director, jefa o jefe de la oficina judicial practicará la liquidación de los gastos y tasas judiciales. Se podrá solicitar la revisión de la liquidación dentro del plazo de cinco (5) días ante la jueza o juez que se sortee a tal efecto.-"},{"n":332,"r":"REMUNERACIÓN","t":"REMUNERACIÓN. Los honorarios y demás gastos derivados de la intervención de las o los peritos corresponderán a la parte que los presentare. Excepcionalmente, la jueza o juez podrá relevar a la parte, total o parcialmente, del pago de la remuneración del o la perito, cuando se demostrase que ella no cuenta con los medios suficientes para solventarlo o cuando tratándose de la persona imputada la no realización de la diligencia pudiere producir un notorio desequilibrio de sus posibilidades de defensa. En este último caso, la jueza o juez regulará prudencialmente la remuneración del o la perito, tomando en cuenta los honorarios de referencia del respectivo colegio profesional o, en su defecto, los usuales en la plaza. El Estado asumirá el adelanto de los gastos, sin perjuicio de los que se dispone en las reglas generales sobre distribución de costas. A: - 10.797 Las o los peritos nombrados de oficio tendrán derecho a cobrar honorarios, exceptuados los que tengan sueldo o remuneración salarial de la Función Pública Nacional Provincial o Municipal, por cargos desempeñados en virtud de conocimientos especiales en la ciencia, arte o técnica que la pericia requiera. La o el perito nombrado a petición de parte puede cobrar directamente a esta o a la persona condenada en costas. -"},{"n":333,"r":"DETERMINACIÓN DE HONORARIOS","t":"DETERMINACIÓN DE HONORARIOS. Se tendrá en cuenta el valor o importancia del proceso, las cuestiones de derecho planteadas, la asistencia a audiencias y, en general, todos los trabajos efectuados a favor de la parte y el resultado obtenido. Los honorarios de las demás personas se determinarán según las normas de las leyes respectivas.-"},{"n":334,"r":"REVISIÓN","t":"REVISIÓN. Cuando a causa de la revisión del procedimiento la ! persona condenada sea absuelta o se le imponga una pena menor será indemnizada en razón del tiempo de privación de libertad o inhabilitación sufrida o del tiempo sufrido en exceso, El precepto regirá, análogamente, para el caso en que la revisión tenga por objeto una medida de seguridad. La multa o su exceso será devuelta. La revisión por aplicación de una ley más benigna, indulto o amnistía no habilitará la indemnización aquí regulada.-"},{"n":335,"r":"OBLIGACIÓN","t":"OBLIGACIÓN. El Estado estará siempre obligado al pago de la indemnización, sin perjuicio de su derecho de repetir contra alguna otra persona obligada. Serán solidariamente responsables quienes hayan contribuido dolosamente o por culpa grave al error judicial. En el caso de las medidas cautelares, la solidaridad alcanzará total o parcialmente a la persona denunciante o a la persona querellante que haya falseado los hechos o litigado con temeridad..- DISPOSICIÓN TRANSITORIA |"},{"n":336,"r":"","t":"Las disposiciones del presente Código Procesal Penal y de la Ley Orgánica de la Justicia Penal entrarán en vigencia el día 1? de agosto de 2026, conforme al cronograma que establezca la Comisión de Implementación, el cual deberá ser progresivo y gradual. En caso de mediar razones de fuerza mayor que impidan total o parcialmente dicha entrada en vigencia, la Comisión deberá presentar un informe fundado ante la Función Legislativa, solicitando la fijación de una nueva fecha de entrada en vigor. La Comisión de Implementación deberá garantizar la puesta en funcionamiento efectiva del Código Procesal Penal y de la Ley Orgánica de la Justicia Penal en todas las circunscripciones judiciales de la Provincia, en un plazo máximo de tres (3) años contados desde la fecha de entrada en vigencia prevista en el primer párrafo del presente Artículo.- DISPOSICIONES TRANSITORIAS Il ORGANO DE APLICACIÓN"},{"n":337,"r":"COMISIÓN DE IMPLEMENTACIÓN","t":"COMISIÓN DE IMPLEMENTACIÓN. Créase una (1) Comisión de Implementación integrada por una o un (1) miembro del Tribunal Superior de Justicia; la o Lis ASI as bio ii - 10.797 el Fiscal General o Adjunto; la o el Defensor General o Adjunto; el Ministerio de Justicia, Seguridad y Derechos Humanos, representado por la Secretaria de Justicia del Gobierno de la Provincia; una o un (1) representante de las Juezas o Jueces con Competencia Penal exclusiva de la Provincia y una o un (1) representante de la Asociación de Magistrados y Funcionarios. La Comisión deberá quedar formalmente constituida en el mes de agosto de 2025, a fin de diseñar su plan de trabajo y garantizar la adecuada implementación y aplicación del Código Procesal Penal de la Provincia. Para que la Comisión pueda arribar a acuerdos válidos deberán reunirse por lo menos la mitad más uno de sus integrantes. Las decisiones y acuerdos se tomarán por mayoría de votos de sus miembros presentes. La Comisión deberá reunirse obligatoriamente por lo menos dos veces al mes, sin perjuicio de hacerlo todas las veces que sea necesario.-"},{"n":338,"r":"FUNCIONES","t":"FUNCIONES. Serán funciones de esta Comisión: a) Diseñar un plan de trabajo previo a la implementación con cada una de las leyes relacionadas a este Código de procedimientos. b) Establecer el cronograma de entrada en vigencia, total o parcial, dentro de los plazos previstos en esta Ley. c) Dictar todas las reglamentaciones y normas prácticas necesarias para la puesta en marcha de las nuevas instituciones de la reforma judicial y de seguridad. d) Coordinar las actividades interinstitucionales necesarias para la puesta en marcha de las nuevas instituciones, racionalizando los recursos existentes en la función judicial para alcanzar los objetivos pautados. e) Supervisar la planificación que lleven adelante cada una de las instituciones, de tal manera que ellas sean compatibles con un plan común de implementación. T Informar a la población sobre los avances del proceso de implementación y diseñar campañas públicas sobre las nuevas instituciones. 9) Evaluar de forma periódica el desempeño de las juezas y jueces integrantes del Colegio de Juezas y Jueces, considerando criterios de objetividad, cumplimiento de los plazos procesales, volumen, complejidad de causas asignadas y cantidad de sentencias dictadas. La Comisión de Implementación contará con una Secretaría Técnica encargada de supervisar los trabajos de implementación y coordinará a los distintos equipos y oficinas de planificación. : La Comisión de implementación llevará a cabo la planificación, seguimiento, evaluación y corrección de la operatividad del nuevo sistema, por lo que deberá permanecer en funciones al menos por un lapso de tres (3) años de la entrada en vigencia de la Ley. k 92 a A o TA SOCIA H DE ds hs CIEAADEML Se encuentra facultado para proponer modificaciones legislativas O dictar reglamentaciones para coordinar el trabajo de los intervinientes en la administración de justicia. También podrá conformar equipos técnicos de trabajo para que se encarguen de los asuntos específicos que les encomiende. Con tal finalidad, puede gestionar la contratación de instituciones especializadas.- DISPOSICIONES TRANSITORIAS lll SISTEMA DE CONCLUSIÓN DE CAUSAS"},{"n":339,"r":"DEFINICIÓN","t":"DEFINICIÓN. Se denomina Sistema de Conclusión de Causas al procedimiento establecido por esta Ley para regular la adecuada finalización de todas las causas penales iniciadas con anterioridad a la entrada en vigencia del Nuevo Sistema de Justicia Penal.-"},{"n":340,"r":"REGLAS","t":"REGLAS. El Sistema de Conclusión de Causas se regirá por las reglas de celeridad, eficiencia, economía procesal y tenderá a lograr el máximo nivel de resolución de conflictos, asegurando el respeto por la vigencia de las garantías establecidas en la Constitución Provincial y la Constitución Nacional.-"},{"n":341,"r":"COMITÉ DE GESTIÓN DE CONCLUSIÓN DE CAUSAS","t":"COMITÉ DE GESTIÓN DE CONCLUSIÓN DE CAUSAS. Créase un Comité de Gestión de Conclusión de Causas, conformado por el Superior Tribunal de Justicia y el Ministerio Público Fiscal. La función única de este Comité será promover y concretar los procedimientos necesarios para una gestión más eficiente del Sistema de Conclusión de Causas sobre las bases de instrumentos procesales establecidos por la presente Ley en el Capítulo siguiente y los que por los actos pertinentes dispongan el Tribunal Superior de Justicia y el Ministerio Público Fiscal.-"},{"n":342,"r":"ESTRUCTURA JUDICIAL DE CONCLUSIÓN DE CAUSAS","t":"ESTRUCTURA JUDICIAL DE CONCLUSIÓN DE CAUSAS. El Tribunal Superior de Justicia tendrá facultades expresas para suprimir, transformar o reasignar funciones a los organismos judiciales abocados al Sistema de Conclusión de Causas, de modo tal que, al finalizar el período de transición, estos se encuentren disueltos o afectados exclusivamente a competencias que no sea de naturaleza penal o transferidos al Nuevo Sistema de Justicia Penal, salvo lo dispuesto en el Artículo 3330.-"},{"n":343,"r":"NORMAS APLICABLES","t":"NORMAS APLICABLES. Las siguientes disposiciones serán aplicables a todas las causas penales indicadas en el Artículo 3330: a) Aquellas causas que se encuentren en la etapa de juicio sin que se haya dictado sentencia, podrán ser concluidas mediante el trámite de juicio abreviado. b) Podrá aplicarse también el procedimiento de suspensión del juicio a prueba. c) Tratándose de causas con imputado no individualizado, la investigación continuará por el plazo de un (1) año, vencido el cual deberán ser archivadas / por resolución fundada. En cuanto sea posible, se utilizarán los datos consignados en las actuaciones como fuente de base de análisis criminal. Lia is IL ds ls USA. l | 10.797 d) Tratándose de causas con personas imputadas individualizadas que no se encuentren privadas de su libertad cautelarmente, previa notificación a la víctima o querellante si lo hubiere, si dentro de los seis (6) meses posteriores la o el fiscal o la víctima o querellante no instaren el proceso de ningún modo, se procederá al archivo de las mismas. Luego de ordenado el archivo y durante el período de transición, la víctima o el querellante, en su caso, podrán ejercer la acción penal a través del ' instituto de la conversión de la acción, previsto en el nuevo Código Procesal ? Penal. e) Si se tratara de causas con personas imputadas individualizadas y con pedidos de captura no declaradas rebeldes, las mismas deberán ser incluidas en un listado a confeccionar por los juzgados intervinientes, previa declaración de rebeldía, que deberá distribuirse a los responsables de la policía y a la fiscalía y publicar en el sitio web de la Función Judicial durante el lapso de un (1) año. ft Tratándose de causas con personas imputadas declaradas rebeldes, las mismas deberán ser declaradas en un listado a confeccionar por los juzgados intervinientes, librándose pedido de captura, si correspondiera. Este listado deberá distribuirse a los responsables de la policía y la fiscalía y publicarse en el sitio web de la Función Judicial durante el lapso de un (1) año. 9) Si se tratara de causas con personas imputadas individualizadas sometidas a medidas cautelares privativas de la libertad, las mismas seguirán siendo tramitadas según su estado. El Ministerio Público Fiscal podrá formular en forma directa el requerimiento de apertura de juicio, de conformidad a lo normado en el nuevo Código Procesal Penal.- :"},{"n":344,"r":"FIN DEL PERÍODO DE TRANSICIÓN","t":"FIN DEL PERÍODO DE TRANSICIÓN. Todas las causas indicadas en el Artículo 333\" en las que, al día de finalización del período de transición, no haya habido decisión definitiva firme serán archivadas de pleno derecho, excepto los casos de querella por delito de acción privada, que continuarán según su estado. A partir de ese momento también cesarán de pleno derecho todas las medidas cautelares personales que se hubieran dispuesto en las causas que se archiven. Tratándose de delitos de acción pública, hasta sesenta (60) días previos a la finalización del período de transición, el querellante o la víctima podrán solicitar que la causa en que fuera parte continúe según su estado. A tal efecto, serán notificadas para hacer valer sus derechos. Si la Fiscalía adhiere a su pedido, la causa se continuará con el mismo procedimiento. En caso contrario, deberá aplicarse el procedimiento de querella prevista para los delitos de acción privada. La Fiscalía podrá solicitar por motivos de política criminal, sesenta (60) días antes del vencimiento del periodo de transición, que no se archive la causa, en cuyo caso deberá continuar según su estado. : En todos los casos en que deban continuar causas luego de finalizado el período de transición, las mismas se tramitarán según las reglas del nuevo Código Procesal Penal y ante los órganos establecidos en las nuevas leyes orgánicas.- PAZ AAA Duro IÍSIL SD a inter e AL AO"},{"n":345,"r":"EXCEPCIONES","t":"EXCEPCIONES. Las disposiciones contenidas precedentemente no serán aplicables a las causas que tramiten por la presunta comisión de los delitos de homicidio; lesiones gravísimas; abuso sexual con acceso carnal y las contempladas en el Primer y Segundo párrafo con agravantes del Párrafo quinto del Artículo 119* del Código Penal; las enmarcadas como violencia de género, Ley Nacional N% 26.485; tortura seguida de muerte; enriquecimiento ilícito y aquellas en que se encuentren imputadas personas funcionarias públicas por la presunta comisión de delitos en el ejercicio de sus funciones y todo otro delito o concurso de los mismos cuya pena máxima prevista sea de ocho (8) años o más, las que continuarán según su estado, incluso ante los órganos previstos en el último párrafo del Artículo anterior.-"},{"n":346,"r":"LISTADO DE CAUSAS","t":"LISTADO DE CAUSAS. Desde el comienzo del período de transición, todos los órganos judiciales encargados del Sistema de Conclusión de Causas deberán confeccionar trimestralmente una lista en la que consten todas las causas que no hayan tenido actuación alguna en los últimos noventa (90) días, indicando cuál fue el último movimiento. En las listas se hará constar el estado procesal de cada causa, si tiene o no personas imputadas individualizadas, si se han dictado y si se encuentran vigentes medidas cautelares y en su caso cuáles; se deberá consignar además si la persona imputada se encuentra rebelde o con pedido de captura y desde qué fecha. Las copias de dichas listas deberán ser remitidas en el mismo plazo a cada uno de los miembros del Comité de Gestión de Conclusión de causas, quienes realizarán evaluaciones y adoptarán las medidas necesarias para cumplir con los fines de esta Ley.-"},{"n":347,"r":"RECURSOS","t":"RECURSOS. A partir del comienzo del período de transición, los recursos de apelaciones de todas las causas indicadas con anterioridad se regirán por las disposiciones del Nuevo Código Procesal Penal, a excepción de aquellas que ya se encuentran radicadas en el órgano judicial correspondiente. - DISPOSICIONES TRANSITORIAS IV Ñ TRANSICIÓN DE MAGISTRADOS, FUNCIONARIOS Y EMPLEADOS DE FUNCIÓN JUDICIAL"},{"n":348,"r":"TRANSICIÓN","t":"TRANSICIÓN. Todas las juezas y jueces que actualmente se desempeñan en el fuero penal, incluidas las juezas y jueces de la Cámara de la Segunda Circunscripción Judicial con sede en la ciudad de Chilecito que se reconfigurará al fuero penal, pasarán a integrar el nuevo sistema de justicia penal, sin perjuicio de continuar a cargo de los casos preexistentes, para lo cual actuarán de conformidad con el Sistema de Conclusión de Causas.-"},{"n":349,"r":"PROGRAMA DE CAPACITACIÓN PARA EL NUEVO SISTEMA DE JUSTICIA PENAL","t":"PROGRAMA DE CAPACITACIÓN PARA EL NUEVO SISTEMA DE JUSTICIA PENAL. A los fines de una efectiva implementación del nuevo Sistema de Justicia, se creará un programa de capacitación cuyo fin será transmitir los valores, principios y reglas del nuevo modelo de justicia. A tales fines, se conformará un cuerpo de capacitadoras o capacitadores que deberán acreditar conocimientos específicos en materia de reformas procesales. Todas las personas operadoras del sistema de administración de justicia deberán cumplir las . capacitaciones que al efecto se determinen.- ! 95 a a o ARTÍCULO 350”. CAPACITACIÓN OBLIGATORIA. Todas las juezas, jueces, funcionarias, funcionarios, empleadas y empleados que presten funciones en el nuevo Sistema de Justicia deben realizar los cursos de capacitación de carácter obligatorio, dentro de los seis (6) meses de la entrada en vigencia del Código Procesal Penal. La inobservancia de esta norma será considerada una falta grave de mal desempeño.-"},{"n":350,"r":"CAPACITACIÓN OBLIGATORIA","t":"CAPACITACIÓN OBLIGATORIA. Todas las juezas, jueces, funcionarias, funcionarios, empleadas y empleados que presten funciones en el nuevo Sistema de Justicia deben realizar los cursos de capacitación de carácter obligatorio, dentro de los seis (6) meses de la entrada en vigencia del Código Procesal Penal. La inobservancia de esta norma será considerada una falta grave de mal desempeño.-"},{"n":351,"r":"FORMACIÓN PROFESIONAL","t":"FORMACIÓN PROFESIONAL. El programa de capacitación deberá realizar cursos para las y los profesionales que ejerzan libremente la actividad.- DISPOSICIÓN TRANSITORIA V PLAZO"},{"n":352,"r":"PLAZO - EXCEPCIÓN","t":"PLAZO - EXCEPCIÓN. El plazo de finalización del período de transición de la presente Ley podrá ser prorrogado por la Función Legislativa, previa solicitud fundada de la Comisión de Implementación.- DISPOSICIONES TRANSITORIAS VI FINANCIAMIENTO DE LA IMPLEMENTACIÓN"},{"n":353,"r":"","t":"Las erogaciones que demande la instrumentación e implementación del nuevo Sistema de Justicia Penal, a efectos del equipamiento adecuado, capacitación y monitoreo, serán atendidas por una partida especial asignada por la Función Ejecutiva, a través de las Autoridades de Aplicación, a cuyos efectos queda facultado a realizar las adecuaciones necesarias de las partidas presupuestarias aprobadas en el Presupuesto General vigente.-"},{"n":354,"r":"APLICACIÓN DE MECANISMOS","t":"APLICACIÓN DE MECANISMOS. El Superior Tribunal de Justicia y la o el titular del Ministerio Público Fiscal impartirán los actos necesarios para la utilización y aplicación de los mecanismos y medios alternativos a fin de reducir la carga de trabajo existente en la circunscripción judicial a determinar, previo a la implementación progresiva.-"},{"n":355,"r":"TRANSFERENCIA DE EMPLEADOS","t":"TRANSFERENCIA DE EMPLEADOS. El Superior Tribunal de Justicia se encuentra facultado a tomar las medidas necesarias para la transferencia, con la correspondiente partida, a los Ministerios Públicos, de empleados y funcionarios que se desempeñan en los diferentes organismos de la circunscripción a su cargo y que sean necesarios, a efectos de implementar la presente Ley.-"},{"n":356,"r":"TRANSFERENCIA DE CARGOS Y CAMBIO DE FUNCIONES","t":"TRANSFERENCIA DE CARGOS Y CAMBIO DE FUNCIONES. Las y los funcionarios letrados de los Juzgados de Instrucción pasarán a ser funcionarios del Ministerio Público Fiscal y del Ministerio Público de la Defensa, gradualmente y de acuerdo a las circunscripciones que determine la Comisión de Implementación. El Superior Tribunal de Justicia y las o los titulares de los Ministerios Públicos dictarán los actos pertinentes a fin de transferir los cargos a los Ministerios Públicos y ordenarán los cambios de funciones y las licencias pertinentes al sólo efecto de facilitar la capacitación obligatoria integral e intensiva, procurando no resentir la normal prestación del servicio de Justicia; asimismo, podrá disponer del traslado de personas funcionarias o la modificación del horario laboral tendiente a esos fines. FUNCION LEGISLATIVA . Se arbitrarán los medios a fin de que los órganos de los Ministerios Públicos cuenten con lo necesario para el cumplimiento de sus funciones, con el objeto de salvaguardar las garantías constitucionales vigentes.- DISPOSICIONES TRANSITORIAS VII PLAN DE SANEAMIENTO DE EFECTOS"},{"n":357,"r":"SANEAMIENTO DE ELEMENTOS SECUESTRADOS","t":"SANEAMIENTO DE ELEMENTOS SECUESTRADOS. La Comisión de Implementación dictará un protocolo a los fines de aplicarlo a todos los efectos secuestrados y decomisados pertenecientes a aquellas actuaciones iniciadas con anterioridad a la entrada en vigencia del nuevo Sistema de Justicia Penal.-"},{"n":358,"r":"","t":"Deróganse la Ley N* 1.574 y sus modificatorias; y las Leyes N* 7.712, 8.093, 8.661 y 8.774, en lo que regulen sobre el Proceso Penal, y toda otra norma que se oponga a la presente.-"},{"n":359,"r":"","t":"Comuníquese, publíquese, insértese en el Registro Oficial y archívese.- Dada en la Sala de Sesiones de la Legislatura de la Provincia, en La Rioja, 140\" Período Legislativo, a quince días del mes de mayo del año dos mil veinticinco. Proyecto presentado por la FUNCIÓN EJECUTIVA.- L_E Y N\" 10.797.- FIRMADO: LIC. TERESITA LEONOR MADERA -— PRESIDENTA - CÁMARA DE DIPUTADOS DR. JUAN MANUEL ÁRTICO - SECRETARIO LEGISLATIVO LES PODIA E ARIOINA] | ES A], LEL UNI NAL: 14 0) RS A CATEDETAMÓÍNSA PRO-SECRETARIA LEGISLATIVA, FURCION LEGISLATIVA « LA RICUA"}]
;

/* ─────────────── índice de términos ─────────────── */
const VACIAS_BIB = new Set(('el la los las un una unos unas de del al a en con por para sin sobre se lo le les y o que qué es son ser sera será fue era este esta estos estas ese esa eso su sus como cuando donde cual cuales quien quienes mas más muy si no ni tambien también cada todo toda todos todas otro otra podra podrá podran podrán debera deberá deberan deberán caso casos forma parte partes ley articulo artículo inciso conforme respecto cuanto ademas además').split(' '));

const rz = w => {
  let x = String(w||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if (x.length > 4 && x.endsWith('es')) x = x.slice(0,-2);
  else if (x.length > 4 && x.endsWith('s')) x = x.slice(0,-1);
  return x.length > 7 ? x.slice(0,7) : x;
};
const termos = s => String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/[^a-z0-9ñ\s]/g,' ').split(/\s+/)
  .filter(w => w.length > 2 && !VACIAS_BIB.has(w)).map(rz);

let INDICE = null, IDF = null;
function indexar(){
  if (INDICE) return;
  INDICE = LEY_10797.map(a => {
    const tf = new Map();
    for (const t of termos(a.r + ' ' + a.t)) tf.set(t, (tf.get(t)||0) + 1);
    return { n:a.n, tf, largo: tf.size || 1 };
  });
  const df = new Map();
  for (const d of INDICE) for (const t of d.tf.keys()) df.set(t, (df.get(t)||0) + 1);
  const N = INDICE.length;
  IDF = new Map();
  for (const [t, f] of df) IDF.set(t, Math.log(1 + (N - f + 0.5) / (f + 0.5)));
}

/* ─────────────── consultas ─────────────── */

/** Devuelve un artículo por su número, o null. */
function articulo(n){
  const k = parseInt(n, 10);
  return LEY_10797.find(a => a.n === k) || null;
}

/** Busca los artículos más pertinentes a una consulta en lenguaje natural. */
function buscar(consulta, limite){
  indexar();
  const q = termos(consulta);
  if (!q.length) return [];
  const puntos = INDICE.map(d => {
    let s = 0;
    for (const t of q){
      const f = d.tf.get(t);
      if (!f) continue;
      s += (IDF.get(t) || 0) * (f * 2.2) / (f + 1.2 * (0.25 + 0.75 * d.largo / 40));
    }
    return { n: d.n, s };
  }).filter(x => x.s > 0).sort((a,b) => b.s - a.s).slice(0, limite || 5);
  return puntos.map(p => Object.assign({ score: Math.round(p.s*100)/100 }, articulo(p.n)));
}

/** Texto listo para inyectar en el contexto de un agente, con su cita. */
function contexto(numeros){
  return (numeros || []).map(n => {
    const a = articulo(n);
    return a ? `Art. ${a.n} ${a.r}. ${a.t}` : null;
  }).filter(Boolean).join('\n\n');
}

/** Fragmento textual para mostrar al usuario cuando toca una cita. */
function cita(n){
  const a = articulo(n);
  if (!a) return null;
  const estado = (typeof window !== 'undefined' && window.LEX && window.LEX.estadoArticulo)
    ? ' · ' + window.LEX.estadoArticulo(a.n) : '';
  return { numero:a.n, rubrica:a.r, texto:a.t,
           fuente:'Ley 10.797 — Código Procesal Penal de La Rioja' + estado };
}

/* ─────────────── verificación de citas ───────────────
   Se pasa por acá todo lo que generen los agentes y la devolución. Si una
   respuesta cita un artículo que no existe, o cita uno cuyo contenido no
   tiene nada que ver con lo que se está diciendo, se marca y se regenera. */

const RE_CITA = /\bart(?:[íi]culos?)?\.?\s*(\d{1,3})\b/gi;

function verificarCitas(texto, opciones){
  const o = opciones || {};
  const halladas = [];
  let m;
  const re = new RegExp(RE_CITA.source, RE_CITA.flags);
  while ((m = re.exec(texto)) !== null){
    const n = parseInt(m[1], 10);
    /* Primero: ¿está citando otra norma? El Código Penal y las leyes
       especiales no están en esta biblioteca y no se verifican acá.   */
    const cola = texto.slice(m.index, m.index + 70);
    if (/\bC\.?P\.?\b|C[oó]digo Penal|ley\s*\d|24\.?660|23\.?737|C\.?N\.?\b|Constituci[oó]n|CADH|Convenci[oó]n/i.test(cola)){
      halladas.push({ n, estado:'otra-norma', fragmento: m[0] });
      continue;
    }
    const a = articulo(n);
    if (!a){
      halladas.push({ n, estado:'inexistente', fragmento: m[0] });
      continue;
    }
    /* ¿El artículo citado tiene algo que ver con lo que se afirma? */
    const alrededor = texto.slice(Math.max(0, m.index - 220), m.index + 220);
    const tq = new Set(termos(alrededor));
    const ta = termos(a.r + ' ' + a.t.slice(0, 700));
    let comunes = 0;
    for (const t of new Set(ta)) if (tq.has(t)) comunes++;
    halladas.push({ n, estado: comunes >= 2 ? 'ok' : 'dudosa', rubrica: a.r, comunes });
  }
  const malas = halladas.filter(h => h.estado === 'inexistente');
  const dudosas = halladas.filter(h => h.estado === 'dudosa');
  return {
    citas: halladas,
    valido: malas.length === 0 && (o.estricto ? dudosas.length === 0 : true),
    inexistentes: malas.map(h => h.n),
    dudosas: dudosas.map(h => h.n)
  };
}

if (typeof window !== 'undefined'){
  window.LEX = Object.assign(window.LEX || {}, {
    LEY_10797, articulo, buscarLey: buscar, contextoLey: contexto, citaLey: cita, verificarCitas
  });
}
